        </form>

        <button 
          onClick={onBack}
          className="mt-6 text-sm font-medium text-neutral-500 hover:text-neutral-900 dark:hover:text-white transition-colors"
        >
          Voltar ao Catálogo
        </button>
      </div>
    </div>
  );
};

