import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [categories, setCategories] = useState<string[]>(() => {
    const saved = localStorage.getItem('categories');
    return saved ? JSON.parse(saved) : CATEGORIES;
  });

  const [variationPresets, setVariationPresets] = useState<VariationPreset[]>(() => {
    const saved = localStorage.getItem('variationPresets');
    return saved ? JSON.parse(saved) : [];
  });

  const [whatsappNumber, setWhatsappNumber] = useState<string>(() => {
    return localStorage.getItem('whatsappNumber') || '5500000000000';
  });

  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState('');

  useEffect(() => {
    localStorage.setItem('products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('categories', JSON.stringify(categories));
  }, [categories]);

  useEffect(() => {
    localStorage.setItem('variationPresets', JSON.stringify(variationPresets));
  }, [variationPresets]);

  useEffect(() => {
    localStorage.setItem('whatsappNumber', whatsappNumber);
  }, [whatsappNumber]);

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant) return;

    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) {
        return prev.map(item => 
          (item.productId === product.id && item.variantId === variantId) 
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      return [...prev, {
        productId: product.id,
        variantId,
        quantity: 1,
        productName: product.name,
        variantName: variant.name,
        price: variant.price
      }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) {
        return prev.map(item => 
          (item.productId === productId && item.variantId === variantId) 
            ? { ...item, quantity: item.quantity - 1 }
            : item
        );
      }
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const toggleProductStatus = (id: string) => {
    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: !p.isActive } : p));
  };

  const addProduct = (newProduct: Product) => {
    setProducts(prev => [...prev, newProduct]);
    setView('admin');
  };

  const handleSendWhatsApp = () => {
    if (!clientName) {
      alert('Por favor, insira seu nome antes de enviar o pedido.');
      return;
    }
    if (cart.length === 0) {
      alert('Seu carrinho está vazio.');
      return;
    }
    const cartText = cart.map(item => `*${item.quantity}x* ${item.productName}${item.variantName !== 'Padrão' ? ` (${item.variantName})` : ''} - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const message = `*Novo Pedido - Catálogo Digital*\n\n*Cliente:* ${clientName}\n\n*Itens:*\n${cartText}\n\n*Total:* R$ ${total.toFixed(2)}\n\n_Enviado via Catálogo Digital_`;

    const whatsappUrl = `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const handleOpenSettings = () => {
    if (isAuthenticated) {
      setView('admin');
    } else {
      setView('login');
    }
  };

  const handleLogin = (password: string) => {
    if (password === '233023') {
      setIsAuthenticated(true);
      setView('admin');
      return true;
    }
    return false;
  };

  return (
    <div className="min-h-screen flex flex-col">
      {view === 'catalog' && (
        <CatalogView 
          products={products.filter(p => p.isActive)} 
          categories={categories}
          cart={cart}
          addToCart={addToCart}
          removeFromCart={removeFromCart}
          clientName={clientName}
          setClientName={setClientName}
          onSendWhatsApp={handleSendWhatsApp}
          onOpenSettings={handleOpenSettings}
        />
      )}

      {view === 'login' && (
        <LoginView 
          onLogin={handleLogin}
          onBack={() => setView('catalog')}
        />
      )}

      {view === 'admin' && (
        <AdminView 
          products={products}
          whatsappNumber={whatsappNumber}
          setWhatsappNumber={setWhatsappNumber}
          onToggleStatus={toggleProductStatus}
          onAddProduct={() => setView('add-product')}
          onOpenCategories={() => setView('edit-categories')}
          onOpenVariations={() => setView('edit-variations')}
          onBack={() => setView('catalog')}
          onLogout={() => {
            setIsAuthenticated(false);
            setView('catalog');
          }}
        />
      )}

      {view === 'add-product' && (
        <AddProductForm 
          categories={categories}
          onSave={addProduct}
          onCancel={() => setView('admin')}
        />
      )}

      {view === 'edit-categories' && (
        <EditCategoriesView 
          categories={categories}
          setCategories={setCategories}
          onBack={() => setView('admin')}
        />
      )}

      {view === 'edit-variations' && (
        <EditVariationsView 
          presets={variationPresets}
          setPresets={setVariationPresets}
          onBack={() => setView('admin')}
        />
      )}
    </div>
  );
};

