import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  productToEdit: Product | null;
  onSave: (product: Product) => void;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants);
    }
  }, [productToEdit]);

  const handleAddVariant = () => {
    setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }]);
  };

  const handleVariantChange = (id: string, field: keyof ProductVariant, value: any) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, [field]: value } : v));
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length > 1) {
      setVariants(variants.filter(v => v.id !== id));
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${Math.random().toString(36).substring(2)}.${fileExt}`;
      const filePath = `products/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage
        .from('product-images')
        .getPublicUrl(filePath);

      setImage(data.publicUrl);
    } catch (error: any) {
      console.error('Erro no upload:', error.message);
      alert('Erro ao fazer upload da imagem. Verifique se o bucket "product-images" é público no Supabase.');
    } finally {
      setIsUploading(false);
    }
  };

  const handleSubmit = () => {
    if (!name || !category) {
      alert('Nome e Categoria são obrigatórios.');
      return;
    }

    const updatedProduct: Product = {
      id: productToEdit ? productToEdit.id : Math.random().toString(36).substr(2, 9),
      name,
      category,
      description,
      image: image || 'https://picsum.photos/400/300',
      isActive: productToEdit ? productToEdit.isActive : true,
      variants
    };

    onSave(updatedProduct);
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen relative pb-32 text-neutral-900 dark:text-neutral-50">
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b border-border-light dark:border-border-dark px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition-colors -ml-2">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar Produto' : 'Adicionar Produto'}</h1>
      </div>

      <div className="px-4 pt-6 flex flex-col gap-6">
        <div className="bg-surface-light dark:bg-surface-dark rounded-xl border border-border-light dark:border-border-dark p-5 shadow-sm">
          <h2 className="text-base font-bold mb-4 flex items-center gap-2">
            <span className="material-symbols-outlined text-primary">edit_note</span>
            Detalhes Básicos
          </h2>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-text-sub dark:text-gray-400 mb-1.5">Nome do Produto</label>
              <input 
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="block w-full rounded-lg border-border-light dark:border-border-dark bg-background-light dark:bg-background-dark py-3 px-3.5 text-sm focus:border-primary focus:ring-primary outline-none" 
                placeholder="Ex: Coca-Cola 2L" 
                type="text"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-text-sub dark:text-gray-400 mb-1.5">Categoria</label>
              <select 
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                className="block w-full appearance-none rounded-lg border-border-light dark:border-border-dark bg-background-light dark:bg-background-dark py-3 px-3.5 text-sm focus:border-primary focus:ring-primary pr-10 outline-none"
              >
                <option value="">Selecione uma categoria</option>
                {categories.map(cat => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-text-sub dark:text-gray-400 mb-1.5">Descrição</label>
              <textarea 
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                className="block w-full rounded-lg border-border-light dark:border-border-dark bg-background-light dark:bg-background-dark py-3 px-3.5 text-sm focus:border-primary focus:ring-primary h-20 resize-none outline-none" 
                placeholder="Ex: Bebida refrescante, servir gelado..."
              />
            </div>
          </div>
        </div>

        <div className="bg-surface-light dark:bg-surface-dark rounded-xl border border-border-light dark:border-border-dark p-5 shadow-sm">
          <h2 className="text-base font-bold mb-4 flex items-center gap-2">
            <span className="material-symbols-outlined text-primary">image</span>
            Mídia do Produto
          </h2>
          <div className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-text-sub dark:text-gray-400 mb-1.5 uppercase tracking-wider">URL da Imagem (Link Direto)</label>
              <input 
                value={image}
                onChange={(e) => setImage(e.target.value)}
                className="block w-full rounded-lg border-border-light dark:border-border-dark bg-background-light dark:bg-background-dark py-2 px-3 text-xs focus:border-primary focus:ring-primary outline-none mb-3" 
                placeholder="Cole o link da imagem aqui..." 
                type="text"
              />
            </div>
            <div className="flex gap-4 items-center">
              <input 
                type="file" 
                accept="image/*" 
                className="hidden" 
                ref={fileInputRef} 
                onChange={handleImageUpload}
              />
              <button 
                onClick={() => fileInputRef.current?.click()}
                disabled={isUploading}
                className={`shrink-0 w-24 h-24 rounded-xl border-2 border-dashed border-primary/40 bg-primary/5 hover:bg-primary/10 flex flex-col items-center justify-center gap-1 transition-colors group ${isUploading ? 'opacity-50' : ''}`}
              >
                {isUploading ? (
                  <div className="w-5 h-5 border-2 border-primary border-t-transparent rounded-full animate-spin"></div>
                ) : (
                  <>
                    <span className="material-symbols-outlined text-primary group-hover:scale-110 transition-transform">upload_file</span>
                    <span className="text-[10px] font-bold text-primary">Upload</span>
                  </>
                )}
              </button>
              {image && (
                <div className="relative w-24 h-24 rounded-xl border border-border-light dark:border-border-dark overflow-hidden bg-neutral-100">
                  <img src={image} alt="Preview" className="w-full h-full object-cover" />
                  <button onClick={() => setImage('')} className="absolute top-1 right-1 bg-black/50 text-white rounded-full p-0.5">
                    <span className="material-symbols-outlined text-xs">close</span>
                  </button>
                </div>
              )}
            </div>
            <p className="text-[10px] text-text-sub dark:text-gray-500 italic">Dica: Use links diretos (terminados em .jpg, .png) ou faça o upload.</p>
          </div>
        </div>

        <div className="bg-surface-light dark:bg-surface-dark rounded-xl border border-border-light dark:border-border-dark p-5 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-base font-bold flex items-center gap-2">
              <span className="material-symbols-outlined text-primary">layers</span>
              Preços e Variações
            </h2>
            <button 
              onClick={handleAddVariant}
              className="text-xs font-bold text-primary px-3 py-1.5 rounded-lg bg-primary/5 hover:bg-primary/10 transition-colors flex items-center gap-1"
            >
              <span className="material-symbols-outlined text-sm">add</span> Add
            </button>
          </div>

          <div className="space-y-3">
            {variants.map((variant) => (
              <div key={variant.id} className="flex gap-2 items-start p-3 bg-background-light dark:bg-background-dark rounded-xl border border-border-light dark:border-border-dark">
                <div className="flex-1 space-y-2">
                  <input 
                    value={variant.name}
                    onChange={(e) => handleVariantChange(variant.id, 'name', e.target.value)}
                    placeholder="Nome (Ex: Padrão, 1kg, 500ml)"
                    className="w-full rounded-lg border-border-light dark:border-border-dark bg-white dark:bg-black/20 px-3 py-2 text-xs outline-none"
                  />
                  <div className="flex items-center gap-2">
                    <div className="relative flex-1">
                      <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[10px] text-text-sub font-bold">R$</span>
                      <input 
                        type="number"
                        value={variant.price}
                        onChange={(e) => handleVariantChange(variant.id, 'price', parseFloat(e.target.value) || 0)}
                        className="w-full rounded-lg border-border-light dark:border-border-dark bg-white dark:bg-black/20 pl-8 pr-3 py-2 text-xs outline-none"
                      />
                    </div>
                  </div>
                </div>
                {variants.length > 1 && (
                  <button onClick={() => handleRemoveVariant(variant.id)} className="p-1 text-red-400 hover:text-red-500">
                    <span className="material-symbols-outlined text-sm">delete</span>
                  </button>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 w-full z-40 bg-surface-light dark:bg-surface-dark border-t border-border-light dark:border-border-dark p-4 max-w-lg mx-auto left-1/2 -translate-x-1/2">
        <div className="flex gap-3">
          <button 
            onClick={onCancel}
            className="flex-1 py-4 px-6 border border-border-light dark:border-border-dark rounded-2xl font-bold text-sm"
          >
            Cancelar
          </button>
          <button 
            onClick={handleSubmit}
            className="flex-2 py-4 px-10 bg-primary hover:bg-primary-dark text-neutral-900 font-bold rounded-2xl shadow-lg shadow-primary/20 transition-all active:scale-95"
          >
            Salvar
          </button>
        </div>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState } from 'react';
import { Product, CartItem } from '../types';

interface CatalogViewProps {
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: () => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;
  const isOrderValid = cart.length > 0 && isNameValid;

  const getQuantity = (pId: string, vId: string) => {
    return cart.find(item => item.productId === pId && item.variantId === vId)?.quantity || 0;
  };

  const currentDate = new Date().toLocaleDateString('pt-BR');
  const currentTime = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });

  return (
    <div className="flex-1 w-full max-w-md mx-auto bg-background-light dark:bg-background-dark min-h-screen flex flex-col">
      {/* Header */}
      <header className="sticky top-0 z-50 w-full bg-background-light/90 dark:bg-background-dark/90 backdrop-blur-md shadow-sm border-b border-neutral-200 dark:border-white/5">
        <div className="flex items-center justify-between p-4">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-primary/20 text-primary-700 dark:text-primary">
              <span className="material-symbols-outlined text-[24px]">storefront</span>
            </div>
            <h1 className="text-neutral-900 dark:text-white text-lg font-bold">Catálogo Digital</h1>
          </div>
          <button onClick={onOpenSettings} className="flex h-10 w-10 items-center justify-center rounded-full text-neutral-500 hover:bg-neutral-100 dark:text-neutral-400 dark:hover:bg-white/10">
            <span className="material-symbols-outlined text-[24px]">settings</span>
          </button>
        </div>
      </header>

      <main className="flex-1 pb-60 px-4 pt-6">
        {/* Categorias */}
        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-6 -mx-4 px-4">
          {['Todas', ...categories].map(cat => (
            <button 
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`shrink-0 px-4 py-2 rounded-full text-sm font-bold transition-all ${
                selectedCategory === cat 
                  ? 'bg-primary text-neutral-900 shadow-sm' 
                  : 'bg-white dark:bg-white/5 text-neutral-600 dark:text-neutral-300 border border-neutral-200 dark:border-white/10'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* Lista de Produtos */}
        <div className="flex flex-col gap-6">
          {filteredProducts.map(product => {
            const activeVariants = product.variants.filter(v => v.isActive);
            if (activeVariants.length === 0) return null;

            return (
              <article key={product.id} className="group overflow-hidden rounded-2xl bg-white dark:bg-white/5 p-3 shadow-sm border border-neutral-100 dark:border-white/5">
                <div className="flex flex-col gap-3">
                  <div className="relative h-44 w-full overflow-hidden rounded-xl bg-neutral-100 dark:bg-neutral-800">
                    <img 
                      src={product.image} 
                      alt={product.name}
                      className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
                      onError={(e) => { (e.target as HTMLImageElement).src = 'https://picsum.photos/400/300?grayscale'; }}
                    />
                    <div className="absolute top-2 right-2 bg-black/60 backdrop-blur-md text-white px-2 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider">
                      {product.category}
                    </div>
                  </div>

                  <div className="flex flex-col w-full px-1">
                    <h3 className="text-base font-bold text-neutral-900 dark:text-white">{product.name}</h3>
                    <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-1 line-clamp-2">{product.description}</p>

                    <div className="mt-4 space-y-3">
                      {activeVariants.map((variant) => {
                        const qty = getQuantity(product.id, variant.id);
                        const isMulti = activeVariants.length > 1;

                        return (
                          <div key={variant.id} className="flex items-center justify-between gap-4">
                            <div className="flex flex-col">
                              {isMulti && <span className="text-xs font-bold text-neutral-500">{variant.name}</span>}
                              <span className="text-base font-extrabold text-primary-dark dark:text-primary">R$ {variant.price.toFixed(2)}</span>
                            </div>

                            <div className="flex items-center bg-neutral-100 dark:bg-black/30 rounded-full p-1">
                              {qty > 0 ? (
                                <>
                                  <button 
                                    onClick={() => removeFromCart(product.id, variant.id)}
                                    className="h-9 w-9 flex items-center justify-center rounded-full bg-white dark:bg-neutral-700 shadow-sm active:scale-95"
                                  >
                                    <span className="material-symbols-outlined text-[20px]">remove</span>
                                  </button>
                                  <span className="w-8 text-center text-sm font-bold">{qty}</span>
                                  <button 
                                    onClick={() => addToCart(product, variant.id)}
                                    className="h-9 w-9 flex items-center justify-center rounded-full bg-primary text-black shadow-sm active:scale-95"
                                  >
                                    <span className="material-symbols-outlined text-[20px]">add</span>
                                  </button>
                                </>
                              ) : (
                                <button 
                                  onClick={() => addToCart(product, variant.id)}
                                  className="flex h-9 px-4 items-center gap-1 rounded-full text-xs font-bold transition hover:bg-primary/10"
                                >
                                  <span className="material-symbols-outlined text-[18px]">add</span> Adicionar
                                </button>
                              )}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              </article>
            );
          })}
        </div>

        {/* Cupom Fiscal do Carrinho */}
        {cart.length > 0 && (
          <div className="mt-12 mb-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="bg-[#fff] text-neutral-800 p-6 shadow-xl rounded-sm border-t-4 border-primary relative overflow-hidden font-mono text-[11px] leading-relaxed">
              <div className="absolute top-0 left-0 w-full flex justify-around -mt-2">
                {[...Array(20)].map((_, i) => (
                  <div key={i} className="w-4 h-4 bg-background-light dark:bg-background-dark rounded-full"></div>
                ))}
              </div>

              <div className="text-center mb-4 space-y-1">
                <h3 className="text-sm font-bold uppercase tracking-widest">RESUMO DO PEDIDO</h3>
                <p className="opacity-50">---------------------------------</p>
                <div className="flex justify-between text-[10px]">
                  <span>{currentDate}</span>
                  <span>{currentTime}</span>
                </div>
              </div>

              <div className="space-y-2 mb-6">
                <div className="flex justify-between font-bold border-b border-neutral-200 pb-1 mb-2">
                  <span className="w-8">QTD</span>
                  <span className="flex-1 px-2">ITEM</span>
                  <span className="text-right">VALOR</span>
                </div>
                {cart.map(item => (
                  <div key={`${item.productId}-${item.variantId}`} className="flex justify-between items-start">
                    <span className="w-8 font-bold">{item.quantity}x</span>
                    <span className="flex-1 px-2 uppercase truncate">
                      {item.productName} 
                      {item.variantName !== 'Padrão' && <span className="block text-[9px] opacity-60">({item.variantName})</span>}
