          <div className="flex items-center justify-between bg-background-light dark:bg-black/20 rounded-xl p-3 border border-border-light dark:border-white/5">
            <div className="flex items-center gap-3">
               <span className="material-symbols-outlined text-green-500">brand_awareness</span>
               {isEditingPhone ? (
                 <input 
