                            <span className={`text-[9px] ${v.isActive ? 'text-primary' : 'text-neutral-500'}`}>R$ {v.price.toFixed(2)}</span>
                          </div>
                          <div className={`w-5 h-5 rounded-full flex items-center justify-center transition-colors ${v.isActive ? 'bg-primary text-black' : 'bg-neutral-200 dark:bg-neutral-700 text-neutral-500'}`}>
                            <span className="material-symbols-outlined text-xs font-black">
                              {v.isActive ? 'check' : 'close'}
                            </span>
                          </div>
                        </button>
                      ))}
                    </div>
                  </div>
