export type AppView = 'catalog' | 'admin' | 'add-product' | 'edit-product' | 'login' | 'edit-categories' | 'edit-variations';

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, VariationPreset, ProductVariant } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [variationPresets, setVariationPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  // Carregamento Inicial do Banco
  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        // Tenta buscar ordenando por order_index
        const { data: dbProducts, error: pError } = await supabase
          .from('products')
          .select('*')
          .order('order_index', { ascending: true });

        if (dbProducts && dbProducts.length > 0) {
          const normalized = dbProducts.map(p => ({
            ...p,
            isActive: p.is_active ?? p.isActive ?? true,
            variants: (p.variants || []).map((v: any) => ({
              ...v,
              isActive: v.is_active ?? v.isActive ?? true
            }))
          }));
          setProducts(normalized);
        } else {
          // Fallback para produtos iniciais caso o banco esteja vazio ou dê erro de coluna inexistente
          const initialWithOrder = INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i }));
          setProducts(initialWithOrder);
        }

        const { data: dbSettings } = await supabase.from('settings').select('*');
        if (dbSettings) {
          const cats = dbSettings.find(s => s.key === 'categories')?.value;
          const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
          const presets = dbSettings.find(s => s.key === 'presets')?.value;

          if (cats) setCategories(cats);
          if (wa) setWhatsappNumber(wa);
          if (presets) setVariationPresets(presets);
        }
      } catch (err) {
        console.error("Erro ao buscar dados do Supabase:", err);
        setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  const updateSetting = async (key: string, value: any) => {
    await supabase.from('settings').upsert({ key, value });
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;

    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) {
        return prev.map(item => 
          (item.productId === product.id && item.variantId === variantId) 
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      return [...prev, {
        productId: product.id,
        variantId,
        quantity: 1,
        productName: product.name,
        variantName: variant.name,
        price: variant.price
      }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) {
        return prev.map(item => 
          (item.productId === productId && item.variantId === variantId) 
            ? { ...item, quantity: item.quantity - 1 }
            : item
        );
      }
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;

    const newStatus = !product.isActive;
    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));

    await supabase
      .from('products')
      .update({ is_active: newStatus })
      .eq('id', id);
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;

    const updatedVariants = product.variants.map(v => 
      v.id === variantId ? { ...v, isActive: !v.isActive } : v
    );

    const updatedProduct = { ...product, variants: updatedVariants };
    setProducts(prev => prev.map(p => p.id === productId ? updatedProduct : p));

    await supabase
      .from('products')
      .update({ variants: updatedVariants })
      .eq('id', productId);
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    if (direction === 'up' && index === 0) return;
    if (direction === 'down' && index === products.length - 1) return;

    const newProducts = [...products];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    [newProducts[index], newProducts[targetIndex]] = [newProducts[targetIndex], newProducts[index]];

    const withIndices = newProducts.map((p, i) => ({ ...p, order_index: i }));
    setProducts(withIndices);

    await Promise.all([
      supabase.from('products').update({ order_index: index }).eq('id', newProducts[index].id),
      supabase.from('products').update({ order_index: targetIndex }).eq('id', newProducts[targetIndex].id)
    ]);
  };

  const saveProduct = async (product: Product) => {
    setIsLoading(true);
    try {
      const orderIndex = productToEdit?.order_index !== undefined ? productToEdit.order_index : products.length;
      const { error } = await supabase.from('products').upsert({
        id: product.id,
        name: product.name,
        description: product.description,
        image: product.image,
        category: product.category,
        is_active: product.isActive,
        variants: product.variants,
        order_index: orderIndex
      });

      if (!error) {
        if (productToEdit) {
          setProducts(prev => prev.map(p => p.id === product.id ? { ...product, order_index: orderIndex } : p));
        } else {
          setProducts(prev => [...prev, { ...product, order_index: orderIndex }]);
        }
      }
    } finally {
      setProductToEdit(null);
      setIsLoading(false);
      setView('admin');
    }
  };

  const handleEditProduct = (product: Product) => {
    setProductToEdit(product);
    setView('edit-product');
  };

  const handleUpdateWhatsapp = async (num: string) => {
    setWhatsappNumber(num);
    await updateSetting('whatsapp', num);
  };

  const handleUpdateCategories = async (newCats: string[] | ((prev: string[]) => string[])) => {
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated);
    await updateSetting('categories', updated);
  };

  const handleUpdatePresets = async (newPresets: VariationPreset[] | ((prev: VariationPreset[]) => VariationPreset[])) => {
    const updated = typeof newPresets === 'function' ? newPresets(variationPresets) : newPresets;
    setVariationPresets(updated);
    await updateSetting('presets', updated);
  };

  const handleSendWhatsApp = () => {
    if (!clientName || clientName.trim().length < 3) {
      alert('Por favor, insira seu nome (mínimo 3 letras) antes de enviar o pedido.');
      return;
    }
    if (cart.length === 0) {
      alert('Seu carrinho está vazio.');
      return;
    }

    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName}${item.variantName !== 'Padrão' ? ` (${item.variantName})` : ''} - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

    const message = `*NOVO PEDIDO - CATÁLOGO*\n\n` +
                    `👤 *Cliente:* ${clientName}\n\n` +
                    `🛒 *Itens:*\n${cartText}\n\n` +
                    `💰 *Total:* R$ ${total.toFixed(2)}\n\n` +
                    `⚠️ _Pedido sujeito a disponibilidade de estoque._`;

    const whatsappUrl = `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const handleOpenSettings = () => {
    if (isAuthenticated) {
      setView('admin');
    } else {
      setView('login');
    }
  };

  const handleLogin = (password: string) => {
    if (password === '233023') {
      setIsAuthenticated(true);
      setView('admin');
      return true;
    }
    return false;
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <h2 className="text-xl font-bold animate-pulse-soft">Carregando catálogo...</h2>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories}
              cart={cart}
              addToCart={addToCart}
              removeFromCart={removeFromCart}
              clientName={clientName}
              setClientName={setClientName}
              onSendWhatsApp={handleSendWhatsApp}
              onOpenSettings={handleOpenSettings}
            />
          )}

          {view === 'login' && (
            <LoginView 
              onLogin={handleLogin}
              onBack={() => setView('catalog')}
            />
          )}

          {view === 'admin' && (
            <AdminView 
              products={products}
              whatsappNumber={whatsappNumber}
              setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus}
              onToggleVariantStatus={toggleVariantStatus}
              onReorderProduct={handleReorderProduct}
              onAddProduct={() => {
                setProductToEdit(null);
                setView('add-product');
              }}
              onEditProduct={handleEditProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onBack={() => setView('catalog')}
              onLogout={() => {
                setIsAuthenticated(false);
                setView('catalog');
              }}
            />
          )}

          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories}
              productToEdit={productToEdit}
              onSave={saveProduct}
              onCancel={() => {
                setProductToEdit(null);
                setView('admin');
              }}
            />
          )}

          {view === 'edit-categories' && (
            <EditCategoriesView 
              categories={categories}
              setCategories={handleUpdateCategories}
              onBack={() => setView('admin')}
            />
          )}

          {view === 'edit-variations' && (
            <EditVariationsView 
              presets={variationPresets}
              setPresets={handleUpdatePresets}
              onBack={() => setView('admin')}
            />
          )}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Product, CartItem } from '../types';

interface CatalogViewProps {
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: () => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;
  const isOrderValid = cart.length > 0 && isNameValid;

  const getQuantity = (pId: string, vId: string) => {
    return cart.find(item => item.productId === pId && item.variantId === vId)?.quantity || 0;
  };

  const currentDate = new Date().toLocaleDateString('pt-BR');
  const currentTime = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });

  return (
    <div className="flex-1 w-full max-w-md mx-auto bg-background-light dark:bg-background-dark min-h-screen flex flex-col">
      {/* Header */}
      <header className="sticky top-0 z-50 w-full bg-background-light/90 dark:bg-background-dark/90 backdrop-blur-md shadow-sm border-b border-neutral-200 dark:border-white/5">
        <div className="flex items-center justify-between p-4">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-primary/20 text-primary-700 dark:text-primary">
              <span className="material-symbols-outlined text-[24px]">storefront</span>
            </div>
            <h1 className="text-neutral-900 dark:text-white text-lg font-bold">Catálogo Digital</h1>
          </div>
          <button onClick={onOpenSettings} className="flex h-10 w-10 items-center justify-center rounded-full text-neutral-500 hover:bg-neutral-100 dark:text-neutral-400 dark:hover:bg-white/10">
            <span className="material-symbols-outlined text-[24px]">settings</span>
          </button>
        </div>
      </header>

      <main className="flex-1 pb-60 px-4 pt-6">
        {/* Categorias */}
        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-6 -mx-4 px-4">
          {['Todas', ...categories].map(cat => (
            <button 
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`shrink-0 px-4 py-2 rounded-full text-sm font-bold transition-all ${
                selectedCategory === cat 
                  ? 'bg-primary text-neutral-900 shadow-sm' 
                  : 'bg-white dark:bg-white/5 text-neutral-600 dark:text-neutral-300 border border-neutral-200 dark:border-white/10'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* Lista de Produtos */}
        <div className="flex flex-col gap-6">
          {filteredProducts.map(product => {
            // Garante que variants seja um array e filtra as ativas de forma resiliente
            const variantsArray = Array.isArray(product.variants) ? product.variants : [];
            const activeVariants = variantsArray.filter(v => v.isActive === true);

            // Se não houver variantes ativas, o produto não aparece no catálogo
            if (activeVariants.length === 0) return null;

            return (
              <article key={product.id} className="group overflow-hidden rounded-2xl bg-white dark:bg-white/5 p-3 shadow-sm border border-neutral-100 dark:border-white/5">
                <div className="flex flex-col gap-3">
                  {/* Image Container with Fixed Aspect Ratio */}
                  <div className="relative aspect-video w-full overflow-hidden rounded-xl bg-neutral-100 dark:bg-neutral-800 shadow-inner">
                    <img 
                      src={product.image || 'https://picsum.photos/400/300?grayscale'} 
                      alt={product.name}
                      className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
                      onError={(e) => { (e.target as HTMLImageElement).src = 'https://picsum.photos/400/300?grayscale'; }}
                    />
                    <div className="absolute top-2 right-2 bg-black/60 backdrop-blur-md text-white px-2 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider">
                      {product.category}
                    </div>
                  </div>

                  <div className="flex flex-col w-full px-1">
                    <h3 className="text-base font-bold text-neutral-900 dark:text-white">{product.name}</h3>
                    {product.description && <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-1 line-clamp-2">{product.description}</p>}

                    <div className="mt-4 space-y-3">
                      {activeVariants.map((variant) => {
                        const qty = getQuantity(product.id, variant.id);
                        const isMulti = activeVariants.length > 1;

                        return (
                          <div key={variant.id} className="flex items-center justify-between gap-4">
                            <div className="flex flex-col">
                              {isMulti && <span className="text-xs font-bold text-neutral-500">{variant.name}</span>}
                              <span className="text-base font-extrabold text-primary-dark dark:text-primary">R$ {Number(variant.price).toFixed(2)}</span>
                            </div>

                            <div className="flex items-center bg-neutral-100 dark:bg-black/30 rounded-full p-1">
                              {qty > 0 ? (
                                <>
                                  <button 
                                    onClick={() => removeFromCart(product.id, variant.id)}
                                    className="h-9 w-9 flex items-center justify-center rounded-full bg-white dark:bg-neutral-700 shadow-sm active:scale-95"
                                  >
                                    <span className="material-symbols-outlined text-[20px]">remove</span>
                                  </button>
                                  <span className="w-8 text-center text-sm font-bold">{qty}</span>
                                  <button 
                                    onClick={() => addToCart(product, variant.id)}
                                    className="h-9 w-9 flex items-center justify-center rounded-full bg-primary text-black shadow-sm active:scale-95"
                                  >
                                    <span className="material-symbols-outlined text-[20px]">add</span>
                                  </button>
                                </>
                              ) : (
                                <button 
                                  onClick={() => addToCart(product, variant.id)}
                                  className="flex h-9 px-4 items-center gap-1 rounded-full text-xs font-bold transition hover:bg-primary/10"
                                >
                                  <span className="material-symbols-outlined text-[18px]">add</span> Adicionar
                                </button>
                              )}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              </article>
            );
          })}
        </div>

        {/* Cupom Fiscal do Carrinho */}
        {cart.length > 0 && (
          <div className="mt-12 mb-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="bg-[#fff] text-neutral-800 p-6 shadow-xl rounded-sm border-t-4 border-primary relative overflow-hidden font-mono text-[11px] leading-relaxed">
              <div className="absolute top-0 left-0 w-full flex justify-around -mt-2">
                {[...Array(20)].map((_, i) => (
                  <div key={i} className="w-4 h-4 bg-background-light dark:bg-background-dark rounded-full"></div>
                ))}
              </div>

              <div className="text-center mb-4 space-y-1">
                <h3 className="text-sm font-bold uppercase tracking-widest">RESUMO DO PEDIDO</h3>
                <p className="opacity-50">---------------------------------</p>
                <div className="flex justify-between text-[10px]">
                  <span>{currentDate}</span>
                  <span>{currentTime}</span>
                </div>
              </div>

              <div className="space-y-2 mb-6">
                <div className="flex justify-between font-bold border-b border-neutral-200 pb-1 mb-2">
                  <span className="w-8">QTD</span>
                  <span className="flex-1 px-2">ITEM</span>
                  <span className="text-right">VALOR</span>
                </div>
                {cart.map(item => (
                  <div key={`${item.productId}-${item.variantId}`} className="flex justify-between items-start">
                    <span className="w-8 font-bold">{item.quantity}x</span>
                    <span className="flex-1 px-2 uppercase truncate">
                      {item.productName} 
                      {item.variantName !== 'Padrão' && <span className="block text-[9px] opacity-60">({item.variantName})</span>}
                    </span>
                    <span className="text-right whitespace-nowrap">R$ {(item.price * item.quantity).toFixed(2)}</span>
                  </div>
                ))}
              </div>

              <div className="border-t border-dashed border-neutral-400 pt-4 space-y-2">
                <div className="flex justify-between text-sm font-bold">
                  <span>TOTAL GERAL</span>
                  <span className="text-base">R$ {total.toFixed(2)}</span>
                </div>

                <div className="bg-neutral-100 p-2 rounded text-center font-bold text-red-600 text-[10px] mt-4 uppercase">
                  ⚠️ Pedido sujeito a disponibilidade de estoque
                </div>
              </div>

              <div className="absolute bottom-0 left-0 w-full flex justify-around -mb-2">
                {[...Array(20)].map((_, i) => (
                  <div key={i} className="w-4 h-4 bg-background-light dark:bg-background-dark rounded-full"></div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Identificação OBRIGATÓRIA */}
        <div className="mt-8 mb-10 p-4 bg-white dark:bg-white/5 rounded-2xl border border-neutral-100 dark:border-white/10 shadow-sm">
          <label className="block text-xs font-bold uppercase text-neutral-500 dark:text-neutral-400 mb-3 tracking-wider">
            Identificação do Cliente <span className="text-red-500">*</span>
          </label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 flex items-center pl-4 pointer-events-none text-neutral-400">
              <span className="material-symbols-outlined text-xl">person</span>
            </div>
            <input 
              value={clientName}
              onChange={(e) => setClientName(e.target.value)}
              className={`w-full bg-neutral-50 dark:bg-black/20 border ${!isNameValid && clientName.length > 0 ? 'border-red-500' : 'border-neutral-200 dark:border-white/10'} text-neutral-900 dark:text-white rounded-xl py-3.5 pl-11 pr-4 outline-none focus:ring-2 focus:ring-primary focus:border-transparent transition-all placeholder:text-neutral-400`} 
              placeholder="Digite seu nome completo..." 
              required
              type="text"
            />
          </div>
          {!isNameValid && (
            <p className="text-[10px] font-bold text-red-500 mt-2 px-1 flex items-center gap-1">
              <span className="material-symbols-outlined text-xs">error</span>
              Mínimo de 3 caracteres necessário para liberar o envio.
            </p>
          )}
        </div>
      </main>

      {/* Barra de Ação Fixa */}
      <div className="fixed bottom-0 left-0 w-full z-50 p-4">
        <div className="absolute bottom-0 left-0 w-full h-44 bg-gradient-to-t from-background-light via-background-light/95 to-transparent dark:from-background-dark dark:via-background-dark/95 pointer-events-none"></div>
        <div className="relative w-full max-w-md mx-auto space-y-3">

          {cart.length > 0 && (
            <div className="bg-white/90 dark:bg-black/60 backdrop-blur-sm p-3 rounded-2xl border border-neutral-200 dark:border-white/5 shadow-lg flex items-center justify-between">
              <div className="flex flex-col">
                <span className="text-[10px] font-bold text-neutral-500 uppercase">Seu Total</span>
                <span className="text-lg font-black text-neutral-900 dark:text-white">R$ {total.toFixed(2)}</span>
              </div>
              <div className="text-[9px] font-bold text-red-500 max-w-[150px] leading-tight text-right uppercase">
                Estoque sujeito a confirmação 📦
              </div>
            </div>
          )}

          <button 
            onClick={onSendWhatsApp}
            disabled={!isOrderValid}
            className={`w-full ${!isOrderValid ? 'bg-neutral-300 dark:bg-neutral-700 cursor-not-allowed text-neutral-500' : 'bg-primary hover:bg-[#0fd651] shadow-xl shadow-primary/20 text-neutral-900 active:scale-[0.98]'} transition-all duration-300 font-bold text-lg rounded-2xl py-4 flex items-center justify-center gap-3`}
          >
