            Cancelar
          </button>
          <button 
            onClick={handleSubmit}
            disabled={isUploading}
            className={`flex-2 py-4 px-10 ${isUploading ? 'bg-neutral-400' : 'bg-primary hover:bg-primary-dark'} text-neutral-900 font-bold rounded-2xl shadow-lg shadow-primary/20 transition-all active:scale-95`}
          >
            {isUploading ? 'Enviando...' : 'Salvar Produto'}
          </button>
        </div>
      </div>
    </div>
  );
