      alert('Seu carrinho está vazio.');
      return;
    }

    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName}${item.variantName !== 'Padrão' ? ` (${item.variantName})` : ''} - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

    const message = `*NOVO PEDIDO - CATÁLOGO*\n\n` +
                    `👤 *Cliente:* ${clientName}\n\n` +
                    `🛒 *Itens:*\n${cartText}\n\n` +
                    `💰 *Total:* R$ ${total.toFixed(2)}\n\n` +
                    `⚠️ _Pedido sujeito a disponibilidade de estoque._`;

    const whatsappUrl = `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const handleOpenSettings = () => {
    if (isAuthenticated) {
      setView('admin');
    } else {
      setView('login');
    }
  };

  const handleLogin = (password: string) => {
    if (password === '233023') {
      setIsAuthenticated(true);
      setView('admin');
      return true;
    }
    return false;
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <h2 className="text-xl font-bold animate-pulse-soft">Sincronizando banco de dados...</h2>
          <p className="text-sm text-neutral-500 mt-2">Isso pode levar alguns segundos.</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories}
              cart={cart}
              addToCart={addToCart}
              removeFromCart={removeFromCart}
              clientName={clientName}
              setClientName={setClientName}
              onSendWhatsApp={handleSendWhatsApp}
              onOpenSettings={handleOpenSettings}
            />
          )}

          {view === 'login' && (
            <LoginView 
              onLogin={handleLogin}
              onBack={() => setView('catalog')}
            />
          )}

          {view === 'admin' && (
            <AdminView 
              products={products}
              whatsappNumber={whatsappNumber}
              setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus}
              onToggleVariantStatus={toggleVariantStatus}
              onReorderProduct={handleReorderProduct}
              onAddProduct={() => {
                setProductToEdit(null);
                setView('add-product');
              }}
              onEditProduct={handleEditProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onBack={() => setView('catalog')}
              onLogout={() => {
                setIsAuthenticated(false);
                setView('catalog');
              }}
            />
          )}

          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories}
              productToEdit={productToEdit}
              onSave={saveProduct}
              onCancel={() => {
                setProductToEdit(null);
                setView('admin');
              }}
            />
          )}

          {view === 'edit-categories' && (
            <EditCategoriesView 
              categories={categories}
              setCategories={handleUpdateCategories}
              onBack={() => setView('admin')}
            />
          )}

          {view === 'edit-variations' && (
            <EditVariationsView 
              presets={variationPresets}
              setPresets={handleUpdatePresets}
              onBack={() => setView('admin')}
            />
          )}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  productToEdit: Product | null;
  onSave: (product: Product) => void;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({...v, price: Number(v.price)})));
    }
  }, [productToEdit]);

  const handleAddVariant = () => {
    setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }]);
  };

  const handleVariantChange = (id: string, field: keyof ProductVariant, value: any) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, [field]: value } : v));
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length > 1) {
      setVariants(variants.filter(v => v.id !== id));
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;
      const filePath = `products/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('product-images')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage
        .from('product-images')
        .getPublicUrl(filePath);

      setImage(data.publicUrl);
    } catch (error: any) {
      console.error('Erro no upload:', error);
      alert('Erro ao fazer upload da imagem. Usando link local de fallback.');
    } finally {
      setIsUploading(false);
    }
  };

  const handleSubmit = () => {
    if (!name.trim() || !category) {
      alert('Por favor, preencha o Nome e selecione uma Categoria.');
      return;
    }

    // Garante que os preços são números e não há campos vazios
    const cleanVariants = variants.map(v => ({
      ...v,
      id: v.id || Date.now().toString(),
      price: Number(v.price) || 0,
      name: v.name.trim() || 'Padrão',
      isActive: true
    }));

    const updatedProduct: Product = {
      // Se for novo, gera um ID numérico em string para maior compatibilidade com bancos legados
      id: productToEdit ? productToEdit.id : String(Date.now()), 
      name: name.trim(),
      category,
      description: description.trim(),
      image: image.trim() || 'https://picsum.photos/400/300?random=' + Date.now(),
      isActive: productToEdit ? productToEdit.isActive : true,
      variants: cleanVariants
    };

    onSave(updatedProduct);
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen relative pb-32 text-neutral-900 dark:text-neutral-50">
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b border-border-light dark:border-border-dark px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition-colors -ml-2">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar Produto' : 'Novo Produto'}</h1>
      </div>

      <div className="px-4 pt-6 flex flex-col gap-6">
        {/* Sessão de Nome e Categoria */}
        <div className="bg-surface-light dark:bg-surface-dark rounded-xl border border-border-light dark:border-border-dark p-5 shadow-sm">
          <h2 className="text-base font-bold mb-4 flex items-center gap-2">
            <span className="material-symbols-outlined text-primary">edit_note</span>
            Informações
          </h2>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-text-sub dark:text-gray-400 mb-1.5">Nome</label>
              <input 
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="block w-full rounded-lg border-border-light dark:border-border-dark bg-background-light dark:bg-background-dark py-3 px-3.5 text-sm focus:border-primary focus:ring-primary outline-none" 
                placeholder="Ex: Batata Frita Média" 
                type="text"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-text-sub dark:text-gray-400 mb-1.5">Categoria</label>
              <select 
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                className="block w-full appearance-none rounded-lg border-border-light dark:border-border-dark bg-background-light dark:bg-background-dark py-3 px-3.5 text-sm focus:border-primary focus:ring-primary pr-10 outline-none"
              >
                <option value="">Escolha...</option>
                {categories.map(cat => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* Sessão de Imagem */}
        <div className="bg-surface-light dark:bg-surface-dark rounded-xl border border-border-light dark:border-border-dark p-5 shadow-sm">
          <h2 className="text-base font-bold mb-4 flex items-center gap-2">
            <span className="material-symbols-outlined text-primary">image</span>
            Imagem do Produto
          </h2>
          <div className="space-y-4">
            {image ? (
              <div className="relative w-full aspect-video rounded-2xl border-2 border-primary/20 overflow-hidden bg-neutral-100 shadow-lg group">
                <img src={image} alt="Preview" className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-3">
                  <button onClick={() => fileInputRef.current?.click()} className="bg-white text-black px-4 py-2 rounded-xl text-xs font-bold shadow-xl active:scale-95 transition-transform">Trocar</button>
                  <button onClick={() => setImage('')} className="bg-red-500 text-white px-4 py-2 rounded-xl text-xs font-bold shadow-xl active:scale-95 transition-transform">Excluir</button>
                </div>
              </div>
            ) : (
              <div 
                onClick={() => fileInputRef.current?.click()}
                className={`w-full aspect-video rounded-2xl border-2 border-dashed ${isUploading ? 'border-primary' : 'border-neutral-300 dark:border-white/10'} bg-neutral-50 dark:bg-black/20 flex flex-col items-center justify-center gap-3 cursor-pointer hover:border-primary transition-all group`}
              >
                {isUploading ? (
                  <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
                ) : (
                  <>
                    <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center text-primary">
                      <span className="material-symbols-outlined text-3xl">add_a_photo</span>
                    </div>
                    <p className="text-sm font-bold">Enviar Foto ou Cole o Link abaixo</p>
                  </>
                )}
              </div>
            )}

            <div>
              <label className="block text-xs font-bold text-text-sub dark:text-gray-400 mb-1.5 uppercase tracking-wider">Link Direto da Imagem (URL)</label>
              <input 
                value={image}
                onChange={(e) => setImage(e.target.value)}
                className="block w-full rounded-lg border-border-light dark:border-border-dark bg-background-light dark:bg-background-dark py-3 px-3 text-xs focus:border-primary focus:ring-primary outline-none" 
                placeholder="https://exemplo.com/foto-do-produto.jpg" 
                type="text"
              />
            </div>

            <input type="file" accept="image/*" className="hidden" ref={fileInputRef} onChange={handleImageUpload} />
          </div>
        </div>

        {/* Preços */}
        <div className="bg-surface-light dark:bg-surface-dark rounded-xl border border-border-light dark:border-border-dark p-5 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-base font-bold flex items-center gap-2">
              <span className="material-symbols-outlined text-primary">payments</span>
              Preços e Pesos
            </h2>
            <button onClick={handleAddVariant} className="text-xs font-bold text-primary px-3 py-1.5 rounded-lg bg-primary/5 hover:bg-primary/10">+ Add</button>
          </div>

          <div className="space-y-3">
            {variants.map((variant) => (
              <div key={variant.id} className="flex gap-2 items-start p-3 bg-background-light dark:bg-background-dark rounded-xl border border-border-light dark:border-border-dark">
                <div className="flex-1 space-y-2">
                  <input 
                    value={variant.name}
                    onChange={(e) => handleVariantChange(variant.id, 'name', e.target.value)}
                    placeholder="Descrição (ex: 500g, 1L, Média)"
                    className="w-full rounded-lg border-border-light dark:border-border-dark bg-white dark:bg-black/20 px-3 py-2 text-xs outline-none"
                  />
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[10px] text-text-sub font-bold">R$</span>
                    <input 
                      type="number"
                      step="0.01"
                      value={variant.price || ''}
                      onChange={(e) => handleVariantChange(variant.id, 'price', e.target.value)}
                      className="w-full rounded-lg border-border-light dark:border-border-dark bg-white dark:bg-black/20 pl-8 pr-3 py-2 text-xs outline-none"
                    />
                  </div>
                </div>
                {variants.length > 1 && (
                  <button onClick={() => handleRemoveVariant(variant.id)} className="p-1 text-red-400">
                    <span className="material-symbols-outlined text-sm">delete</span>
                  </button>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 w-full z-40 bg-surface-light dark:bg-surface-dark border-t border-border-light dark:border-border-dark p-4 max-w-lg mx-auto left-1/2 -translate-x-1/2">
        <div className="flex gap-3">
          <button onClick={onCancel} className="flex-1 py-4 border border-border-light dark:border-border-dark rounded-2xl font-bold text-sm">Cancelar</button>
          <button 
            onClick={handleSubmit} 
            disabled={isUploading}
            className="flex-[2] py-4 bg-primary text-neutral-900 font-bold rounded-2xl shadow-lg shadow-primary/20 active:scale-95 transition-all disabled:opacity-50"
          >
            {isUploading ? 'Subindo Imagem...' : 'Salvar Produto'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, VariationPreset, ProductVariant } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [variationPresets, setVariationPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      // Tenta buscar com ordem primeiro
      let { data: dbProducts, error: pError } = await supabase
        .from('products')
        .select('*')
        .order('order_index', { ascending: true });

      // Se der erro de coluna inexistente (42703), tenta sem ordem
      if (pError && pError.code === '42703') {
         const { data, error } = await supabase.from('products').select('*');
         dbProducts = data;
         pError = error;
      }

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (p.variants || []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));
        setProducts(normalized);
      } else {
        // Se banco vazio, usa iniciais
        setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const presets = dbSettings.find(s => s.key === 'presets')?.value;

        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (presets) setVariationPresets(presets);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const updateSetting = async (key: string, value: any) => {
    try {
      await supabase.from('settings').upsert({ key, value });
    } catch (e) {
      console.error("Erro ao salvar config:", e);
    }
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;

    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) {
        return prev.map(item => 
          (item.productId === product.id && item.variantId === variantId) 
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      return [...prev, {
        productId: product.id,
        variantId,
        quantity: 1,
        productName: product.name,
        variantName: variant.name,
        price: variant.price
      }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) {
        return prev.map(item => 
          (item.productId === productId && item.variantId === variantId) 
            ? { ...item, quantity: item.quantity - 1 }
            : item
        );
      }
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;

    const newStatus = !product.isActive;
    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));

    // Tenta snake_case primeiro
    const { error } = await supabase.from('products').update({ is_active: newStatus }).eq('id', id);
    if (error) {
       // Tenta camelCase como fallback
       await supabase.from('products').update({ isActive: newStatus }).eq('id', id);
    }
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;

    const updatedVariants = product.variants.map(v => 
      v.id === variantId ? { ...v, isActive: !v.isActive } : v
    );

    const updatedProduct = { ...product, variants: updatedVariants };
    setProducts(prev => prev.map(p => p.id === productId ? updatedProduct : p));

    await supabase.from('products').update({ variants: updatedVariants }).eq('id', productId);
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    if (direction === 'up' && index === 0) return;
    if (direction === 'down' && index === products.length - 1) return;

    const newProducts = [...products];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    [newProducts[index], newProducts[targetIndex]] = [newProducts[targetIndex], newProducts[index]];

    const withIndices = newProducts.map((p, i) => ({ ...p, order_index: i }));
    setProducts(withIndices);

    await supabase.from('products').update({ order_index: targetIndex }).eq('id', id);
  };

  const saveProduct = async (product: Product) => {
    setIsLoading(true);
    try {
      const orderIndex = productToEdit?.order_index !== undefined 
        ? productToEdit.order_index 
        : products.length;

      // Criamos um payload limpo (sem undefined)
      const payload: any = {
        id: product.id,
        name: product.name,
        description: product.description || "",
        image: product.image,
        category: product.category,
        variants: JSON.parse(JSON.stringify(product.variants)), // Deep copy para evitar problemas de referência
        is_active: product.isActive,
        order_index: orderIndex
      };

      console.log("Tentando salvar produto:", payload);

      // Tenta o upsert completo
      let { error } = await supabase.from('products').upsert(payload);

      // Fallback 1: Erro de coluna (42703) - tenta remover campos possivelmente inexistentes
      if (error && error.code === '42703') {
        console.warn("Detectada coluna inexistente, tentando salvar sem order_index e is_active...");
        const fallbackPayload = { ...payload };
        delete fallbackPayload.order_index;
        delete fallbackPayload.is_active;
        fallbackPayload.isActive = product.isActive; // Tenta versão camelCase

        const retry = await supabase.from('products').upsert(fallbackPayload);
        error = retry.error;
      }

      if (error) {
        console.error("Erro completo do Supabase:", error);
        // Extrai a mensagem real do erro para evitar o [object Object]
        const errorMessage = error.message || "Erro desconhecido";
        const errorDetails = error.details || "";
        const errorHint = error.hint || "";

        throw new Error(`${errorMessage} ${errorDetails} ${errorHint}`);
      }

      // Atualiza estado local apenas se salvou no banco
      const updatedProduct = { ...product, order_index: orderIndex };
      if (productToEdit) {
        setProducts(prev => prev.map(p => p.id === product.id ? updatedProduct : p));
      } else {
        setProducts(prev => [...prev, updatedProduct]);
      }

      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      console.error("Erro fatal ao salvar produto:", err);
      // Se 'err' for uma string ou tiver .message, usamos isso. Caso contrário, stringify.
      const msg = err.message || (typeof err === 'object' ? JSON.stringify(err) : String(err));
      alert(`ERRO AO CADASTRAR:\n${msg}\n\nVerifique as colunas da sua tabela 'products'.`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleEditProduct = (product: Product) => {
    setProductToEdit(product);
    setView('edit-product');
  };

  const handleUpdateWhatsapp = async (num: string) => {
    setWhatsappNumber(num);
    await updateSetting('whatsapp', num);
  };

  const handleUpdateCategories = async (newCats: string[] | ((prev: string[]) => string[])) => {
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated);
    await updateSetting('categories', updated);
  };

  const handleUpdatePresets = async (newPresets: VariationPreset[] | ((prev: VariationPreset[]) => VariationPreset[])) => {
    const updated = typeof newPresets === 'function' ? newPresets(variationPresets) : newPresets;
