    const newProducts = [...products];
    [newProducts[index], newProducts[targetIndex]] = [newProducts[targetIndex], newProducts[index]];

    const withIndices = newProducts.map((p, i) => ({ ...p, order_index: i }));
    setProducts(withIndices);

    try {
      await supabase.from('products').update({ order_index: targetIndex }).eq('id', id);
    } catch (e) {
      console.warn("Ordenação persistente não suportada pelo banco.");
    }
  };

  const saveProduct = async (product: Product) => {
    setIsLoading(true);
    try {
      const orderIndex = productToEdit?.order_index !== undefined 
        ? productToEdit.order_index 
        : products.length;

      const variantsClean = JSON.parse(JSON.stringify(product.variants));

      // Definição dos campos básicos (essenciais)
      const baseFields = {
        id: product.id,
        name: product.name,
        description: product.description || "",
        image: product.image,
        category: product.category,
        variants: variantsClean
      };

      console.log("Iniciando salvamento adaptativo multi-nível...");

      // TENTA NÍVEL 1: Tudo (is_active + order_index)
      let { error } = await supabase.from('products').upsert({
        ...baseFields,
        is_active: product.isActive,
        order_index: orderIndex
      });

      // SE NÍVEL 1 FALHAR: Tenta NÍVEL 2 (Apenas is_active)
      if (error && (error.code === '42703' || error.code === 'PGRST204' || error.message?.includes('order_index'))) {
        console.warn("Falha no Nível 1. Tentando Nível 2 (sem order_index)...");
        const retry1 = await supabase.from('products').upsert({
          ...baseFields,
          is_active: product.isActive
        });
        error = retry1.error;
      }

      // SE NÍVEL 2 FALHAR: Tenta NÍVEL 3 (Apenas isActive em camelCase)
      if (error && (error.code === '42703' || error.code === 'PGRST204' || error.message?.includes('is_active'))) {
        console.warn("Falha no Nível 2. Tentando Nível 3 (isActive camelCase)...");
        const retry2 = await supabase.from('products').upsert({
          ...baseFields,
          isActive: product.isActive
        });
        error = retry2.error;
      }

      // SE NÍVEL 3 FALHAR: Tenta NÍVEL 4 (Mínimo absoluto - Sem status nem ordem)
      if (error && (error.code === '42703' || error.code === 'PGRST204' || error.message?.includes('isActive'))) {
        console.warn("Falha no Nível 3. Tentando Nível 4 (MVP absoluto)...");
        const retry3 = await supabase.from('products').upsert(baseFields);
        error = retry3.error;
      }

      if (error) {
        const errDetails = {
          message: error.message,
          code: error.code,
          hint: error.hint
        };
        throw new Error(JSON.stringify(errDetails, null, 2));
      }

      // SUCESSO: Atualiza estado local
      const updatedProduct = { ...product, order_index: orderIndex };
      if (productToEdit) {
        setProducts(prev => prev.map(p => p.id === product.id ? updatedProduct : p));
      } else {
        setProducts(prev => [...prev, updatedProduct]);
      }

      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      console.error("Erro crítico no salvamento:", err);
      const msg = err.message || String(err);
      alert(`ERRO AO SALVAR:\n${msg}\n\nO produto pode não ter sido salvo permanentemente.`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleEditProduct = (product: Product) => {
    setProductToEdit(product);
    setView('edit-product');
  };

  const handleUpdateWhatsapp = async (num: string) => {
    setWhatsappNumber(num);
    await updateSetting('whatsapp', num);
  };

  const handleUpdateCategories = async (newCats: string[] | ((prev: string[]) => string[])) => {
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated);
    await updateSetting('categories', updated);
  };

  const handleUpdatePresets = async (newPresets: VariationPreset[] | ((prev: VariationPreset[]) => VariationPreset[])) => {
    const updated = typeof newPresets === 'function' ? newPresets(variationPresets) : newPresets;
    setVariationPresets(updated);
    await updateSetting('presets', updated);
  };

  const handleSendWhatsApp = () => {
    if (!clientName || clientName.trim().length < 3) {
      alert('Por favor, insira seu nome (mínimo 3 letras) antes de enviar o pedido.');
      return;
    }
    if (cart.length === 0) {
      alert('Seu carrinho está vazio.');
      return;
    }

    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName}${item.variantName !== 'Padrão' ? ` (${item.variantName})` : ''} - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

    const message = `*NOVO PEDIDO - CATÁLOGO*\n\n` +
                    `👤 *Cliente:* ${clientName}\n\n` +
                    `🛒 *Itens:*\n${cartText}\n\n` +
                    `💰 *Total:* R$ ${total.toFixed(2)}\n\n` +
                    `⚠️ _Pedido sujeito a disponibilidade de estoque._`;

    const whatsappUrl = `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const handleOpenSettings = () => {
    if (isAuthenticated) {
      setView('admin');
    } else {
      setView('login');
    }
  };

  const handleLogin = (password: string) => {
    if (password === '233023') {
      setIsAuthenticated(true);
      setView('admin');
      return true;
    }
    return false;
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <h2 className="text-xl font-bold animate-pulse-soft">Sincronizando Banco de Dados...</h2>
          <p className="text-sm text-neutral-500 mt-2">Isso garante que seu estoque esteja atualizado.</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories}
              cart={cart}
              addToCart={addToCart}
              removeFromCart={removeFromCart}
              clientName={clientName}
              setClientName={setClientName}
              onSendWhatsApp={handleSendWhatsApp}
              onOpenSettings={handleOpenSettings}
            />
          )}

          {view === 'login' && (
            <LoginView 
              onLogin={handleLogin}
              onBack={() => setView('catalog')}
            />
          )}

          {view === 'admin' && (
            <AdminView 
              products={products}
              whatsappNumber={whatsappNumber}
              setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus}
              onToggleVariantStatus={toggleVariantStatus}
              onReorderProduct={handleReorderProduct}
              onAddProduct={() => {
                setProductToEdit(null);
                setView('add-product');
              }}
              onEditProduct={handleEditProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onBack={() => setView('catalog')}
              onLogout={() => {
                setIsAuthenticated(false);
                setView('catalog');
              }}
            />
          )}

          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories}
              productToEdit={productToEdit}
              onSave={saveProduct}
              onCancel={() => {
                setProductToEdit(null);
                setView('admin');
              }}
            />
          )}

          {view === 'edit-categories' && (
            <EditCategoriesView 
              categories={categories}
              setCategories={handleUpdateCategories}
              onBack={() => setView('admin')}
            />
          )}

          {view === 'edit-variations' && (
            <EditVariationsView 
              presets={variationPresets}
              setPresets={handleUpdatePresets}
              onBack={() => setView('admin')}
            />
          )}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, VariationPreset, ProductVariant } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [variationPresets, setVariationPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let dbProducts: any[] | null = null;
      let pError: any = null;

      // Tenta carregar produtos com ordenação
      try {
        const { data, error } = await supabase.from('products').select('*').order('order_index', { ascending: true });
        dbProducts = data;
        pError = error;
      } catch (e) { pError = e; }

      // Se der erro de coluna (ordem ou schema), tenta busca simples
      if (pError && (pError.code === 'PGRST204' || pError.code === '42703' || pError.message?.includes('order_index'))) {
        const { data, error } = await supabase.from('products').select('*');
        dbProducts = data;
        pError = error;
      }

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));
        setProducts(normalized);
      } else {
        setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
      }

      // Carrega Configurações
      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const presets = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (presets) setVariationPresets(presets);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const saveProduct = async (product: Product) => {
    setIsLoading(true);
    try {
      const orderIndex = productToEdit?.order_index !== undefined ? productToEdit.order_index : products.length;

      // Payload inicial completo
      let payload: any = {
        id: product.id,
        name: product.name,
        description: product.description || "",
        image: product.image,
        category: product.category,
        variants: JSON.parse(JSON.stringify(product.variants)),
        is_active: product.isActive,
        order_index: orderIndex
      };

      // Função de tentativa recursiva para auto-correção de colunas
      const attemptUpsert = async (currentPayload: any): Promise<any> => {
        const { error } = await supabase.from('products').upsert(currentPayload);

        if (error) {
          // Se o erro for de coluna inexistente (PGRST204 ou 42703)
          if (error.code === 'PGRST204' || error.code === '42703' || error.message.includes('column')) {
            // Tenta extrair o nome da coluna da mensagem: "Could not find the 'column_name' column..."
            const match = error.message.match(/'([^']+)'/);
            const offendingColumn = match ? match[1] : null;

            if (offendingColumn && currentPayload.hasOwnProperty(offendingColumn)) {
              console.warn(`Removendo coluna inexistente do payload: ${offendingColumn}`);
              const newPayload = { ...currentPayload };
              delete newPayload[offendingColumn];
              return attemptUpsert(newPayload); // Tenta novamente sem a coluna problemática
            }

            // Fallback agressivo se não encontrar o nome da coluna no erro
            if (currentPayload.order_index !== undefined) {
              const p = { ...currentPayload }; delete p.order_index; return attemptUpsert(p);
            }
            if (currentPayload.is_active !== undefined) {
              const p = { ...currentPayload }; delete p.is_active; return attemptUpsert(p);
            }
          }
          return error;
        }
        return null;
      };

      const error = await attemptUpsert(payload);

      if (error) {
        throw new Error(`Erro Supabase: ${error.message} (Código: ${error.code})`);
      }

      // Atualiza localmente
      const updatedProduct = { ...product, order_index: orderIndex };
      setProducts(prev => {
        const exists = prev.find(p => p.id === product.id);
        if (exists) return prev.map(p => p.id === product.id ? updatedProduct : p);
        return [...prev, updatedProduct];
      });

      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      alert(`FALHA AO SALVAR:\n${err.message || 'Erro desconhecido'}`);
    } finally {
      setIsLoading(false);
    }
  };

  // Funções de apoio
  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStatus = !product.isActive;
    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));
    try {
      await supabase.from('products').update({ is_active: newStatus }).eq('id', id);
    } catch (e) {}
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;
    const newProducts = [...products];
    [newProducts[index], newProducts[targetIndex]] = [newProducts[targetIndex], newProducts[index]];
    setProducts(newProducts.map((p, i) => ({ ...p, order_index: i })));
    try { await supabase.from('products').update({ order_index: targetIndex }).eq('id', id); } catch (e) {}
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;
    const updatedVariants = product.variants.map(v => v.id === variantId ? { ...v, isActive: !v.isActive } : v);
    setProducts(prev => prev.map(p => p.id === productId ? { ...product, variants: updatedVariants } : p));
    await supabase.from('products').update({ variants: updatedVariants }).eq('id', productId);
  };

  const updateSetting = async (key: string, value: any) => {
    try { await supabase.from('settings').upsert({ key, value }); } catch (e) {}
  };

  const handleUpdateWhatsapp = async (num: string) => { setWhatsappNumber(num); await updateSetting('whatsapp', num); };
  const handleUpdateCategories = async (newCats: any) => { 
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated); await updateSetting('categories', updated); 
  };
  const handleUpdatePresets = async (newPresets: any) => {
    const updated = typeof newPresets === 'function' ? newPresets(variationPresets) : newPresets;
    setVariationPresets(updated); await updateSetting('presets', updated);
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) return prev.map(item => (item.productId === product.id && item.variantId === variantId) ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, variantId, quantity: 1, productName: product.name, variantName: variant.name, price: variant.price }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) return prev.map(item => (item.productId === productId && item.variantId === variantId) ? { ...item, quantity: item.quantity - 1 } : item);
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const handleSendWhatsApp = () => {
    if (!clientName || clientName.trim().length < 3) { alert('Insira seu nome.'); return; }
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName}) - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold animate-pulse">Sincronizando com Supabase...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} addToCart={addToCart} removeFromCart={removeFromCart}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus} onToggleVariantStatus={toggleVariantStatus} onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onOpenCategories={() => setView('edit-categories')} onOpenVariations={() => setView('edit-variations')}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && <AddProductForm categories={categories} productToEdit={productToEdit} onSave={saveProduct} onCancel={() => setView('admin')} />}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} setCategories={handleUpdateCategories} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={variationPresets} setPresets={handleUpdatePresets} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  productToEdit: Product | null;
  onSave: (product: Product) => void;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({...v, price: Number(v.price)})));
    }
  }, [productToEdit]);

  const handleAddVariant = () => {
    setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }]);
  };

  const handleVariantChange = (id: string, field: keyof ProductVariant, value: any) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, [field]: value } : v));
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage.from('product-images').upload(`products/${fileName}`, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
    } catch (error: any) {
      alert('Erro no upload. Tente colar um link direto da imagem.');
    } finally { setIsUploading(false); }
  };

  const handleSubmit = () => {
    if (!name.trim() || !category) { alert('Nome e Categoria são obrigatórios.'); return; }
    const cleanVariants = variants.map(v => ({ ...v, price: Number(v.price) || 0, name: v.name || 'Padrão' }));
    onSave({
      id: productToEdit ? productToEdit.id : String(Date.now()), 
      name: name.trim(), category, description: description.trim(),
      image: image.trim() || 'https://picsum.photos/400/300?random=' + Date.now(),
      isActive: productToEdit ? productToEdit.isActive : true,
      variants: cleanVariants
    });
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b border-border-light dark:border-border-dark px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5"><span className="material-symbols-outlined">arrow_back</span></button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar Produto' : 'Novo Produto'}</h1>
      </div>

      <div className="px-4 pt-6 flex flex-col gap-6">
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div>
            <label className="block text-sm font-bold mb-1.5">Nome do Produto</label>
            <input value={name} onChange={(e) => setName(e.target.value)} className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm focus:ring-primary focus:border-primary" placeholder="Ex: Coca-Cola 2L" />
          </div>
          <div>
            <label className="block text-sm font-bold mb-1.5">Categoria</label>
            <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm">
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
