              <div className="flex items-center gap-1 font-bold text-sm">R$ <input type="number" value={v.price} onChange={(e) => handleVariantChange(v.id, 'price', e.target.value)} className="w-20 bg-transparent border-none p-0 focus:ring-0" /></div>
