      <div className="fixed bottom-0 w-full p-4 bg-white dark:bg-surface-dark border-t border-border-light dark:border-border-dark flex gap-3 max-w-lg mx-auto left-1/2 -translate-x-1/2">
        <button onClick={onCancel} className="flex-1 py-4 font-bold rounded-2xl border border-border-light">Cancelar</button>
        <button onClick={handleSubmit} className="flex-[2] py-4 bg-primary text-black font-bold rounded-2xl shadow-lg active:scale-95 transition-all">Salvar Produto</button>
