                    </div>
                  </div>

                  <div className="bg-background-light dark:bg-black/20 rounded-xl p-3 border border-border-light dark:border-white/5">
                    <div className="flex items-center justify-between mb-3">
                      <span className="text-[9px] font-black uppercase text-neutral-400 dark:text-neutral-500 tracking-widest">Disponibilidade</span>
                    </div>
                    <div className="grid grid-cols-2 gap-2">
