                        <button key={v.id} disabled={!product.isActive} onClick={() => onToggleVariantStatus(product.id, v.id)} className={`flex items-center justify-between px-3 py-2.5 rounded-lg border text-[11px] font-bold transition-all active:scale-[0.97] ${v.isActive ? 'bg-white dark:bg-neutral-800 border-primary/20 text-neutral-900 dark:text-white shadow-sm' : 'bg-neutral-100 dark:bg-neutral-900/50 border-transparent text-neutral-400 line-through'} ${!product.isActive ? 'opacity-50 cursor-not-allowed' : ''}`}>
