                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full bg-surface-light dark:bg-surface-dark border-t border-border-light dark:border-border-dark z-50 px-6 py-4 flex items-center justify-around shadow-2xl">
        <button onClick={onBack} className="flex flex-col items-center gap-1 text-neutral-400"><span className="material-symbols-outlined">shopping_bag</span><span className="text-[9px] font-black uppercase">Loja</span></button>
