import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  productToEdit: Product | null;
  onSave: (product: Product) => void;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({...v, price: Number(v.price)})));
    }
  }, [productToEdit]);

  const handleAddVariant = () => {
    setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }]);
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length <= 1) {
      alert('O produto precisa ter pelo menos um preço/variação.');
      return;
    }
    setVariants(prev => prev.filter(v => v.id !== id));
  };

  const handleVariantChange = (id: string, field: keyof ProductVariant, value: any) => {
    setVariants(prev => prev.map(v => {
      if (v.id === id) {
        const newValue = field === 'price' ? (value === '' ? 0 : parseFloat(value)) : value;
        return { ...v, [field]: newValue };
      }
      return v;
    }));
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage.from('product-images').upload(`products/${fileName}`, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
    } catch (error: any) {
      alert('Erro no upload. Tente colar um link direto da imagem.');
    } finally { setIsUploading(false); }
  };

  const handleSubmit = () => {
    if (!name.trim() || !category) { alert('Nome e Marca são obrigatórios.'); return; }
    const cleanVariants = variants.map(v => ({ ...v, price: Number(v.price) || 0, name: v.name || 'Padrão' }));
    onSave({
      id: productToEdit ? productToEdit.id : String(Date.now()), 
      name: name.trim(), category, description: description.trim(),
      image: image.trim() || 'https://picsum.photos/400/300?random=' + Date.now(),
      isActive: productToEdit ? productToEdit.isActive : true,
      variants: cleanVariants
    });
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b border-border-light dark:border-border-dark px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5"><span className="material-symbols-outlined">arrow_back</span></button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar Produto' : 'Novo Produto'}</h1>
      </div>

      <div className="px-4 pt-6 flex flex-col gap-6">
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div>
            <label className="block text-sm font-bold mb-1.5">Nome do Produto</label>
            <input value={name} onChange={(e) => setName(e.target.value)} className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm focus:ring-primary focus:border-primary" placeholder="Ex: Coca-Cola 2L" />
          </div>
          <div>
            <label className="block text-sm font-bold mb-1.5">Marca</label>
            <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm">
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <h2 className="text-sm font-bold flex items-center gap-2"><span className="material-symbols-outlined text-primary">image</span> Imagem do Produto</h2>
          <div className="p-3 bg-primary/5 rounded-xl border border-primary/20">
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest">Link Direto (HTML / URL)</label>
            <input value={image} onChange={(e) => setImage(e.target.value)} className="w-full rounded-lg border-primary/30 bg-white dark:bg-black/40 p-3 text-xs focus:ring-primary focus:border-primary font-mono" placeholder="https://exemplo.com/imagem.png" />
          </div>
          <div className="relative group">
