import React, { useState, useRef } from 'react';
import { Product, CartItem } from '../types';

declare var html2canvas: any;

interface CatalogViewProps {
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: (paymentMethod: string) => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');
  const [paymentMethod, setPaymentMethod] = useState<'Pix' | 'Dinheiro'>('Dinheiro');
  const [isProcessing, setIsProcessing] = useState(false);
  const receiptRef = useRef<HTMLDivElement>(null);

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;
  const isOrderValid = cart.length > 0 && isNameValid;

  const getQuantity = (pId: string, vId: string) => {
    return cart.find(item => item.productId === pId && item.variantId === vId)?.quantity || 0;
  };

  const handleConfirmOrder = async () => {
    if (!isOrderValid) return;

    setIsProcessing(true);

    try {
      // Pequeno delay para garantir que o DOM está pronto e renderizado
      await new Promise(r => setTimeout(r, 300));

      if (receiptRef.current && navigator.share) {
        const canvas = await html2canvas(receiptRef.current, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          logging: false
        });

        const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));

        if (blob) {
          const file = new File([blob], `pedido-${Date.now()}.png`, { type: 'image/png' });

          const cartText = cart.map(item => `• ${item.quantity}x ${item.productName} (${item.variantName})`).join('\n');
          const shareData = {
            title: 'Novo Pedido',
            text: `*NOVO PEDIDO*\n👤 Cliente: ${clientName}\n💳 Pagamento: ${paymentMethod}\n💰 Total: R$ ${total.toFixed(2)}\n\n🛒 Itens:\n${cartText}`,
            files: [file]
          };

          if (navigator.canShare && navigator.canShare(shareData)) {
            await navigator.share(shareData);
            setIsProcessing(false);
            return;
          }
        }
      }

      // Fallback para o método de texto padrão se o compartilhamento de arquivo falhar ou não existir
      onSendWhatsApp(paymentMethod);
    } catch (err) {
      console.error("Erro ao gerar/compartilhar cupom:", err);
      onSendWhatsApp(paymentMethod); // Fallback silencioso
    } finally {
      setIsProcessing(false);
    }
  };

  const currentDate = new Date().toLocaleDateString('pt-BR');
  const currentTime = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });

  return (
    <div className="flex-1 w-full max-md:max-w-md mx-auto bg-background-light dark:bg-background-dark min-h-screen flex flex-col text-neutral-900 dark:text-neutral-50">
      {isProcessing && (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center p-6 text-white">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-black text-lg uppercase tracking-widest animate-pulse">Gerando Cupom...</p>
          <p className="text-xs opacity-70 mt-2">Estamos preparando o print do seu pedido</p>
        </div>
      )}

      {/* Header */}
      <header className="sticky top-0 z-50 w-full bg-background-light/90 dark:bg-background-dark/90 backdrop-blur-md shadow-sm border-b border-neutral-200 dark:border-white/5">
        <div className="flex items-center justify-between p-4">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-primary/20 text-primary-700 dark:text-primary">
              <span className="material-symbols-outlined text-[24px]">storefront</span>
            </div>
            <h1 className="text-neutral-900 dark:text-white text-lg font-bold">Catálogo Digital</h1>
          </div>
          <button onClick={onOpenSettings} className="flex h-10 w-10 items-center justify-center rounded-full text-neutral-500 hover:bg-neutral-100 dark:text-neutral-400 dark:hover:bg-white/10">
