                              <div className={`w-4 h-4 shrink-0 rounded-full flex items-center justify-center transition-colors ${v.isActive ? 'bg-primary text-black' : 'bg-neutral-200 dark:bg-neutral-700 text-neutral-500'}`}>
                                <span className="material-symbols-outlined text-[10px] font-black">{v.isActive ? 'check' : 'close'}</span>
                              </div>
                            </button>
                          ))}
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full bg-surface-light dark:bg-surface-dark border-t border-border-light dark:border-border-dark z-50 px-6 py-4 flex items-center justify-around shadow-2xl">
        <button onClick={onBack} className="flex flex-col items-center gap-1 text-neutral-400">
          <span className="material-symbols-outlined">shopping_bag</span>
          <span className="text-[9px] font-black uppercase">Loja</span>
        </button>
        <button onClick={onAddProduct} className="w-14 h-14 bg-primary text-black rounded-2xl shadow-xl shadow-primary/30 flex items-center justify-center -mt-10 hover:scale-110 active:scale-95 transition-all">
          <span className="material-symbols-outlined text-3xl font-black">add</span>
        </button>
        <button onClick={onLogout} className="flex flex-col items-center gap-1 text-red-400">
          <span className="material-symbols-outlined">logout</span>
          <span className="text-[9px] font-black uppercase">Sair</span>
        </button>
      </div>
    </div>
  );
};

export default AdminView;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  productToEdit: Product | null;
  onSave: (product: Product) => void;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({...v, price: Number(v.price)})));
    }
  }, [productToEdit]);

  const handleApplyPreset = (preset: VariationPreset) => {
    // Substitui as variações atuais pelas do preset (gerando novos IDs para evitar conflitos)
    const newVariants = preset.variants.map(v => ({
      ...v,
      id: Math.random().toString(36).substr(2, 9)
    }));
    setVariants(newVariants);
    setShowPresets(false);
  };

  const handleAddVariant = () => {
    setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }]);
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length <= 1) {
      alert('O produto precisa ter pelo menos um preço/variação.');
      return;
    }
    setVariants(prev => prev.filter(v => v.id !== id));
  };

  const handleVariantChange = (id: string, field: keyof ProductVariant, value: any) => {
    setVariants(prev => prev.map(v => {
      if (v.id === id) {
        const newValue = field === 'price' ? (value === '' ? 0 : parseFloat(value)) : value;
        return { ...v, [field]: newValue };
      }
      return v;
    }));
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage.from('product-images').upload(`products/${fileName}`, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
    } catch (error: any) {
      alert('Erro no upload. Tente colar um link direto da imagem.');
    } finally { setIsUploading(false); }
  };

  const handleSubmit = () => {
    if (!name.trim() || !category) { alert('Nome e Marca são obrigatórios.'); return; }
    const cleanVariants = variants.map(v => ({ ...v, price: Number(v.price) || 0, name: v.name || 'Padrão' }));
    onSave({
      id: productToEdit ? productToEdit.id : String(Date.now()), 
      name: name.trim(), category, description: description.trim(),
      image: image.trim() || 'https://picsum.photos/400/300?random=' + Date.now(),
      isActive: productToEdit ? productToEdit.isActive : true,
      variants: cleanVariants
    });
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b border-border-light dark:border-border-dark px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5"><span className="material-symbols-outlined">arrow_back</span></button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar Produto' : 'Novo Produto'}</h1>
      </div>

      <div className="px-4 pt-6 flex flex-col gap-6">
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div>
            <label className="block text-sm font-bold mb-1.5">Nome do Produto</label>
            <input value={name} onChange={(e) => setName(e.target.value)} className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm focus:ring-primary focus:border-primary" placeholder="Ex: Coca-Cola 2L" />
          </div>
          <div>
            <label className="block text-sm font-bold mb-1.5">Marca</label>
            <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm">
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <h2 className="text-sm font-bold flex items-center gap-2"><span className="material-symbols-outlined text-primary">image</span> Imagem do Produto</h2>
          <div className="p-3 bg-primary/5 rounded-xl border border-primary/20">
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest">Link Direto (HTML / URL)</label>
            <input value={image} onChange={(e) => setImage(e.target.value)} className="w-full rounded-lg border-primary/30 bg-white dark:bg-black/40 p-3 text-xs focus:ring-primary focus:border-primary font-mono" placeholder="https://exemplo.com/imagem.png" />
          </div>
          <div className="relative group">
            <div className="w-full aspect-video rounded-xl bg-neutral-100 dark:bg-black/40 overflow-hidden border-2 border-dashed border-neutral-300 dark:border-white/10 flex items-center justify-center">
              {image ? <img src={image} className="w-full h-full object-cover" /> : <span className="material-symbols-outlined text-4xl opacity-20">add_a_photo</span>}
            </div>
            <button onClick={() => fileInputRef.current?.click()} className="absolute bottom-2 right-2 bg-primary text-black p-2 rounded-full shadow-lg"><span className="material-symbols-outlined">upload_file</span></button>
          </div>
          <input type="file" ref={fileInputRef} className="hidden" onChange={handleImageUpload} />
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-sm font-bold">Variações e Preços</h2>
            <div className="flex gap-2">
              <button 
                onClick={() => setShowPresets(!showPresets)} 
                className="text-[10px] font-black uppercase text-blue-500 bg-blue-50 dark:bg-blue-900/20 px-2 py-1 rounded"
              >
                Mágica (Presets)
              </button>
              <button onClick={handleAddVariant} className="text-xs font-bold text-primary">+ Adicionar</button>
            </div>
          </div>

          {showPresets && presets.length > 0 && (
            <div className="p-3 bg-blue-50 dark:bg-blue-900/10 border border-blue-200 dark:border-blue-800 rounded-xl space-y-2 animate-in fade-in zoom-in-95 duration-200">
              <p className="text-[10px] font-bold text-blue-600 dark:text-blue-400 uppercase tracking-widest">Aplicar Grupo Salvo:</p>
              <div className="flex flex-wrap gap-2">
                {presets.map(p => (
                  <button 
                    key={p.id} 
                    onClick={() => handleApplyPreset(p)}
                    className="px-3 py-1.5 bg-white dark:bg-blue-900/30 border border-blue-300 dark:border-blue-700 text-[10px] font-bold rounded-lg shadow-sm"
                  >
                    {p.name}
                  </button>
                ))}
              </div>
            </div>
          )}

          {variants.map(v => (
            <div key={v.id} className="flex flex-col gap-2 p-3 bg-background-light dark:bg-black/20 rounded-xl relative group">
              <div className="flex gap-2">
                <input value={v.name} onChange={(e) => handleVariantChange(v.id, 'name', e.target.value)} className="flex-1 bg-transparent border-none p-0 text-sm font-bold focus:ring-0" placeholder="Tam/Peso" />
                <button onClick={() => handleRemoveVariant(v.id)} className="text-red-400 hover:text-red-600 transition-colors"><span className="material-symbols-outlined text-sm">delete</span></button>
              </div>
              <div className="flex items-center gap-1 font-bold text-sm bg-white dark:bg-black/40 px-3 py-1.5 rounded-lg border border-border-light dark:border-white/10">
                <span className="text-neutral-500">R$</span>
                <input type="number" step="0.01" inputMode="decimal" value={v.price === 0 ? '' : v.price} onChange={(e) => handleVariantChange(v.id, 'price', e.target.value)} onFocus={(e) => e.target.select()} className="w-full bg-transparent border-none p-0 focus:ring-0 font-black text-primary-dark dark:text-primary" placeholder="0,00" />
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="fixed bottom-0 w-full p-4 bg-white dark:bg-surface-dark border-t border-border-light dark:border-border-dark flex gap-3 max-w-lg mx-auto left-1/2 -translate-x-1/2">
        <button onClick={onCancel} className="flex-1 py-4 font-bold rounded-2xl border border-border-light">Cancelar</button>
        <button onClick={handleSubmit} className="flex-[2] py-4 bg-primary text-black font-bold rounded-2xl shadow-lg active:scale-95 transition-all">Salvar Produto</button>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let dbProducts: any[] | null = null;
      let pError: any = null;

      try {
        const { data, error } = await supabase.from('products').select('*').order('order_index', { ascending: true });
        dbProducts = data;
        pError = error;
      } catch (e) { pError = e; }

      if (pError && (pError.code === 'PGRST204' || pError.code === '42703' || pError.message?.includes('order_index'))) {
        const { data, error } = await supabase.from('products').select('*');
        dbProducts = data;
        pError = error;
      }

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));
        setProducts(normalized);
      } else {
        setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const saveProduct = async (product: Product) => {
    setIsLoading(true);
    try {
      const orderIndex = productToEdit?.order_index !== undefined ? productToEdit.order_index : products.length;
      let payload: any = {
        id: product.id,
        name: product.name,
        description: product.description || "",
        image: product.image,
        category: product.category,
        variants: JSON.parse(JSON.stringify(product.variants)),
        is_active: product.isActive,
        order_index: orderIndex
      };

      const attemptUpsert = async (currentPayload: any): Promise<any> => {
        const { error } = await supabase.from('products').upsert(currentPayload);
        if (error) {
          if (error.code === 'PGRST204' || error.code === '42703' || error.message.includes('column')) {
            const match = error.message.match(/'([^']+)'/);
            const offendingColumn = match ? match[1] : null;
            if (offendingColumn && currentPayload.hasOwnProperty(offendingColumn)) {
              const newPayload = { ...currentPayload };
              delete newPayload[offendingColumn];
              return attemptUpsert(newPayload);
            }
            if (currentPayload.order_index !== undefined) {
              const p = { ...currentPayload }; delete p.order_index; return attemptUpsert(p);
            }
            if (currentPayload.is_active !== undefined) {
              const p = { ...currentPayload }; delete p.is_active; return attemptUpsert(p);
            }
          }
          return error;
        }
        return null;
      };

      const error = await attemptUpsert(payload);
      if (error) throw new Error(`Erro Supabase: ${error.message}`);

      const updatedProduct = { ...product, order_index: orderIndex };
      setProducts(prev => {
        const exists = prev.find(p => p.id === product.id);
        if (exists) return prev.map(p => p.id === product.id ? updatedProduct : p);
        return [...prev, updatedProduct];
      });
      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      alert(`FALHA AO SALVAR:\n${err.message || 'Erro desconhecido'}`);
    } finally {
      setIsLoading(false);
    }
  };

  const deleteProduct = async (id: string) => {
    setIsLoading(true);
    try {
      // Tenta excluir do Supabase (id pode ser string ou número dependendo da origem)
      const { error } = await supabase.from('products').delete().eq('id', id);

      // Se der erro de tipo, tenta converter o ID para número (caso o banco use int)
      if (error && !isNaN(Number(id))) {
        await supabase.from('products').delete().eq('id', Number(id));
      }

      // Independentemente do resultado no servidor (para suportar exclusão de itens iniciais locais),
      // removemos do estado do app para o usuário ver a mudança imediatamente.
      setProducts(prev => prev.filter(p => p.id !== id));
      setCart(prev => prev.filter(item => item.productId !== id));
    } catch (err: any) {
      console.error("Erro na exclusão:", err);
      alert(`Não foi possível excluir o produto no servidor, mas ele foi removido da sua visualização.`);
      setProducts(prev => prev.filter(p => p.id !== id));
    } finally {
      setIsLoading(false);
    }
  };

  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStatus = !product.isActive;
    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));
    try { await supabase.from('products').update({ is_active: newStatus }).eq('id', id); } catch (e) {}
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;
    const newProducts = [...products];
    [newProducts[index], newProducts[targetIndex]] = [newProducts[targetIndex], newProducts[index]];
    setProducts(newProducts.map((p, i) => ({ ...p, order_index: i })));
    try { await supabase.from('products').update({ order_index: targetIndex }).eq('id', id); } catch (e) {}
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;
    const updatedVariants = product.variants.map(v => v.id === variantId ? { ...v, isActive: !v.isActive } : v);
    setProducts(prev => prev.map(p => p.id === productId ? { ...product, variants: updatedVariants } : p));
    await supabase.from('products').update({ variants: updatedVariants }).eq('id', productId);
  };

  const updateSetting = async (key: string, value: any) => {
    try { await supabase.from('settings').upsert({ key, value }); } catch (e) {}
  };

  const handleUpdateWhatsapp = async (num: string) => { setWhatsappNumber(num); await updateSetting('whatsapp', num); };
  const handleUpdateCategories = async (newCats: any) => { 
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated); await updateSetting('categories', updated); 
  };
  const handleUpdatePresets = async (newPresets: any) => {
    const updated = typeof newPresets === 'function' ? newPresets(presets) : newPresets;
    setPresets(updated); await updateSetting('presets', updated);
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) return prev.map(item => (item.productId === product.id && item.variantId === variantId) ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, variantId, quantity: 1, productName: product.name, variantName: variant.name, price: variant.price }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) return prev.map(item => (item.productId === productId && item.variantId === variantId) ? { ...item, quantity: item.quantity - 1 } : item);
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const handleSendWhatsApp = (paymentMethod: string) => {
    if (!clientName || clientName.trim().length < 3) { alert('Insira seu nome.'); return; }
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName}) - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold animate-pulse">Sincronizando com Supabase...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} addToCart={addToCart} removeFromCart={removeFromCart}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus} onToggleVariantStatus={toggleVariantStatus} onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={deleteProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} 
              presets={presets}
              productToEdit={productToEdit} 
              onSave={saveProduct} 
              onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} setCategories={handleUpdateCategories} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} setPresets={handleUpdatePresets} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Product } from '../types';

interface AdminViewProps {
  products: Product[];
  whatsappNumber: string;
  setWhatsappNumber: (num: string) => void;
  onToggleStatus: (id: string) => void;
  onToggleVariantStatus: (pId: string, vId: string) => void;
  onReorderProduct: (id: string, direction: 'up' | 'down') => void;
  onAddProduct: () => void;
  onEditProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onOpenCategories: () => void;
  onOpenVariations: () => void;
  onBack: () => void;
  onLogout: () => void;
}

const AdminView: React.FC<AdminViewProps> = ({ 
  products, 
  whatsappNumber, 
  setWhatsappNumber, 
  onToggleStatus, 
  onToggleVariantStatus,
  onReorderProduct,
  onAddProduct, 
  onEditProduct,
  onDeleteProduct,
  onOpenCategories, 
  onOpenVariations,
  onBack, 
  onLogout 
}) => {
  const [isEditingPhone, setIsEditingPhone] = useState(false);
  const [tempPhone, setTempPhone] = useState(whatsappNumber);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  const handleSavePhone = () => {
    const cleaned = tempPhone.replace(/\D/g, '');
    if (cleaned.length < 10) {
      alert('Por favor, insira um número de WhatsApp válido (com DDD).');
      return;
    }
    setWhatsappNumber(cleaned);
    setIsEditingPhone(false);
  };

  const toggleExpand = (id: string) => {
    setExpandedId(expandedId === id ? null : id);
    setConfirmDeleteId(null); // Reseta confirmação se expandir outro
  };

  const handleDeleteClick = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirmDeleteId === id) {
      onDeleteProduct(id);
      setConfirmDeleteId(null);
    } else {
      setConfirmDeleteId(id);
      // Opcional: auto-cancela após 3 segundos
      setTimeout(() => setConfirmDeleteId(prev => prev === id ? null : prev), 4000);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32 text-neutral-900 dark:text-neutral-50">
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b border-border-light dark:border-border-dark px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <button onClick={onBack} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition-colors">
            <span className="material-symbols-outlined">arrow_back</span>
          </button>
          <div>
            <h1 className="text-sm font-bold leading-tight">Painel Admin</h1>
            <p className="text-[10px] font-bold text-primary uppercase tracking-tighter">Gestão de Inventário</p>
          </div>
        </div>
        <button onClick={onLogout} className="w-10 h-10 flex items-center justify-center rounded-full text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors">
          <span className="material-symbols-outlined">logout</span>
        </button>
      </div>

      <div className="px-4 pt-6 space-y-8">
        {/* Settings Card */}
        <div className="bg-surface-light dark:bg-surface-dark rounded-2xl border border-border-light dark:border-border-dark p-4 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <span className="text-[10px] font-black uppercase text-text-sub dark:text-gray-400 tracking-widest">Configurações Gerais</span>
            <div className="flex gap-2">
               <button onClick={onOpenCategories} className="p-2 bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400 rounded-lg" title="Marcas">
                 <span className="material-symbols-outlined text-sm">category</span>
               </button>
               <button onClick={onOpenVariations} className="p-2 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-lg" title="Variações/Preços">
                 <span className="material-symbols-outlined text-sm">list_alt</span>
               </button>
            </div>
          </div>

          <div className="flex items-center justify-between bg-background-light dark:bg-black/20 rounded-xl p-3 border border-border-light dark:border-white/5">
            <div className="flex items-center gap-3">
               <span className="material-symbols-outlined text-green-500">brand_awareness</span>
               {isEditingPhone ? (
                 <input autoFocus value={tempPhone} onChange={(e) => setTempPhone(e.target.value)} onBlur={handleSavePhone} className="bg-transparent border-none p-0 text-sm font-bold w-32 focus:ring-0" />
               ) : (
                 <span className="text-sm font-bold">+{whatsappNumber}</span>
               )}
            </div>
            <button onClick={() => setIsEditingPhone(!isEditingPhone)} className="text-[10px] font-bold uppercase text-primary">
              {isEditingPhone ? 'Salvar' : 'Mudar WhatsApp'}
            </button>
          </div>
        </div>

        {/* Products List */}
        <div>
          <div className="flex items-center justify-between mb-4 px-1">
            <h2 className="text-lg font-black italic uppercase">Meus Itens</h2>
            <button onClick={onAddProduct} className="flex items-center gap-1 bg-primary px-3 py-1.5 rounded-lg text-[11px] font-black text-neutral-900 uppercase shadow-sm">
              <span className="material-symbols-outlined text-sm">add</span> Novo
            </button>
          </div>

          <div className="space-y-3">
            {products.map((product, idx) => {
              const isExpanded = expandedId === product.id;
              const isConfirmingDelete = confirmDeleteId === product.id;

              return (
                <div key={product.id} className="relative bg-white dark:bg-white/5 rounded-2xl border border-border-light dark:border-border-dark overflow-hidden transition-all hover:shadow-md">
                  <div className={`h-1 w-full ${product.isActive ? 'bg-primary' : 'bg-neutral-300 dark:bg-neutral-700'}`}></div>

                  {/* Card Header (Always Visible) */}
                  <div 
                    className="p-3 flex items-center gap-3 cursor-pointer select-none active:bg-black/5 dark:active:bg-white/5 transition-colors"
                    onClick={() => toggleExpand(product.id)}
                  >
                    <div className="relative shrink-0">
                      <div className="w-12 h-12 rounded-lg overflow-hidden border border-neutral-100 dark:border-white/10">
                        <img src={product.image} className={`w-full h-full object-cover ${!product.isActive ? 'grayscale opacity-50' : ''}`} alt="" />
                      </div>
                      <div className="absolute -left-1 -top-1 bg-white dark:bg-black/80 rounded shadow-sm border border-neutral-200 dark:border-white/10 px-1 py-0.5 flex flex-col items-center opacity-0 group-hover:opacity-100 md:opacity-100 transition-opacity">
                        <button disabled={idx === 0} onClick={(e) => { e.stopPropagation(); onReorderProduct(product.id, 'up'); }} className="text-neutral-600 dark:text-neutral-300 disabled:opacity-20 hover:text-primary"><span className="material-symbols-outlined text-[12px]">keyboard_arrow_up</span></button>
                        <button disabled={idx === products.length - 1} onClick={(e) => { e.stopPropagation(); onReorderProduct(product.id, 'down'); }} className="text-neutral-600 dark:text-neutral-300 disabled:opacity-20 hover:text-primary"><span className="material-symbols-outlined text-[12px]">keyboard_arrow_down</span></button>
                      </div>
                    </div>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-1.5">
                        <span className="text-[8px] font-black uppercase text-primary tracking-tighter whitespace-nowrap">{product.category}</span>
                        <div className={`w-1.5 h-1.5 rounded-full ${product.isActive ? 'bg-primary' : 'bg-neutral-400'}`}></div>
                      </div>
                      <h3 className={`text-sm font-bold truncate ${!product.isActive ? 'text-neutral-400' : ''}`}>{product.name}</h3>
                      <p className="text-[9px] text-neutral-500 font-bold uppercase">{product.isActive ? 'Em estoque' : 'Pausado'}</p>
                    </div>

                    <div className="flex items-center gap-1 shrink-0">
                      {!isConfirmingDelete ? (
                        <>
                          <button 
                            onClick={(e) => { e.stopPropagation(); onEditProduct(product); }} 
                            className="p-2 text-neutral-400 hover:text-primary transition-colors"
                          >
                            <span className="material-symbols-outlined text-lg">edit_square</span>
                          </button>
                          <button 
                            onClick={(e) => handleDeleteClick(e, product.id)} 
                            className="p-2 text-neutral-400 hover:text-red-500 transition-colors"
                          >
                            <span className="material-symbols-outlined text-lg">delete</span>
                          </button>
                        </>
                      ) : (
                        <button 
                          onClick={(e) => handleDeleteClick(e, product.id)} 
                          className="bg-red-500 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase animate-pulse shadow-lg shadow-red-500/30"
                        >
                          Apagar?
                        </button>
                      )}

                      <span className={`material-symbols-outlined text-neutral-400 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`}>
                        expand_more
                      </span>
                    </div>
                  </div>

                  {/* Expandable Content (Details) */}
                  {isExpanded && (
                    <div className="px-3 pb-3 animate-in slide-in-from-top-2 duration-200">
                      <div className="bg-background-light dark:bg-black/30 rounded-xl p-2.5 border border-border-light dark:border-white/5 space-y-2">
                        <div className="flex items-center justify-between px-1">
                          <span className="text-[9px] font-black uppercase text-neutral-400 dark:text-neutral-500 tracking-widest">Disponibilidade / Variações</span>
                          <button 
                            onClick={(e) => { e.stopPropagation(); onToggleStatus(product.id); }}
                            className={`flex items-center gap-1.5 text-[10px] font-bold uppercase px-2 py-1 rounded-md transition-all ${product.isActive ? 'bg-primary/20 text-primary-dark dark:text-primary' : 'bg-neutral-200 dark:bg-neutral-700 text-neutral-500'}`}
                          >
                            {product.isActive ? 'Ativo' : 'Pausado'}
                            <div className={`w-2 h-2 rounded-full ${product.isActive ? 'bg-primary animate-pulse' : 'bg-neutral-400'}`}></div>
                          </button>
                        </div>

                        <div className="grid grid-cols-2 gap-2">
                          {product.variants.map(v => (
                            <button 
                              key={v.id} 
                              disabled={!product.isActive} 
                              onClick={(e) => { e.stopPropagation(); onToggleVariantStatus(product.id, v.id); }} 
                              className={`flex items-center justify-between px-2 py-2 rounded-lg border text-[10px] font-bold transition-all active:scale-[0.97] ${v.isActive ? 'bg-white dark:bg-neutral-800 border-primary/20 text-neutral-900 dark:text-white shadow-sm' : 'bg-neutral-100 dark:bg-neutral-900/50 border-transparent text-neutral-400 line-through'} ${!product.isActive ? 'opacity-50 cursor-not-allowed' : ''}`}
                            >
                              <div className="flex flex-col items-start min-w-0">
                                <span className="truncate w-full">{v.name}</span>
                                <span className={`text-[9px] ${v.isActive ? 'text-primary' : 'text-neutral-500'}`}>R$ {v.price.toFixed(2)}</span>
                              </div>
                              <div className={`w-4 h-4 shrink-0 rounded-full flex items-center justify-center transition-colors ${v.isActive ? 'bg-primary text-black' : 'bg-neutral-200 dark:bg-neutral-700 text-neutral-500'}`}>
                                <span className="material-symbols-outlined text-[10px] font-black">{v.isActive ? 'check' : 'close'}</span>
                              </div>
                            </button>
                          ))}
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full bg-surface-light dark:bg-surface-dark border-t border-border-light dark:border-border-dark z-50 px-6 py-4 flex items-center justify-around shadow-2xl">
        <button onClick={onBack} className="flex flex-col items-center gap-1 text-neutral-400">
          <span className="material-symbols-outlined">shopping_bag</span>
          <span className="text-[9px] font-black uppercase">Loja</span>
        </button>
        <button onClick={onAddProduct} className="w-14 h-14 bg-primary text-black rounded-2xl shadow-xl shadow-primary/30 flex items-center justify-center -mt-10 hover:scale-110 active:scale-95 transition-all">
          <span className="material-symbols-outlined text-3xl font-black">add</span>
        </button>
        <button onClick={onLogout} className="flex flex-col items-center gap-1 text-red-400">
          <span className="material-symbols-outlined">logout</span>
          <span className="text-[9px] font-black uppercase">Sair</span>
        </button>
      </div>
    </div>
  );
};

export default AdminView;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let dbProducts: any[] | null = null;
      let pError: any = null;

      try {
        const { data, error } = await supabase.from('products').select('*').order('order_index', { ascending: true });
        dbProducts = data;
        pError = error;
      } catch (e) { pError = e; }

      if (pError && (pError.code === 'PGRST204' || pError.code === '42703' || pError.message?.includes('order_index'))) {
        const { data, error } = await supabase.from('products').select('*');
        dbProducts = data;
        pError = error;
      }

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));
        setProducts(normalized);
      } else {
        setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const saveProduct = async (product: Product) => {
    setIsLoading(true);
    try {
      const orderIndex = productToEdit?.order_index !== undefined ? productToEdit.order_index : products.length;
      let payload: any = {
        id: product.id,
        name: product.name,
        description: product.description || "",
        image: product.image,
        category: product.category,
        variants: JSON.parse(JSON.stringify(product.variants)),
        is_active: product.isActive,
        order_index: orderIndex
      };

      const attemptUpsert = async (currentPayload: any): Promise<any> => {
        const { error } = await supabase.from('products').upsert(currentPayload);
        if (error) {
          if (error.code === 'PGRST204' || error.code === '42703' || error.message.includes('column')) {
            const match = error.message.match(/'([^']+)'/);
            const offendingColumn = match ? match[1] : null;
            if (offendingColumn && currentPayload.hasOwnProperty(offendingColumn)) {
              const newPayload = { ...currentPayload };
              delete newPayload[offendingColumn];
              return attemptUpsert(newPayload);
            }
            if (currentPayload.order_index !== undefined) {
              const p = { ...currentPayload }; delete p.order_index; return attemptUpsert(p);
            }
            if (currentPayload.is_active !== undefined) {
              const p = { ...currentPayload }; delete p.is_active; return attemptUpsert(p);
            }
          }
          return error;
        }
        return null;
      };

      const error = await attemptUpsert(payload);
      if (error) throw new Error(`Erro Supabase: ${error.message}`);

      const updatedProduct = { ...product, order_index: orderIndex };
      setProducts(prev => {
        const exists = prev.find(p => p.id === product.id);
        if (exists) return prev.map(p => p.id === product.id ? updatedProduct : p);
        return [...prev, updatedProduct];
      });
      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      alert(`FALHA AO SALVAR:\n${err.message || 'Erro desconhecido'}`);
    } finally {
      setIsLoading(false);
    }
  };

  const deleteProduct = async (id: string) => {
    setIsLoading(true);
    try {
      const { error } = await supabase.from('products').delete().eq('id', id);
      if (error && !isNaN(Number(id))) {
        await supabase.from('products').delete().eq('id', Number(id));
      }
      setProducts(prev => prev.filter(p => p.id !== id));
      setCart(prev => prev.filter(item => item.productId !== id));
    } catch (err: any) {
      console.error("Erro na exclusão:", err);
      alert(`Não foi possível excluir o produto no servidor, mas ele foi removido da sua visualização.`);
      setProducts(prev => prev.filter(p => p.id !== id));
    } finally {
      setIsLoading(false);
    }
  };

  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStatus = !product.isActive;
    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));
    try { await supabase.from('products').update({ is_active: newStatus }).eq('id', id); } catch (e) {}
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;

    const newProducts = [...products];
    const itemA = newProducts[index];
    const itemB = newProducts[targetIndex];

    // Troca local
    [newProducts[index], newProducts[targetIndex]] = [newProducts[targetIndex], newProducts[index]];

    // Atualiza estado local com novos índices
    const productsWithNewIndexes = newProducts.map((p, i) => ({ ...p, order_index: i }));
    setProducts(productsWithNewIndexes);

    // Persiste no banco de dados para os dois itens afetados
    try {
      await Promise.all([
        supabase.from('products').update({ order_index: targetIndex }).eq('id', itemA.id),
        supabase.from('products').update({ order_index: index }).eq('id', itemB.id)
      ]);
    } catch (e) {
      console.error("Erro ao salvar nova ordem no Supabase:", e);
    }
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;
    const updatedVariants = product.variants.map(v => v.id === variantId ? { ...v, isActive: !v.isActive } : v);
    setProducts(prev => prev.map(p => p.id === productId ? { ...product, variants: updatedVariants } : p));
    await supabase.from('products').update({ variants: updatedVariants }).eq('id', productId);
  };

  const updateSetting = async (key: string, value: any) => {
    try { await supabase.from('settings').upsert({ key, value }); } catch (e) {}
  };

  const handleUpdateWhatsapp = async (num: string) => { setWhatsappNumber(num); await updateSetting('whatsapp', num); };
  const handleUpdateCategories = async (newCats: any) => { 
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated); await updateSetting('categories', updated); 
  };
  const handleUpdatePresets = async (newPresets: any) => {
    const updated = typeof newPresets === 'function' ? newPresets(presets) : newPresets;
    setPresets(updated); await updateSetting('presets', updated);
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) return prev.map(item => (item.productId === product.id && item.variantId === variantId) ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, variantId, quantity: 1, productName: product.name, variantName: variant.name, price: variant.price }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) return prev.map(item => (item.productId === productId && item.variantId === variantId) ? { ...item, quantity: item.quantity - 1 } : item);
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const handleSendWhatsApp = (paymentMethod: string) => {
    if (!clientName || clientName.trim().length < 3) { alert('Insira seu nome.'); return; }
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName}) - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold animate-pulse">Sincronizando com Supabase...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} addToCart={addToCart} removeFromCart={removeFromCart}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus} onToggleVariantStatus={toggleVariantStatus} onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={deleteProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} 
              presets={presets}
              productToEdit={productToEdit} 
              onSave={saveProduct} 
              onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} setCategories={handleUpdateCategories} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} setPresets={handleUpdatePresets} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Product } from '../types';

interface AdminViewProps {
  products: Product[];
  whatsappNumber: string;
  setWhatsappNumber: (num: string) => void;
  onToggleStatus: (id: string) => void;
  onToggleVariantStatus: (pId: string, vId: string) => void;
  onReorderProduct: (id: string, direction: 'up' | 'down') => void;
  onAddProduct: () => void;
  onEditProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onOpenCategories: () => void;
  onOpenVariations: () => void;
  onBack: () => void;
  onLogout: () => void;
}

const AdminView: React.FC<AdminViewProps> = ({ 
  products, 
  whatsappNumber, 
  setWhatsappNumber, 
  onToggleStatus, 
  onToggleVariantStatus,
  onReorderProduct,
  onAddProduct, 
  onEditProduct,
  onDeleteProduct,
  onOpenCategories, 
  onOpenVariations,
  onBack, 
  onLogout 
}) => {
  const [isEditingPhone, setIsEditingPhone] = useState(false);
  const [tempPhone, setTempPhone] = useState(whatsappNumber);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  const handleSavePhone = () => {
    const cleaned = tempPhone.replace(/\D/g, '');
    if (cleaned.length < 10) {
      alert('Por favor, insira um número de WhatsApp válido (com DDD).');
      return;
    }
    setWhatsappNumber(cleaned);
    setIsEditingPhone(false);
  };

  const toggleExpand = (id: string) => {
    setExpandedId(expandedId === id ? null : id);
    setConfirmDeleteId(null);
  };

  const handleDeleteClick = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirmDeleteId === id) {
      onDeleteProduct(id);
      setConfirmDeleteId(null);
    } else {
      setConfirmDeleteId(id);
      setTimeout(() => setConfirmDeleteId(prev => prev === id ? null : prev), 4000);
    }
