            </div>
            <h1 className="text-neutral-900 dark:text-white text-lg font-bold">Catalogo Doce Mania</h1>
          </div>
          <button onClick={onOpenSettings} className="flex h-10 w-10 items-center justify-center rounded-full text-neutral-500 hover:bg-neutral-100 dark:text-neutral-400 dark:hover:bg-white/10">
