        {/* Lista de Produtos */}
        <div className="flex flex-col gap-6">
          {filteredProducts.map(product => {
            const variantsArray = Array.isArray(product.variants) ? product.variants : [];
            const activeVariants = variantsArray.filter(v => v.isActive === true);

            if (activeVariants.length === 0) return null;

            return (
              <article key={product.id} className="group overflow-hidden rounded-2xl bg-white dark:bg-white/5 p-3 shadow-sm border border-neutral-100 dark:border-white/5">
                <div className="flex flex-col gap-3">
                  <div className="relative aspect-video w-full overflow-hidden rounded-xl bg-neutral-100 dark:bg-neutral-800 shadow-inner">
                    <img 
                      src={product.image || 'https://picsum.photos/400/300?grayscale'} 
                      alt={product.name}
                      className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
                      onError={(e) => { (e.target as HTMLImageElement).src = 'https://picsum.photos/400/300?grayscale'; }}
                    />
                    <div className="absolute top-2 right-2 bg-black/60 backdrop-blur-md text-white px-2 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider">
                      {product.category}
                    </div>
                  </div>

                  <div className="flex flex-col w-full px-1">
                    <h3 className="text-base font-bold text-neutral-900 dark:text-white">{product.name}</h3>
                    {product.description && <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-1 line-clamp-2">{product.description}</p>}

                    <div className="mt-4 space-y-3">
                      {activeVariants.map((variant) => {
                        const qty = getQuantity(product.id, variant.id);
                        const isMulti = activeVariants.length > 1;

                        return (
                          <div key={variant.id} className="flex items-center justify-between gap-4">
                            <div className="flex flex-col">
                              {isMulti && <span className="text-xs font-bold text-neutral-500">{variant.name}</span>}
                              <span className="text-base font-extrabold text-primary-dark dark:text-primary">R$ {Number(variant.price).toFixed(2)}</span>
                            </div>

                            <div className="flex items-center bg-neutral-100 dark:bg-black/30 rounded-full p-1">
                              {qty > 0 ? (
                                <>
                                  <button 
                                    onClick={() => removeFromCart(product.id, variant.id)}
                                    className="h-9 w-9 flex items-center justify-center rounded-full bg-white dark:bg-neutral-700 shadow-sm active:scale-95"
                                  >
                                    <span className="material-symbols-outlined text-[20px]">remove</span>
                                  </button>
                                  <span className="w-8 text-center text-sm font-bold">{qty}</span>
                                  <button 
                                    onClick={() => addToCart(product, variant.id)}
                                    className="h-9 w-9 flex items-center justify-center rounded-full bg-primary text-black shadow-sm active:scale-95"
                                  >
                                    <span className="material-symbols-outlined text-[20px]">add</span>
                                  </button>
                                </>
                              ) : (
                                <button 
                                  onClick={() => addToCart(product, variant.id)}
                                  className="flex h-9 px-4 items-center gap-1 rounded-full text-xs font-bold transition hover:bg-primary/10"
                                >
                                  <span className="material-symbols-outlined text-[18px]">add</span> Adicionar
                                </button>
                              )}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              </article>
            );
          })}
        </div>

        {/* Resumo do Carrinho (Cupom) */}
        {cart.length > 0 && (
          <div className="mt-12 mb-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div 
              ref={receiptRef}
              className="bg-[#fff] text-neutral-800 p-6 shadow-xl rounded-sm border-t-4 border-primary relative overflow-hidden font-mono text-[11px] leading-relaxed"
            >
              <div className="absolute top-0 left-0 w-full flex justify-around -mt-2">
                {[...Array(20)].map((_, i) => (
                  <div key={i} className="w-4 h-4 bg-background-light dark:bg-background-dark rounded-full"></div>
                ))}
