                  <span>{currentTime}</span>
                </div>

                <div className="text-left border-y border-neutral-100 py-2 space-y-1">
                  <div>
                    <span className="font-black">CLIENTE: </span>
                    <span className="uppercase">{clientName || "____________________"}</span>
                  </div>
                  <div>
                    <span className="font-black">PAGAMENTO: </span>
                    <span className="uppercase">{paymentMethod}</span>
                  </div>
