                    <span className="w-8 font-bold">{item.quantity}x</span>
                    <span className="flex-1 px-2 uppercase truncate">
                      {item.productName} 
                      {item.variantName !== 'Padrão' && <span className="block text-[9px] opacity-60">({item.variantName})</span>}
                    </span>
                    <span className="text-right whitespace-nowrap">R$ {(item.price * item.quantity).toFixed(2)}</span>
                  </div>
