              <div className="border-t border-dashed border-neutral-400 pt-4 space-y-2">
                <div className="flex justify-between text-sm font-bold">
                  <span>TOTAL GERAL</span>
                  <span className="text-base">R$ {total.toFixed(2)}</span>
                </div>
              </div>

              <div className="absolute bottom-0 left-0 w-full flex justify-around -mb-2">
                {[...Array(20)].map((_, i) => (
                  <div key={i} className="w-4 h-4 bg-background-light dark:bg-background-dark rounded-full"></div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Identificação e Pagamento */}
        <div className="mt-8 mb-10 space-y-6">
          <div className="p-4 bg-white dark:bg-white/5 rounded-2xl border border-neutral-100 dark:border-white/10 shadow-sm">
            <label className="block text-xs font-bold uppercase text-neutral-500 dark:text-neutral-400 mb-3 tracking-wider">
              Identificação do Cliente <span className="text-red-500">*</span>
            </label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 flex items-center pl-4 pointer-events-none text-neutral-400">
                <span className="material-symbols-outlined text-xl">person</span>
              </div>
              <input 
                value={clientName}
                onChange={(e) => setClientName(e.target.value)}
                className={`w-full bg-neutral-50 dark:bg-black/20 border ${!isNameValid && clientName.length > 0 ? 'border-red-500' : 'border-neutral-200 dark:border-white/10'} text-neutral-900 dark:text-white rounded-xl py-3.5 pl-11 pr-4 outline-none focus:ring-2 focus:ring-primary focus:border-transparent transition-all placeholder:text-neutral-400`} 
                placeholder="Digite seu nome completo..." 
                required
                type="text"
              />
            </div>
          </div>

          <div className="p-4 bg-white dark:bg-white/5 rounded-2xl border border-neutral-100 dark:border-white/10 shadow-sm">
            <label className="block text-xs font-bold uppercase text-neutral-500 dark:text-neutral-400 mb-4 tracking-wider">
              Forma de Pagamento
            </label>
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => setPaymentMethod('Pix')}
                className={`flex items-center justify-center gap-2 py-3.5 rounded-xl border-2 font-bold transition-all ${paymentMethod === 'Pix' ? 'border-primary bg-primary/10 text-primary-dark dark:text-primary shadow-sm' : 'border-neutral-200 dark:border-white/5 text-neutral-500'}`}
              >
                <span className="material-symbols-outlined text-xl">qr_code_2</span> Pix
              </button>
              <button 
                onClick={() => setPaymentMethod('Dinheiro')}
                className={`flex items-center justify-center gap-2 py-3.5 rounded-xl border-2 font-bold transition-all ${paymentMethod === 'Dinheiro' ? 'border-primary bg-primary/10 text-primary-dark dark:text-primary shadow-sm' : 'border-neutral-200 dark:border-white/5 text-neutral-500'}`}
              >
                <span className="material-symbols-outlined text-xl">payments</span> Dinheiro
              </button>
            </div>
          </div>
        </div>
      </main>

      {/* Barra de Ação Fixa */}
      <div className="fixed bottom-0 left-0 w-full z-50 p-4">
        <div className="absolute bottom-0 left-0 w-full h-44 bg-gradient-to-t from-background-light via-background-light/95 to-transparent dark:from-background-dark dark:via-background-dark/95 pointer-events-none"></div>
        <div className="relative w-full max-w-md mx-auto space-y-3">

          {cart.length > 0 && (
            <div className="bg-white/90 dark:bg-black/60 backdrop-blur-sm p-3 rounded-2xl border border-neutral-200 dark:border-white/5 shadow-lg flex items-center justify-between">
              <div className="flex flex-col">
                <span className="text-[10px] font-bold text-neutral-500 uppercase">Seu Total</span>
                <span className="text-lg font-black text-neutral-900 dark:text-white">R$ {total.toFixed(2)}</span>
              </div>
              <div className="flex flex-col items-end">
                <span className="text-[10px] font-bold text-neutral-500 uppercase">Pagamento</span>
                <span className="text-[11px] font-black text-primary-dark dark:text-primary uppercase tracking-tighter">
                  {paymentMethod}
                </span>
              </div>
            </div>
          )}

          <button 
            onClick={handleConfirmOrder}
            disabled={!isOrderValid || isProcessing}
            className={`w-full ${!isOrderValid || isProcessing ? 'bg-neutral-300 dark:bg-neutral-700 cursor-not-allowed text-neutral-500' : 'bg-primary hover:bg-[#0fd651] shadow-xl shadow-primary/20 text-neutral-900 active:scale-[0.98]'} transition-all duration-300 font-bold text-lg rounded-2xl py-4 flex items-center justify-center gap-3`}
          >
            {isProcessing ? (
               <div className="w-5 h-5 border-2 border-neutral-900 border-t-transparent rounded-full animate-spin"></div>
            ) : (
              <svg className="w-6 h-6 fill-current" viewBox="0 0 24 24"><path d="M18.403 5.633A8.919 8.919 0 0 0 12.053 3c-4.948 0-8.976 4.027-8.978 8.977 0 1.582.413 3.126 1.198 4.488L3 21.116l4.759-1.249a8.981 8.981 0 0 0 4.293 1.093h.004c4.947 0 8.975-4.027 8.977-8.977a8.926 8.926 0 0 0-2.63-6.35m-6.35 13.812h-.003a7.446 7.446 0 0 1-3.798-1.041l-.272-.162-2.824.741.753-2.753-.177-.282a7.448 7.448 0 0 1-1.141-3.971c.002-4.114 3.349-7.461 7.465-7.461a7.413 7.413 0 0 1 5.275 2.188 7.42 7.42 0 0 1 2.183 5.279c-.002 4.114-3.349 7.462-7.461 7.462m4.093-5.589c-.225-.113-1.327-.655-1.533-.73-.205-.075-.354-.112-.504.112s-.58.729-.711.879-.262.168-.486.056-.947-.349-1.804-1.113c-.667-.595-1.117-1.329-1.248-1.554s-.014-.346.099-.458c.101-.1.224-.262.336-.393.112-.131.149-.224.224-.374s.038-.281-.019-.393c-.056-.113-.505-1.217-.692-1.666-.181-.435-.366-.377-.504-.383a9.65 9.65 0 0 0-.429-.008.826.826 0 0 0-.599.28c-.206.225-.785.767-.785 1.871s.804 2.171.916 2.321c.112.15 1.582 2.415 3.832 3.387.536.231.954.369 1.279.473.537.171 1.026.146 1.413.089.431-.064 1.327-.542 1.514-1.066.187-.524.187-.973.131-1.067-.056-.094-.207-.151-.43-.263"></path></svg>
            Confirmar Pedido
          </button>
        </div>
      </div>
    </div>
  );
};

