export const CATEGORIES = ['Todas', 'Elma Chips', 'Bebidas', 'Doces', 'Salgados', 'Pipocas'];

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let { data: dbProducts, error } = await supabase.from('products').select('*').order('order_index', { ascending: true });

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));
        setProducts(normalized);
      } else {
        const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({ 
          ...p, 
          order_index: i,
          is_active: p.isActive,
          variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
        }));
        setProducts(seedProducts);
        await supabase.from('products').upsert(seedProducts);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const formatSupabaseError = (err: any): string => {
    if (!err) return "Erro desconhecido";
    if (typeof err === 'string') return err;
    if (err.message) return `${err.message} ${err.details ? `(${err.details})` : ''}`;
    return JSON.stringify(err);
  };

  const saveProduct = async (product: Product) => {
    try {
      const orderIndex = productToEdit?.order_index !== undefined ? productToEdit.order_index : products.length;

      // Payload Híbrido para máxima compatibilidade com o banco de dados
      const payload: any = {
        id: product.id,
        name: product.name,
        description: product.description || "",
        image: product.image,
        category: product.category,
        variants: JSON.parse(JSON.stringify(product.variants)),
        is_active: product.isActive,
        isActive: product.isActive,
        order_index: orderIndex,
        orderIndex: orderIndex
      };

      const { error } = await supabase.from('products').upsert(payload);

      if (error) {
        console.error("Erro Supabase 1:", error);
        // Tentativa 2: Apenas campos básicos em caso de erro de coluna
        const { error: error2 } = await supabase.from('products').upsert({
          id: product.id,
          name: product.name,
          image: product.image,
          category: product.category,
          description: product.description
        });

        if (error2) {
          throw new Error(formatSupabaseError(error2));
        }
      }

      // Atualização Local
      const updatedProduct = { ...product, order_index: orderIndex };
      setProducts(prev => {
        const exists = prev.find(p => p.id === product.id);
        if (exists) return prev.map(p => p.id === product.id ? updatedProduct : p);
        return [...prev, updatedProduct];
      });

      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      throw new Error(formatSupabaseError(err));
    }
  };

  const handleResetToDefaults = async () => {
    if (!confirm("Restaurar catálogo original?")) return;
    setIsLoading(true);
    try {
      await supabase.from('products').delete().neq('id', '0');
      const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({
        ...p,
        order_index: i,
        is_active: p.isActive,
        variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
      }));
      await supabase.from('products').upsert(seedProducts);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
      setCategories(CATEGORIES);
      alert("Catálogo Restaurado!");
    } catch (err) {
      alert("Erro ao restaurar.");
    } finally {
      setIsLoading(false);
    }
  };

  const deleteProduct = async (id: string) => {
    setIsLoading(true);
    try {
      await supabase.from('products').delete().eq('id', id);
      setProducts(prev => prev.filter(p => p.id !== id));
      setCart(prev => prev.filter(item => item.productId !== id));
    } catch (err) {} finally { setIsLoading(false); }
  };

  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStatus = !product.isActive;
    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));
    try { 
      await supabase.from('products').update({ is_active: newStatus, isActive: newStatus }).eq('id', id); 
    } catch (e) {}
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;
    const newProducts = [...products];
    const itemA = newProducts[index];
    const itemB = newProducts[targetIndex];
    [newProducts[index], newProducts[targetIndex]] = [newProducts[targetIndex], newProducts[index]];
    setProducts(newProducts.map((p, i) => ({ ...p, order_index: i })));
    try {
      await Promise.all([
        supabase.from('products').update({ order_index: targetIndex, orderIndex: targetIndex }).eq('id', itemA.id),
        supabase.from('products').update({ order_index: index, orderIndex: index }).eq('id', itemB.id)
      ]);
    } catch (e) {}
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;
    const updatedVariants = product.variants.map(v => v.id === variantId ? { ...v, isActive: !v.isActive } : v);
    setProducts(prev => prev.map(p => p.id === productId ? { ...product, variants: updatedVariants } : p));
    await supabase.from('products').update({ variants: updatedVariants }).eq('id', productId);
  };

  const updateSetting = async (key: string, value: any) => {
    try { await supabase.from('settings').upsert({ key, value }); } catch (e) {}
  };

  const handleUpdateWhatsapp = async (num: string) => { setWhatsappNumber(num); await updateSetting('whatsapp', num); };
  const handleUpdateCategories = async (newCats: any) => { 
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated); await updateSetting('categories', updated); 
  };
  const handleUpdatePresets = async (newPresets: any) => {
    const updated = typeof newPresets === 'function' ? newPresets(presets) : newPresets;
    setPresets(updated); await updateSetting('presets', updated);
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) return prev.map(item => (item.productId === product.id && item.variantId === variantId) ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, variantId, quantity: 1, productName: product.name, variantName: variant.name, price: variant.price }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) return prev.map(item => (item.productId === productId && item.variantId === variantId) ? { ...item, quantity: item.quantity - 1 } : item);
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const handleSendWhatsApp = (paymentMethod: string) => {
    if (!clientName || clientName.trim().length < 3) { alert('Insira seu nome.'); return; }
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName}) - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-6"></div>
          <h2 className="text-xl font-black uppercase text-neutral-900 dark:text-white tracking-widest mb-2">Catalogo Doce Mania</h2>
          <p className="font-bold animate-pulse text-primary text-sm uppercase">Sincronizando Banco...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} addToCart={addToCart} removeFromCart={removeFromCart}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus} onToggleVariantStatus={toggleVariantStatus} onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={deleteProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onResetToDefaults={handleResetToDefaults}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} 
              presets={presets}
              productToEdit={productToEdit} 
              onSave={saveProduct} 
              onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} setCategories={handleUpdateCategories} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} setPresets={handleUpdatePresets} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({...v, price: Number(v.price)})));
    }
  }, [productToEdit]);

  const handleApplyPreset = (preset: VariationPreset) => {
    const newVariants = preset.variants.map(v => ({
      ...v,
      id: Math.random().toString(36).substr(2, 9)
    }));
    setVariants(newVariants);
    setShowPresets(false);
  };

  const handleAddVariant = () => {
    setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }]);
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length <= 1) {
      alert('O produto precisa ter pelo menos um preço/variação.');
      return;
    }
    setVariants(prev => prev.filter(v => v.id !== id));
  };

  const handleVariantChange = (id: string, field: keyof ProductVariant, value: any) => {
    setVariants(prev => prev.map(v => {
      if (v.id === id) {
        const newValue = field === 'price' ? (value === '' ? 0 : parseFloat(value)) : value;
        return { ...v, [field]: newValue };
      }
      return v;
    }));
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage.from('product-images').upload(`products/${fileName}`, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
    } catch (error: any) {
      const msg = error.message || "Erro de conexão";
      alert('Erro no upload: ' + msg);
    } finally { setIsUploading(false); }
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) { 
      alert('Preencha Nome e Marca!'); 
      return; 
    }

    setIsSaving(true);
    try {
      const cleanVariants = variants.map(v => ({ 
        ...v, 
        price: Number(v.price) || 0, 
        name: v.name || 'Padrão' 
      }));

      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/300',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: cleanVariants
      });
    } catch (err: any) {
      const errorMsg = err.message || String(err);
      console.error("ERRO CRÍTICO NO SALVAMENTO:", err);
      alert(`⚠️ ERRO DO SERVIDOR:\n\n${errorMsg}\n\nVerifique se o nome do produto ou marca estão corretos.`);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b border-border-light dark:border-border-dark px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar Produto' : 'Novo Produto'}</h1>
      </div>

      <div className="px-4 pt-6 flex flex-col gap-6">
        {/* Basic Info */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div>
            <label className="block text-sm font-bold mb-1.5 italic tracking-tighter text-primary-dark dark:text-primary">Nome do Produto</label>
            <input 
              value={name} 
              onChange={(e) => setName(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm focus:ring-primary focus:border-primary outline-none font-bold" 
              placeholder="Ex: Doritos Sweet Chili" 
            />
          </div>
          <div>
            <label className="block text-sm font-bold mb-1.5 italic tracking-tighter text-primary-dark dark:text-primary">Marca</label>
            <select 
              value={category} 
              onChange={(e) => setCategory(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm outline-none font-bold"
            >
              <option value="">Selecione a Marca...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
        </div>

        {/* Image Section */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <h2 className="text-sm font-black uppercase italic tracking-widest flex items-center gap-2">
            <span className="material-symbols-outlined text-primary">image</span> Foto do Produto
          </h2>
          <div className="p-3 bg-primary/5 rounded-xl border border-primary/20">
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest">URL da Imagem (Link Direto)</label>
            <input 
              value={image} 
              onChange={(e) => setImage(e.target.value)} 
              className="w-full rounded-lg border-primary/30 bg-white dark:bg-black/40 p-3 text-xs focus:ring-primary outline-none font-mono" 
              placeholder="Cole o link da foto aqui..." 
            />
          </div>
          <div className="relative group overflow-hidden rounded-xl border-2 border-dashed border-neutral-300 dark:border-white/10">
            <div className="w-full aspect-video bg-neutral-100 dark:bg-black/40 flex items-center justify-center">
              {image ? (
                <img src={image} className="w-full h-full object-contain" onError={(e) => (e.currentTarget.src = 'https://picsum.photos/400/300?text=Erro+Link')} />
              ) : (
                <span className="material-symbols-outlined text-4xl opacity-20">add_a_photo</span>
              )}
            </div>
            <button 
              onClick={() => fileInputRef.current?.click()} 
              disabled={isUploading}
              className="absolute bottom-2 right-2 bg-primary text-black p-3 rounded-xl shadow-lg disabled:opacity-50"
            >
              <span className="material-symbols-outlined">{isUploading ? 'sync' : 'upload'}</span>
            </button>
          </div>
          <input type="file" ref={fileInputRef} className="hidden" onChange={handleImageUpload} accept="image/*" />
        </div>

        {/* Variants Section */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-sm font-black uppercase italic tracking-widest">Preços e Pesos</h2>
            <div className="flex gap-2">
              <button 
                onClick={() => setShowPresets(!showPresets)} 
                className="text-[10px] font-black uppercase text-blue-500 bg-blue-50 dark:bg-blue-900/20 px-2 py-1 rounded"
              >
                Presets
              </button>
              <button onClick={handleAddVariant} className="text-xs font-bold text-primary">+ Novo Preço</button>
            </div>
          </div>

          {showPresets && presets.length > 0 && (
            <div className="p-3 bg-blue-50 dark:bg-blue-900/10 border border-blue-200 dark:border-blue-800 rounded-xl space-y-2">
              <p className="text-[10px] font-bold text-blue-600 dark:text-blue-400 uppercase tracking-widest">Aplicar Grupo:</p>
              <div className="flex flex-wrap gap-2">
                {presets.map(p => (
                  <button 
                    key={p.id} 
                    onClick={() => handleApplyPreset(p)}
                    className="px-3 py-1.5 bg-white dark:bg-blue-900/30 border border-blue-300 dark:border-blue-700 text-[10px] font-bold rounded-lg shadow-sm"
                  >
                    {p.name}
                  </button>
                ))}
              </div>
            </div>
          )}

          {variants.map(v => (
            <div key={v.id} className="flex flex-col gap-2 p-3 bg-background-light dark:bg-black/20 rounded-xl relative border border-transparent focus-within:border-primary/30 transition-all">
              <div className="flex gap-2">
                <input 
                  value={v.name} 
                  onChange={(e) => handleVariantChange(v.id, 'name', e.target.value)} 
                  className="flex-1 bg-transparent border-none p-0 text-sm font-bold focus:ring-0 outline-none" 
                  placeholder="Ex: 48g, 140g ou Unitário" 
                />
                <button onClick={() => handleRemoveVariant(v.id)} className="text-red-400 hover:text-red-600 transition-colors">
                  <span className="material-symbols-outlined text-sm">delete</span>
                </button>
              </div>
              <div className="flex items-center gap-1 font-bold text-sm bg-white dark:bg-black/40 px-3 py-1.5 rounded-lg border border-border-light dark:border-white/10">
                <span className="text-neutral-500">R$</span>
                <input 
                  type="number" 
                  step="0.01" 
                  inputMode="decimal" 
                  value={v.price === 0 ? '' : v.price} 
                  onChange={(e) => handleVariantChange(v.id, 'price', e.target.value)} 
                  className="w-full bg-transparent border-none p-0 focus:ring-0 font-black text-primary-dark dark:text-primary outline-none" 
                  placeholder="0,00" 
                />
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="fixed bottom-0 w-full p-4 bg-white/95 dark:bg-surface-dark/95 backdrop-blur-md border-t border-border-light dark:border-border-dark flex gap-3 max-w-lg mx-auto left-1/2 -translate-x-1/2 z-50">
        <button 
          onClick={onCancel} 
          disabled={isSaving}
          className="flex-1 py-4 font-bold rounded-2xl border border-border-light disabled:opacity-50"
        >
          Voltar
        </button>
        <button 
          onClick={handleSubmit} 
          disabled={isSaving || isUploading}
          className="flex-[2] py-4 bg-primary text-black font-bold rounded-2xl shadow-xl shadow-primary/20 active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
        >
          {isSaving ? (
            <div className="w-5 h-5 border-2 border-black border-t-transparent rounded-full animate-spin"></div>
          ) : (
            <span className="material-symbols-outlined font-black">save</span>
          )}
          {isSaving ? 'Gravando...' : 'Salvar Alterações'}
        </button>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let { data: dbProducts, error } = await supabase.from('products').select('*').order('order_index', { ascending: true });

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));
        setProducts(normalized);
      } else {
        const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({ 
          ...p, 
          order_index: i,
          is_active: p.isActive,
          variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
        }));
        setProducts(seedProducts);
        await supabase.from('products').upsert(seedProducts);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const formatError = (err: any): string => {
    if (!err) return "Erro desconhecido";
    if (typeof err === 'string') return err;
    // Se for um erro do Supabase (PostgrestError)
    if (err.message) {
      let msg = err.message;
      if (err.details) msg += ` (${err.details})`;
      if (err.hint) msg += ` - Dica: ${err.hint}`;
      return msg;
    }
    return JSON.stringify(err);
  };

  const saveProduct = async (product: Product) => {
    try {
      const orderIndex = productToEdit?.order_index !== undefined ? productToEdit.order_index : products.length;

      // Payload resiliente
      const payload: any = {
        id: product.id,
        name: product.name,
        description: product.description || "",
        image: product.image,
        category: product.category,
        variants: product.variants,
        is_active: product.isActive,
        isActive: product.isActive, // Envia ambos para evitar erro de coluna
        order_index: orderIndex,
        orderIndex: orderIndex // Envia ambos para evitar erro de coluna
      };

      const { error } = await supabase.from('products').upsert(payload);

      if (error) {
        console.error("Erro no salvamento (Tentativa 1):", error);

        // Tentativa de modo de segurança: Apenas campos básicos
        const minimalPayload = {
          id: product.id,
          name: product.name,
          image: product.image,
          category: product.category,
          description: product.description
        };

        const { error: error2 } = await supabase.from('products').upsert(minimalPayload);

        if (error2) {
          throw new Error(formatError(error2));
        }

        // Se o modo de segurança funcionou, avisamos que variantes/status podem não ter sido salvos no DB
        console.warn("Produto salvo apenas com dados básicos devido a restrições de colunas no seu banco de dados.");
      }

      // Atualização imediata na interface
      const updatedProduct = { ...product, order_index: orderIndex };
      setProducts(prev => {
        const exists = prev.find(p => p.id === product.id);
        if (exists) return prev.map(p => p.id === product.id ? updatedProduct : p);
        return [...prev, updatedProduct];
      });

      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      throw new Error(formatError(err));
    }
  };

  const handleResetToDefaults = async () => {
    if (!confirm("Isso restaurará os itens originais do catálogo. Continuar?")) return;
    setIsLoading(true);
    try {
      await supabase.from('products').delete().neq('id', '0');
      const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({
        ...p,
        order_index: i,
        is_active: p.isActive,
        variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
      }));
      await supabase.from('products').upsert(seedProducts);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
      setCategories(CATEGORIES);
      alert("Catálogo Resetado com Sucesso!");
    } catch (err) {
      alert("Falha ao resetar. Verifique sua conexão.");
    } finally {
      setIsLoading(false);
    }
  };

  const deleteProduct = async (id: string) => {
    setIsLoading(true);
    try {
      await supabase.from('products').delete().eq('id', id);
      setProducts(prev => prev.filter(p => p.id !== id));
      setCart(prev => prev.filter(item => item.productId !== id));
    } catch (err) {} finally { setIsLoading(false); }
  };

  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStatus = !product.isActive;
    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));
    try { 
      await supabase.from('products').update({ is_active: newStatus, isActive: newStatus }).eq('id', id); 
    } catch (e) {}
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;
    const newProducts = [...products];
    const itemA = newProducts[index];
    const itemB = newProducts[targetIndex];
    [newProducts[index], newProducts[targetIndex]] = [newProducts[targetIndex], newProducts[index]];
    setProducts(newProducts.map((p, i) => ({ ...p, order_index: i })));
    try {
      await Promise.all([
        supabase.from('products').update({ order_index: targetIndex, orderIndex: targetIndex }).eq('id', itemA.id),
        supabase.from('products').update({ order_index: index, orderIndex: index }).eq('id', itemB.id)
      ]);
    } catch (e) {}
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;
    const updatedVariants = product.variants.map(v => v.id === variantId ? { ...v, isActive: !v.isActive } : v);
    setProducts(prev => prev.map(p => p.id === productId ? { ...product, variants: updatedVariants } : p));
    await supabase.from('products').update({ variants: updatedVariants }).eq('id', productId);
  };

  const updateSetting = async (key: string, value: any) => {
    try { await supabase.from('settings').upsert({ key, value }); } catch (e) {}
  };

  const handleUpdateWhatsapp = async (num: string) => { setWhatsappNumber(num); await updateSetting('whatsapp', num); };
  const handleUpdateCategories = async (newCats: any) => { 
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated); await updateSetting('categories', updated); 
  };
  const handleUpdatePresets = async (newPresets: any) => {
    const updated = typeof newPresets === 'function' ? newPresets(presets) : newPresets;
    setPresets(updated); await updateSetting('presets', updated);
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) return prev.map(item => (item.productId === product.id && item.variantId === variantId) ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, variantId, quantity: 1, productName: product.name, variantName: variant.name, price: variant.price }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) return prev.map(item => (item.productId === productId && item.variantId === variantId) ? { ...item, quantity: item.quantity - 1 } : item);
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const handleSendWhatsApp = (paymentMethod: string) => {
    if (!clientName || clientName.trim().length < 3) { alert('Insira seu nome.'); return; }
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName}) - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-6"></div>
          <h2 className="text-xl font-black uppercase text-neutral-900 dark:text-white tracking-widest mb-2">Doce Mania</h2>
          <p className="font-bold animate-pulse text-primary text-sm uppercase italic">Carregando Itens...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} addToCart={addToCart} removeFromCart={removeFromCart}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus} onToggleVariantStatus={toggleVariantStatus} onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={deleteProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onResetToDefaults={handleResetToDefaults}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} 
              presets={presets}
              productToEdit={productToEdit} 
              onSave={saveProduct} 
              onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} setCategories={handleUpdateCategories} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} setPresets={handleUpdatePresets} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({...v, price: Number(v.price)})));
    }
  }, [productToEdit]);

  // Função para limpar o link caso o usuário cole um código HTML (ex: <img src="...">)
  const handleImageChange = (val: string) => {
    let cleanLink = val.trim();
    if (cleanLink.includes('<img') && cleanLink.includes('src=')) {
      const match = cleanLink.match(/src="([^"]+)"/) || cleanLink.match(/src='([^']+)'/);
      if (match && match[1]) {
        cleanLink = match[1];
      }
    }
    setImage(cleanLink);
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    const newVariants = preset.variants.map(v => ({
      ...v,
      id: Math.random().toString(36).substr(2, 9)
    }));
    setVariants(newVariants);
    setShowPresets(false);
  };

  const handleAddVariant = () => {
    setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }]);
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length <= 1) {
      alert('O produto precisa ter pelo menos um preço.');
      return;
    }
    setVariants(prev => prev.filter(v => v.id !== id));
  };

  const handleVariantChange = (id: string, field: keyof ProductVariant, value: any) => {
    setVariants(prev => prev.map(v => {
      if (v.id === id) {
        const newValue = field === 'price' ? (value === '' ? 0 : parseFloat(value)) : value;
        return { ...v, [field]: newValue };
      }
      return v;
    }));
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage.from('product-images').upload(`products/${fileName}`, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
    } catch (error: any) {
      alert('Upload falhou: ' + (error.message || 'Erro de conexão'));
    } finally { setIsUploading(false); }
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) { 
      alert('Campo Nome e Marca são obrigatórios!'); 
      return; 
    }

    setIsSaving(true);
    try {
      const cleanVariants = variants.map(v => ({ 
        ...v, 
        price: Number(v.price) || 0, 
        name: v.name || 'Padrão' 
      }));

      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/300',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: cleanVariants
      });
    } catch (err: any) {
      const errorMsg = err.message || JSON.stringify(err);
      console.error("ERRO NO SUBMIT:", err);
      alert(`ERRO DE SALVAMENTO:\n\n${errorMsg}\n\nTente novamente ou use nomes mais simples.`);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b border-border-light dark:border-border-dark px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar Produto' : 'Novo Produto'}</h1>
      </div>

      <div className="px-4 pt-6 flex flex-col gap-6">
        {/* Informações Básicas */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div>
            <label className="block text-xs font-black uppercase text-primary mb-1.5 tracking-widest italic">Nome do Item</label>
            <input 
              value={name} 
              onChange={(e) => setName(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm font-bold focus:ring-primary focus:border-primary outline-none" 
              placeholder="Ex: Coca-Cola 2L" 
            />
          </div>
          <div>
            <label className="block text-xs font-black uppercase text-primary mb-1.5 tracking-widest italic">Marca / Categoria</label>
            <select 
              value={category} 
              onChange={(e) => setCategory(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm font-bold outline-none"
            >
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
        </div>

        {/* Imagem do Produto */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <h2 className="text-sm font-black uppercase italic tracking-widest flex items-center gap-2">
            <span className="material-symbols-outlined text-primary">add_a_photo</span> Foto
          </h2>
          <div className="p-3 bg-primary/5 rounded-xl border border-primary/20">
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest">Link Direto ou Código HTML</label>
            <input 
              value={image} 
              onChange={(e) => handleImageChange(e.target.value)} 
              className="w-full rounded-lg border-primary/30 bg-white dark:bg-black/40 p-3 text-xs focus:ring-primary outline-none font-mono" 
              placeholder="Cole o link ou o código da imagem aqui..." 
            />
          </div>
          <div className="relative group overflow-hidden rounded-xl border-2 border-dashed border-neutral-300 dark:border-white/10">
            <div className="w-full aspect-video bg-neutral-100 dark:bg-black/40 flex items-center justify-center">
              {image ? (
                <img src={image} className="w-full h-full object-contain" onError={(e) => (e.currentTarget.src = 'https://picsum.photos/400/300?text=Link+Invalido')} />
              ) : (
                <span className="material-symbols-outlined text-4xl opacity-20">photo_camera</span>
              )}
            </div>
            <button 
              onClick={() => fileInputRef.current?.click()} 
              disabled={isUploading}
              className="absolute bottom-2 right-2 bg-primary text-black p-3 rounded-xl shadow-lg disabled:opacity-50 active:scale-90 transition-transform"
            >
              <span className="material-symbols-outlined">{isUploading ? 'sync' : 'upload_file'}</span>
            </button>
          </div>
          <input type="file" ref={fileInputRef} className="hidden" onChange={handleImageUpload} accept="image/*" />
        </div>

        {/* Preços */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-sm font-black uppercase italic tracking-widest">Preços e Pesos</h2>
            <div className="flex gap-2">
              <button 
                onClick={() => setShowPresets(!showPresets)} 
                className="text-[10px] font-black uppercase text-blue-500 bg-blue-50 dark:bg-blue-900/20 px-2 py-1 rounded"
              >
                Presets
              </button>
              <button onClick={handleAddVariant} className="text-xs font-bold text-primary">+ Adicionar</button>
            </div>
          </div>

          {showPresets && presets.length > 0 && (
            <div className="p-3 bg-blue-50 dark:bg-blue-900/10 border border-blue-200 dark:border-blue-800 rounded-xl space-y-2">
              <p className="text-[10px] font-bold text-blue-600 dark:text-blue-400 uppercase tracking-widest">Sugestões Rápidas:</p>
              <div className="flex flex-wrap gap-2">
                {presets.map(p => (
                  <button 
                    key={p.id} 
                    onClick={() => handleApplyPreset(p)}
                    className="px-3 py-1.5 bg-white dark:bg-blue-900/30 border border-blue-300 dark:border-blue-700 text-[10px] font-bold rounded-lg shadow-sm"
                  >
                    {p.name}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="space-y-3">
            {variants.map(v => (
              <div key={v.id} className="flex flex-col gap-2 p-3 bg-background-light dark:bg-black/20 rounded-xl relative border border-transparent focus-within:border-primary/30 transition-all">
                <div className="flex gap-2">
                  <input 
                    value={v.name} 
                    onChange={(e) => handleVariantChange(v.id, 'name', e.target.value)} 
                    className="flex-1 bg-transparent border-none p-0 text-sm font-bold focus:ring-0 outline-none" 
                    placeholder="Ex: 48g, 140g ou Unitário" 
                  />
                  <button onClick={() => handleRemoveVariant(v.id)} className="text-red-400 hover:text-red-600 transition-colors">
                    <span className="material-symbols-outlined text-sm">delete</span>
                  </button>
                </div>
                <div className="flex items-center gap-1 font-black text-sm bg-white dark:bg-black/40 px-3 py-1.5 rounded-lg border border-border-light dark:border-white/10">
                  <span className="text-neutral-500">R$</span>
                  <input 
                    type="number" 
                    step="0.01" 
                    inputMode="decimal" 
                    value={v.price === 0 ? '' : v.price} 
                    onChange={(e) => handleVariantChange(v.id, 'price', e.target.value)} 
                    className="w-full bg-transparent border-none p-0 focus:ring-0 text-primary-dark dark:text-primary outline-none" 
                    placeholder="0,00" 
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full p-4 bg-white/95 dark:bg-surface-dark/95 backdrop-blur-md border-t border-border-light dark:border-border-dark flex gap-3 max-w-lg mx-auto left-1/2 -translate-x-1/2 z-50">
        <button 
          onClick={onCancel} 
          disabled={isSaving}
          className="flex-1 py-4 font-bold rounded-2xl border border-border-light disabled:opacity-50"
        >
          Cancelar
        </button>
        <button 
          onClick={handleSubmit} 
          disabled={isSaving || isUploading}
          className="flex-[2] py-4 bg-primary text-black font-bold rounded-2xl shadow-xl shadow-primary/20 active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
        >
          {isSaving ? (
            <div className="w-5 h-5 border-2 border-black border-t-transparent rounded-full animate-spin"></div>
          ) : (
            <span className="material-symbols-outlined font-black">check_circle</span>
          )}
          {isSaving ? 'Salvando...' : 'Finalizar Cadastro'}
        </button>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let { data: dbProducts, error } = await supabase.from('products').select('*').order('order_index', { ascending: true });

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));
        setProducts(normalized);
      } else {
        const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({ 
          ...p, 
          order_index: i,
          is_active: p.isActive,
          variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
        }));
        setProducts(seedProducts);
        await supabase.from('products').upsert(seedProducts);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const formatError = (err: any): string => {
    if (!err) return "Erro desconhecido";
    if (typeof err === 'string') return err;

    // Erros específicos do Supabase/Postgrest
    if (err.message) {
      let msg = err.message;
      if (err.details && err.details !== 'null') msg += ` - Detalhes: ${err.details}`;
      if (err.hint && err.hint !== 'null') msg += ` (Dica: ${err.hint})`;
      if (err.code) msg = `[${err.code}] ` + msg;
      return msg;
    }

    try {
      const stringified = JSON.stringify(err);
      if (stringified === '{}') return "Erro de sistema (Objeto Vazio)";
      return stringified;
    } catch {
      return String(err);
    }
  };

  const saveProduct = async (product: Product) => {
    try {
      const orderIndex = productToEdit?.order_index !== undefined ? productToEdit.order_index : products.length;

      const payload: any = {
        id: product.id,
        name: product.name,
        description: product.description || "",
        image: product.image,
        category: product.category,
        variants: JSON.parse(JSON.stringify(product.variants)), // Deep copy para evitar problemas de referência
        is_active: product.isActive,
        isActive: product.isActive,
        order_index: orderIndex,
        orderIndex: orderIndex
      };

      const { error } = await supabase.from('products').upsert(payload);

      if (error) {
        console.error("Erro no salvamento (Tentativa 1):", formatError(error));

        // Modo de segurança: Salva apenas o básico se colunas extras não existirem
        const minimalPayload = {
          id: product.id,
          name: product.name,
          image: product.image,
          category: product.category,
          description: product.description
        };

        const { error: error2 } = await supabase.from('products').upsert(minimalPayload);

        if (error2) {
          throw new Error(formatError(error2));
        }
      }

      const updatedProduct = { ...product, order_index: orderIndex };
      setProducts(prev => {
        const exists = prev.find(p => p.id === product.id);
        if (exists) return prev.map(p => p.id === product.id ? updatedProduct : p);
        return [...prev, updatedProduct];
      });

      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      throw new Error(formatError(err));
    }
  };

  const handleResetToDefaults = async () => {
    if (!confirm("Isso restaurará os itens originais do catálogo. Continuar?")) return;
    setIsLoading(true);
    try {
      await supabase.from('products').delete().neq('id', '0');
      const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({
        ...p,
        order_index: i,
        is_active: p.isActive,
        variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
      }));
      await supabase.from('products').upsert(seedProducts);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
      setCategories(CATEGORIES);
      alert("Catálogo Resetado!");
    } catch (err) {
      alert("Falha ao resetar catálogo.");
    } finally {
      setIsLoading(false);
    }
  };

  const deleteProduct = async (id: string) => {
    setIsLoading(true);
    try {
      await supabase.from('products').delete().eq('id', id);
      setProducts(prev => prev.filter(p => p.id !== id));
      setCart(prev => prev.filter(item => item.productId !== id));
    } catch (err) {} finally { setIsLoading(false); }
  };

  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStatus = !product.isActive;
    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));
    try { 
      await supabase.from('products').update({ is_active: newStatus, isActive: newStatus }).eq('id', id); 
    } catch (e) {}
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;
    const newProducts = [...products];
    const itemA = newProducts[index];
    const itemB = newProducts[targetIndex];
    [newProducts[index], newProducts[targetIndex]] = [newProducts[targetIndex], newProducts[index]];
    setProducts(newProducts.map((p, i) => ({ ...p, order_index: i })));
    try {
      await Promise.all([
        supabase.from('products').update({ order_index: targetIndex, orderIndex: targetIndex }).eq('id', itemA.id),
        supabase.from('products').update({ order_index: index, orderIndex: index }).eq('id', itemB.id)
      ]);
    } catch (e) {}
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;
    const updatedVariants = product.variants.map(v => v.id === variantId ? { ...v, isActive: !v.isActive } : v);
    setProducts(prev => prev.map(p => p.id === productId ? { ...product, variants: updatedVariants } : p));
    await supabase.from('products').update({ variants: updatedVariants }).eq('id', productId);
  };

  const updateSetting = async (key: string, value: any) => {
    try { await supabase.from('settings').upsert({ key, value }); } catch (e) {}
  };

  const handleUpdateWhatsapp = async (num: string) => { setWhatsappNumber(num); await updateSetting('whatsapp', num); };
  const handleUpdateCategories = async (newCats: any) => { 
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated); await updateSetting('categories', updated); 
  };
  const handleUpdatePresets = async (newPresets: any) => {
    const updated = typeof newPresets === 'function' ? newPresets(presets) : newPresets;
    setPresets(updated); await updateSetting('presets', updated);
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) return prev.map(item => (item.productId === product.id && item.variantId === variantId) ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, variantId, quantity: 1, productName: product.name, variantName: variant.name, price: variant.price }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) return prev.map(item => (item.productId === productId && item.variantId === variantId) ? { ...item, quantity: item.quantity - 1 } : item);
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const handleSendWhatsApp = (paymentMethod: string) => {
    if (!clientName || clientName.trim().length < 3) { alert('Insira seu nome.'); return; }
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName}) - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-6"></div>
          <h2 className="text-xl font-black uppercase text-neutral-900 dark:text-white tracking-widest mb-2">Doce Mania</h2>
          <p className="font-bold animate-pulse text-primary text-sm uppercase italic">Sincronizando Banco de Dados...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} addToCart={addToCart} removeFromCart={removeFromCart}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus} onToggleVariantStatus={toggleVariantStatus} onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={deleteProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onResetToDefaults={handleResetToDefaults}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} 
              presets={presets}
              productToEdit={productToEdit} 
              onSave={saveProduct} 
              onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} setCategories={handleUpdateCategories} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} setPresets={handleUpdatePresets} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({...v, price: Number(v.price)})));
    }
  }, [productToEdit]);

  // Função para limpar o link caso o usuário cole um código HTML (ex: <img src="...">)
  const handleImageChange = (val: string) => {
    let cleanLink = val.trim();

    // Suporte para extrair link de tags HTML completas
    if (cleanLink.toLowerCase().includes('<img') || cleanLink.toLowerCase().includes('src=')) {
      const srcMatch = cleanLink.match(/src=["']?([^"'\s>]+)["']?/i);
      if (srcMatch && srcMatch[1]) {
        cleanLink = srcMatch[1];
      }
    }

    setImage(cleanLink);
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    const newVariants = preset.variants.map(v => ({
      ...v,
      id: Math.random().toString(36).substr(2, 9)
    }));
    setVariants(newVariants);
    setShowPresets(false);
  };

  const handleAddVariant = () => {
    setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }]);
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length <= 1) {
      alert('O produto precisa ter pelo menos um preço.');
      return;
    }
    setVariants(prev => prev.filter(v => v.id !== id));
  };

  const handleVariantChange = (id: string, field: keyof ProductVariant, value: any) => {
    setVariants(prev => prev.map(v => {
      if (v.id === id) {
        const newValue = field === 'price' ? (value === '' ? 0 : parseFloat(value)) : value;
        return { ...v, [field]: newValue };
      }
      return v;
    }));
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage.from('product-images').upload(`products/${fileName}`, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
    } catch (error: any) {
      alert('Upload falhou: ' + (error.message || 'Verifique sua permissão de storage no Supabase'));
    } finally { setIsUploading(false); }
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) { 
      alert('Nome do Produto e Marca são obrigatórios!'); 
      return; 
    }

    setIsSaving(true);
    try {
      const cleanVariants = variants.map(v => ({ 
        ...v, 
        price: Number(v.price) || 0, 
        name: v.name || 'Padrão' 
      }));

      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/300?text=Sem+Foto',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: cleanVariants
      });
    } catch (err: any) {
      // Aqui garantimos que a mensagem de erro seja mostrada como texto, não como objeto
      const errorMsg = err.message || (typeof err === 'object' ? JSON.stringify(err) : String(err));
      console.error("FALHA CRÍTICA NO SALVAMENTO:", err);
      alert(`⚠️ ERRO AO SALVAR:\n\n${errorMsg}\n\nVerifique se o banco de dados está online.`);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b border-border-light dark:border-border-dark px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5 active:scale-90 transition-all">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar Item' : 'Novo Cadastro'}</h1>
      </div>

      <div className="px-4 pt-6 flex flex-col gap-6">
        {/* Info Base */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Nome Comercial</label>
            <input 
              value={name} 
              onChange={(e) => setName(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm font-bold focus:ring-primary outline-none transition-all" 
              placeholder="Ex: Salgadinho Torcida Pimenta" 
            />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Marca / Grupo</label>
            <select 
              value={category} 
              onChange={(e) => setCategory(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm font-bold outline-none"
            >
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
        </div>

        {/* Gestão de Imagem */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <h2 className="text-xs font-black uppercase italic tracking-widest flex items-center gap-2">
            <span className="material-symbols-outlined text-primary text-sm">image</span> Visual do Produto
          </h2>
          <div className="p-3 bg-primary/5 rounded-xl border border-primary/20">
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest">Link Direto ou Tag HTML (Extrai Auto)</label>
            <input 
              value={image} 
              onChange={(e) => handleImageChange(e.target.value)} 
              className="w-full rounded-lg border-primary/30 bg-white dark:bg-black/40 p-3 text-xs focus:ring-primary outline-none font-mono" 
              placeholder="Cole <img src='...'> ou link direto" 
            />
          </div>
          <div className="relative group overflow-hidden rounded-xl border-2 border-dashed border-neutral-300 dark:border-white/10">
            <div className="w-full aspect-video bg-neutral-100 dark:bg-black/40 flex items-center justify-center">
              {image ? (
                <img src={image} className="w-full h-full object-contain" onError={(e) => (e.currentTarget.src = 'https://picsum.photos/400/300?text=Erro+no+Link')} />
              ) : (
                <span className="material-symbols-outlined text-4xl opacity-20">add_photo_alternate</span>
              )}
            </div>
            <button 
              onClick={() => fileInputRef.current?.click()} 
              disabled={isUploading}
              className="absolute bottom-2 right-2 bg-primary text-black p-3 rounded-xl shadow-lg disabled:opacity-50 active:scale-95 transition-all"
            >
              <span className="material-symbols-outlined">{isUploading ? 'sync' : 'upload'}</span>
            </button>
          </div>
          <input type="file" ref={fileInputRef} className="hidden" onChange={handleImageUpload} accept="image/*" />
        </div>

        {/* Tabela de Preços */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-xs font-black uppercase italic tracking-widest">Variantes e Preços</h2>
            <div className="flex gap-2">
              <button 
                onClick={() => setShowPresets(!showPresets)} 
                className="text-[10px] font-black uppercase text-blue-500 bg-blue-50 dark:bg-blue-900/20 px-2 py-1 rounded"
              >
                Presets
              </button>
              <button onClick={handleAddVariant} className="text-[10px] font-black uppercase text-primary">+ Novo</button>
            </div>
          </div>

          {showPresets && presets.length > 0 && (
            <div className="p-3 bg-blue-50 dark:bg-blue-900/10 border border-blue-200 dark:border-blue-800 rounded-xl space-y-2 animate-in fade-in zoom-in-95 duration-200">
              <p className="text-[10px] font-bold text-blue-600 dark:text-blue-400 uppercase tracking-widest">Aplicar Grupo:</p>
              <div className="flex flex-wrap gap-2">
                {presets.map(p => (
                  <button 
                    key={p.id} 
                    onClick={() => handleApplyPreset(p)}
                    className="px-3 py-1.5 bg-white dark:bg-blue-900/30 border border-blue-300 dark:border-blue-700 text-[10px] font-bold rounded-lg shadow-sm active:scale-90 transition-transform"
                  >
                    {p.name}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="space-y-3">
            {variants.map(v => (
              <div key={v.id} className="flex flex-col gap-2 p-3 bg-background-light dark:bg-black/20 rounded-xl relative border border-transparent focus-within:border-primary/30 transition-all">
                <div className="flex gap-2">
                  <input 
                    value={v.name} 
                    onChange={(e) => handleVariantChange(v.id, 'name', e.target.value)} 
                    className="flex-1 bg-transparent border-none p-0 text-sm font-bold focus:ring-0 outline-none" 
                    placeholder="Ex: 50g ou Unitário" 
                  />
                  <button onClick={() => handleRemoveVariant(v.id)} className="text-red-400 hover:text-red-600 transition-colors">
                    <span className="material-symbols-outlined text-sm">delete</span>
                  </button>
                </div>
                <div className="flex items-center gap-1 font-black text-sm bg-white dark:bg-black/40 px-3 py-1.5 rounded-lg border border-border-light dark:border-white/10">
                  <span className="text-neutral-500">R$</span>
                  <input 
                    type="number" 
                    step="0.01" 
                    inputMode="decimal" 
                    value={v.price === 0 ? '' : v.price} 
                    onChange={(e) => handleVariantChange(v.id, 'price', e.target.value)} 
                    className="w-full bg-transparent border-none p-0 focus:ring-0 text-primary-dark dark:text-primary outline-none" 
                    placeholder="0,00" 
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full p-4 bg-white/95 dark:bg-surface-dark/95 backdrop-blur-md border-t border-border-light dark:border-border-dark flex gap-3 max-w-lg mx-auto left-1/2 -translate-x-1/2 z-50">
        <button 
          onClick={onCancel} 
          disabled={isSaving}
          className="flex-1 py-4 font-bold rounded-2xl border border-border-light dark:border-border-dark disabled:opacity-50"
        >
          Cancelar
        </button>
        <button 
          onClick={handleSubmit} 
          disabled={isSaving || isUploading}
          className="flex-[2] py-4 bg-primary text-black font-bold rounded-2xl shadow-xl shadow-primary/20 active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
        >
          {isSaving ? (
            <div className="w-5 h-5 border-2 border-black border-t-transparent rounded-full animate-spin"></div>
          ) : (
            <span className="material-symbols-outlined font-black">save_as</span>
          )}
          {isSaving ? 'Gravando...' : 'Salvar Produto'}
        </button>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let { data: dbProducts, error } = await supabase.from('products').select('*').order('order_index', { ascending: true });

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));
        setProducts(normalized);
      } else {
        const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({ 
          ...p, 
          order_index: i,
          is_active: p.isActive,
          variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
        }));
        setProducts(seedProducts);
        await supabase.from('products').upsert(seedProducts);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const formatError = (err: any): string => {
    if (!err) return "Erro desconhecido";
    if (typeof err === 'string') return err;

    // Extrai mensagem real de objetos de erro do Supabase
    if (err.message) {
      let msg = err.message;
      if (err.details && err.details !== 'null') msg += ` - ${err.details}`;
      if (err.hint && err.hint !== 'null') msg += ` (Dica: ${err.hint})`;
      return msg;
    }

    try {
      const stringified = JSON.stringify(err);
      return stringified === '{}' ? String(err) : stringified;
    } catch {
      return String(err);
    }
  };

  const saveProduct = async (product: Product) => {
    try {
      const orderIndex = productToEdit?.order_index !== undefined ? productToEdit.order_index : products.length;

      // Payload resiliente: envia variações de nomes de colunas para garantir que funcione no seu banco
      const payload: any = {
        id: product.id,
        name: product.name,
        description: product.description || "",
        image: product.image,
        category: product.category,
        variants: JSON.parse(JSON.stringify(product.variants)), 
        is_active: product.isActive,
        isActive: product.isActive,
        order_index: orderIndex,
        orderIndex: orderIndex
      };

      const { error } = await supabase.from('products').upsert(payload);

      if (error) {
        console.error("Erro no upsert:", error);
        // Tentativa de modo de segurança (apenas colunas básicas em caso de erro de esquema)
        const minimalPayload = {
          id: product.id,
          name: product.name,
          image: product.image,
          category: product.category,
          description: product.description
        };
        const { error: error2 } = await supabase.from('products').upsert(minimalPayload);
        if (error2) throw new Error(formatError(error2));
      }

      const updatedProduct = { ...product, order_index: orderIndex };
      setProducts(prev => {
        const exists = prev.find(p => p.id === product.id);
        if (exists) return prev.map(p => p.id === product.id ? updatedProduct : p);
        return [...prev, updatedProduct];
      });

      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      throw new Error(formatError(err));
    }
  };

  const handleResetToDefaults = async () => {
    if (!confirm("Isso apagará suas alterações e voltará ao catálogo original. Continuar?")) return;
    setIsLoading(true);
    try {
      await supabase.from('products').delete().neq('id', '0');
      const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({
        ...p,
        order_index: i,
        is_active: p.isActive,
        variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
      }));
      await supabase.from('products').upsert(seedProducts);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
      setCategories(CATEGORIES);
      alert("Catálogo Restaurado!");
    } catch (err) {
      alert("Erro ao restaurar catálogo: " + formatError(err));
    } finally {
      setIsLoading(false);
    }
  };

  const deleteProduct = async (id: string) => {
    setIsLoading(true);
    try {
      await supabase.from('products').delete().eq('id', id);
      setProducts(prev => prev.filter(p => p.id !== id));
      setCart(prev => prev.filter(item => item.productId !== id));
    } catch (err) {
      alert("Erro ao excluir: " + formatError(err));
    } finally { setIsLoading(false); }
  };

  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStatus = !product.isActive;
    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));
    try { 
      await supabase.from('products').update({ is_active: newStatus, isActive: newStatus }).eq('id', id); 
    } catch (e) {}
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;
    const newProducts = [...products];
    const itemA = newProducts[index];
    const itemB = newProducts[targetIndex];
    [newProducts[index], newProducts[targetIndex]] = [newProducts[targetIndex], newProducts[index]];
    setProducts(newProducts.map((p, i) => ({ ...p, order_index: i })));
    try {
      await Promise.all([
        supabase.from('products').update({ order_index: targetIndex, orderIndex: targetIndex }).eq('id', itemA.id),
        supabase.from('products').update({ order_index: index, orderIndex: index }).eq('id', itemB.id)
      ]);
    } catch (e) {}
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;
    const updatedVariants = product.variants.map(v => v.id === variantId ? { ...v, isActive: !v.isActive } : v);
    setProducts(prev => prev.map(p => p.id === productId ? { ...product, variants: updatedVariants } : p));
    await supabase.from('products').update({ variants: updatedVariants }).eq('id', productId);
  };

  const updateSetting = async (key: string, value: any) => {
    try { await supabase.from('settings').upsert({ key, value }); } catch (e) {}
  };

  const handleUpdateWhatsapp = async (num: string) => { setWhatsappNumber(num); await updateSetting('whatsapp', num); };
  const handleUpdateCategories = async (newCats: any) => { 
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated); await updateSetting('categories', updated); 
  };
  const handleUpdatePresets = async (newPresets: any) => {
    const updated = typeof newPresets === 'function' ? newPresets(presets) : newPresets;
    setPresets(updated); await updateSetting('presets', updated);
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) return prev.map(item => (item.productId === product.id && item.variantId === variantId) ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, variantId, quantity: 1, productName: product.name, variantName: variant.name, price: variant.price }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) return prev.map(item => (item.productId === productId && item.variantId === variantId) ? { ...item, quantity: item.quantity - 1 } : item);
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const handleSendWhatsApp = (paymentMethod: string) => {
    if (!clientName || clientName.trim().length < 3) { alert('Insira seu nome.'); return; }
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName}) - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-6"></div>
          <h2 className="text-xl font-black uppercase text-neutral-900 dark:text-white tracking-widest mb-2">Doce Mania</h2>
          <p className="font-bold animate-pulse text-primary text-sm uppercase italic">Sincronizando com o Servidor...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} addToCart={addToCart} removeFromCart={removeFromCart}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus} onToggleVariantStatus={toggleVariantStatus} onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={deleteProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onResetToDefaults={handleResetToDefaults}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} 
              presets={presets}
              productToEdit={productToEdit} 
              onSave={saveProduct} 
              onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} setCategories={handleUpdateCategories} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} setPresets={handleUpdatePresets} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({...v, price: Number(v.price)})));
    }
  }, [productToEdit]);

  // Função mágica: Extrai link se o usuário colar um código HTML do Google/Site
  const handleImageInput = (val: string) => {
    let text = val.trim();

    // Regex para encontrar o conteúdo do atributo src="..." ou apenas o link
    if (text.includes('<') && text.includes('src')) {
      const match = text.match(/src=["']?([^"'\s>]+)["']?/i);
      if (match && match[1]) {
        text = match[1];
      }
    }

    setImage(text);
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    const newVariants = preset.variants.map(v => ({
      ...v,
      id: Math.random().toString(36).substr(2, 9)
    }));
    setVariants(newVariants);
    setShowPresets(false);
  };

  const handleAddVariant = () => {
    setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }]);
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length <= 1) {
      alert('O produto precisa ter pelo menos um preço.');
      return;
    }
    setVariants(prev => prev.filter(v => v.id !== id));
  };

  const handleVariantChange = (id: string, field: keyof ProductVariant, value: any) => {
    setVariants(prev => prev.map(v => {
      if (v.id === id) {
        const newValue = field === 'price' ? (value === '' ? 0 : parseFloat(value)) : value;
        return { ...v, [field]: newValue };
      }
      return v;
    }));
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage.from('product-images').upload(`products/${fileName}`, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
    } catch (error: any) {
      alert('Upload falhou: ' + (error.message || 'Verifique as permissões de storage.'));
    } finally { setIsUploading(false); }
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) { 
      alert('Por favor, preencha o Nome e a Marca do produto.'); 
      return; 
    }

    setIsSaving(true);
    try {
      const cleanVariants = variants.map(v => ({ 
        ...v, 
        price: Number(v.price) || 0, 
        name: v.name || 'Padrão' 
      }));

      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/300?text=Sem+Imagem',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: cleanVariants
      });
    } catch (err: any) {
      const errorMsg = err.message || (typeof err === 'object' ? JSON.stringify(err) : String(err));
      console.error("ERRO NO SALVAMENTO:", err);
      alert(`⚠️ ERRO AO SALVAR:\n\n${errorMsg}\n\nVerifique se todas as colunas existem no banco.`);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      {/* Header */}
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b border-border-light dark:border-border-dark px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5 active:scale-90 transition-all">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar Produto' : 'Cadastrar Novo'}</h1>
      </div>

      <div className="px-4 pt-6 flex flex-col gap-6">
        {/* Info Base */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Título do Produto</label>
            <input 
              value={name} 
              onChange={(e) => setName(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm font-bold focus:ring-primary outline-none transition-all" 
              placeholder="Ex: Coca-Cola 350ml" 
            />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Marca / Categoria</label>
            <select 
              value={category} 
              onChange={(e) => setCategory(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm font-bold outline-none"
            >
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Descrição (Opcional)</label>
            <textarea 
              value={description} 
              onChange={(e) => setDescription(e.target.value)} 
              rows={2}
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm outline-none" 
              placeholder="Ex: Bebida refrescante gelada..." 
            />
          </div>
        </div>

        {/* Gestão de Imagem */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <h2 className="text-xs font-black uppercase italic tracking-widest flex items-center gap-2">
            <span className="material-symbols-outlined text-primary text-sm">photo_library</span> Imagem do Item
          </h2>
          <div className="p-3 bg-primary/5 rounded-xl border border-primary/20">
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest">Link Direto ou Código HTML</label>
            <input 
              value={image} 
              onChange={(e) => handleImageInput(e.target.value)} 
              className="w-full rounded-lg border-primary/30 bg-white dark:bg-black/40 p-3 text-xs focus:ring-primary outline-none font-mono" 
              placeholder="Cole o link ou o código da imagem..." 
            />
            <p className="text-[9px] text-neutral-500 mt-1 italic">*Você pode colar o código HTML do Google Imagens que nós extraímos o link!</p>
          </div>
          <div className="relative group overflow-hidden rounded-xl border-2 border-dashed border-neutral-300 dark:border-white/10">
            <div className="w-full aspect-video bg-neutral-100 dark:bg-black/40 flex items-center justify-center">
              {image ? (
                <img src={image} className="w-full h-full object-contain" onError={(e) => (e.currentTarget.src = 'https://picsum.photos/400/300?text=Erro+no+Link')} />
              ) : (
                <span className="material-symbols-outlined text-4xl opacity-20">add_photo_alternate</span>
              )}
            </div>
            <button 
              onClick={() => fileInputRef.current?.click()} 
              disabled={isUploading}
              className="absolute bottom-2 right-2 bg-primary text-black p-3 rounded-xl shadow-lg disabled:opacity-50 active:scale-95 transition-all"
            >
              <span className="material-symbols-outlined">{isUploading ? 'sync' : 'upload_file'}</span>
            </button>
          </div>
          <input type="file" ref={fileInputRef} className="hidden" onChange={handleImageUpload} accept="image/*" />
        </div>

        {/* Tabela de Preços */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-xs font-black uppercase italic tracking-widest">Preços por Variação</h2>
            <div className="flex gap-2">
              <button 
                onClick={() => setShowPresets(!showPresets)} 
                className="text-[10px] font-black uppercase text-blue-500 bg-blue-50 dark:bg-blue-900/20 px-2 py-1 rounded"
              >
                Presets
              </button>
              <button onClick={handleAddVariant} className="text-[10px] font-black uppercase text-primary">+ Adicionar</button>
            </div>
          </div>

          {showPresets && presets.length > 0 && (
            <div className="p-3 bg-blue-50 dark:bg-blue-900/10 border border-blue-200 dark:border-blue-800 rounded-xl space-y-2 animate-in fade-in zoom-in-95 duration-200">
              <p className="text-[10px] font-bold text-blue-600 dark:text-blue-400 uppercase tracking-widest">Aplicar Grupo:</p>
              <div className="flex flex-wrap gap-2">
                {presets.map(p => (
                  <button 
                    key={p.id} 
                    onClick={() => handleApplyPreset(p)}
                    className="px-3 py-1.5 bg-white dark:bg-blue-900/30 border border-blue-300 dark:border-blue-700 text-[10px] font-bold rounded-lg shadow-sm active:scale-90 transition-transform"
                  >
                    {p.name}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="space-y-3">
            {variants.map(v => (
              <div key={v.id} className="flex flex-col gap-2 p-3 bg-background-light dark:bg-black/20 rounded-xl relative border border-transparent focus-within:border-primary/30 transition-all">
                <div className="flex gap-2">
                  <input 
                    value={v.name} 
                    onChange={(e) => handleVariantChange(v.id, 'name', e.target.value)} 
                    className="flex-1 bg-transparent border-none p-0 text-sm font-bold focus:ring-0 outline-none" 
                    placeholder="Ex: Unitário ou 2 Litros" 
                  />
                  <button onClick={() => handleRemoveVariant(v.id)} className="text-red-400 hover:text-red-600 transition-colors">
                    <span className="material-symbols-outlined text-sm">delete</span>
                  </button>
                </div>
                <div className="flex items-center gap-1 font-black text-sm bg-white dark:bg-black/40 px-3 py-1.5 rounded-lg border border-border-light dark:border-white/10">
                  <span className="text-neutral-500">R$</span>
                  <input 
                    type="number" 
                    step="0.01" 
                    inputMode="decimal" 
                    value={v.price === 0 ? '' : v.price} 
                    onChange={(e) => handleVariantChange(v.id, 'price', e.target.value)} 
                    className="w-full bg-transparent border-none p-0 focus:ring-0 text-primary-dark dark:text-primary outline-none" 
                    placeholder="0,00" 
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full p-4 bg-white/95 dark:bg-surface-dark/95 backdrop-blur-md border-t border-border-light dark:border-border-dark flex gap-3 max-w-lg mx-auto left-1/2 -translate-x-1/2 z-50">
        <button 
          onClick={onCancel} 
          disabled={isSaving}
          className="flex-1 py-4 font-bold rounded-2xl border border-border-light dark:border-border-dark disabled:opacity-50"
        >
          Cancelar
        </button>
        <button 
          onClick={handleSubmit} 
          disabled={isSaving || isUploading}
          className="flex-[2] py-4 bg-primary text-black font-bold rounded-2xl shadow-xl shadow-primary/20 active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
        >
          {isSaving ? (
            <div className="w-5 h-5 border-2 border-black border-t-transparent rounded-full animate-spin"></div>
          ) : (
            <span className="material-symbols-outlined font-black">check_circle</span>
          )}
          {isSaving ? 'Gravando...' : 'Salvar Alterações'}
        </button>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let { data: dbProducts, error } = await supabase.from('products').select('*').order('order_index', { ascending: true });

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));
        setProducts(normalized);
      } else {
        const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({ 
          ...p, 
          order_index: i,
          is_active: p.isActive,
          variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
        }));
        setProducts(seedProducts);
        await supabase.from('products').upsert(seedProducts);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const formatError = (err: any): string => {
    if (!err) return "Erro desconhecido";
    if (typeof err === 'string') return err;

    // Trata erros específicos do Supabase PostgrestError
    if (err.message) {
      let msg = err.message;
      if (err.details && err.details !== 'null' && err.details !== '') msg += ` | Detalhes: ${err.details}`;
      if (err.hint && err.hint !== 'null' && err.hint !== '') msg += ` | Dica: ${err.hint}`;
      if (err.code) msg = `[${err.code}] ` + msg;
      return msg;
    }

    try {
      const stringified = JSON.stringify(err, null, 2);
      return stringified === '{}' ? String(err) : stringified;
    } catch {
      return String(err);
    }
  };

  const saveProduct = async (product: Product) => {
    try {
      const orderIndex = productToEdit?.order_index !== undefined 
        ? productToEdit.order_index 
        : products.length;

      // Criamos um payload compatível com snake_case e camelCase para evitar erros de esquema
      const payload: any = {
        id: product.id,
        name: product.name,
        description: product.description || "",
        image: product.image,
        category: product.category,
        variants: product.variants, // Supabase trata o array/objeto como JSONB
        is_active: product.isActive,
        isActive: product.isActive,
        order_index: orderIndex,
        orderIndex: orderIndex
      };

      const { error } = await supabase.from('products').upsert(payload);

      if (error) {
        console.error("Erro detalhado no Upsert:", error);

        // Tentativa 2: Modo de Segurança (apenas colunas garantidas)
        const minimalPayload = {
          id: product.id,
          name: product.name,
          image: product.image,
          category: product.category,
          description: product.description
        };

        const { error: error2 } = await supabase.from('products').upsert(minimalPayload);

        if (error2) {
          throw new Error(formatError(error2));
        } else {
          console.warn("Produto salvo parcialmente devido a restrições de colunas no banco.");
        }
      }

      // Atualização local imediata
      const updatedProduct = { ...product, order_index: orderIndex };
      setProducts(prev => {
        const exists = prev.find(p => p.id === product.id);
        if (exists) return prev.map(p => p.id === product.id ? updatedProduct : p);
        return [...prev, updatedProduct];
      });

      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      throw new Error(formatError(err));
    }
  };

  const handleResetToDefaults = async () => {
    if (!confirm("Restaurar o catálogo original? Isso apagará seus produtos atuais.")) return;
    setIsLoading(true);
    try {
      await supabase.from('products').delete().neq('id', '0');
      const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({
        ...p,
        order_index: i,
        is_active: p.isActive,
        variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
      }));
      await supabase.from('products').upsert(seedProducts);
      setProducts(INITIAL_PRODUCTS.map((p, i) => ({ ...p, order_index: i })));
      setCategories(CATEGORIES);
      alert("Catálogo Restaurado!");
    } catch (err) {
      alert("Falha ao restaurar: " + formatError(err));
    } finally {
      setIsLoading(false);
    }
  };

  const deleteProduct = async (id: string) => {
    setIsLoading(true);
    try {
      await supabase.from('products').delete().eq('id', id);
      setProducts(prev => prev.filter(p => p.id !== id));
      setCart(prev => prev.filter(item => item.productId !== id));
    } catch (err) {
      alert("Erro ao excluir: " + formatError(err));
    } finally { setIsLoading(false); }
  };

  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStatus = !product.isActive;
    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));
    try { 
      await supabase.from('products').update({ is_active: newStatus, isActive: newStatus }).eq('id', id); 
    } catch (e) {}
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;
    const newProducts = [...products];
    const itemA = newProducts[index];
    const itemB = newProducts[targetIndex];
    [newProducts[index], newProducts[targetIndex]] = [newProducts[targetIndex], newProducts[index]];
    setProducts(newProducts.map((p, i) => ({ ...p, order_index: i })));
    try {
      await Promise.all([
        supabase.from('products').update({ order_index: targetIndex, orderIndex: targetIndex }).eq(itemA.id, itemA.id),
        supabase.from('products').update({ order_index: index, orderIndex: index }).eq(itemB.id, itemB.id)
      ]);
    } catch (e) {}
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;
    const updatedVariants = product.variants.map(v => v.id === variantId ? { ...v, isActive: !v.isActive } : v);
    setProducts(prev => prev.map(p => p.id === productId ? { ...product, variants: updatedVariants } : p));
    await supabase.from('products').update({ variants: updatedVariants }).eq('id', productId);
  };

  const updateSetting = async (key: string, value: any) => {
    try { await supabase.from('settings').upsert({ key, value }); } catch (e) {}
  };

  const handleUpdateWhatsapp = async (num: string) => { setWhatsappNumber(num); await updateSetting('whatsapp', num); };
  const handleUpdateCategories = async (newCats: any) => { 
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated); await updateSetting('categories', updated); 
  };
  const handleUpdatePresets = async (newPresets: any) => {
    const updated = typeof newPresets === 'function' ? newPresets(presets) : newPresets;
    setPresets(updated); await updateSetting('presets', updated);
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) return prev.map(item => (item.productId === product.id && item.variantId === variantId) ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, variantId, quantity: 1, productName: product.name, variantName: variant.name, price: variant.price }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) return prev.map(item => (item.productId === productId && item.variantId === variantId) ? { ...item, quantity: item.quantity - 1 } : item);
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const handleSendWhatsApp = (paymentMethod: string) => {
    if (!clientName || clientName.trim().length < 3) { alert('Insira seu nome.'); return; }
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName}) - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-6"></div>
          <h2 className="text-xl font-black uppercase text-neutral-900 dark:text-white tracking-widest mb-2">Doce Mania</h2>
          <p className="font-bold animate-pulse text-primary text-sm uppercase italic">Conectando...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} addToCart={addToCart} removeFromCart={removeFromCart}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus} onToggleVariantStatus={toggleVariantStatus} onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={deleteProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onResetToDefaults={handleResetToDefaults}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} 
              presets={presets}
              productToEdit={productToEdit} 
              onSave={saveProduct} 
              onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} setCategories={handleUpdateCategories} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} setPresets={handleUpdatePresets} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({...v, price: Number(v.price)})));
    }
  }, [productToEdit]);

  // Função mágica aprimorada: Extrai o link se o usuário colar um código HTML completo ou link
  const handleImageInput = (val: string) => {
    let input = val.trim();

    // Se o input parecer HTML (tem tags ou src=)
    if (input.includes('<') || input.includes('src=')) {
      // Regex que busca o valor dentro de src="URL" ou src='URL' ou src=URL
      const srcMatch = input.match(/src=["']?([^"'\s>]+)["']?/i);
      if (srcMatch && srcMatch[1]) {
        input = srcMatch[1];
      }
    }

    setImage(input);
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    const newVariants = preset.variants.map(v => ({
      ...v,
      id: Math.random().toString(36).substr(2, 9)
    }));
    setVariants(newVariants);
    setShowPresets(false);
  };

  const handleAddVariant = () => {
    setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }]);
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length <= 1) {
      alert('O produto precisa ter pelo menos um preço.');
      return;
    }
    setVariants(prev => prev.filter(v => v.id !== id));
  };

  const handleVariantChange = (id: string, field: keyof ProductVariant, value: any) => {
    setVariants(prev => prev.map(v => {
      if (v.id === id) {
        // Garantir que preço seja número
        const newValue = field === 'price' ? (value === '' ? 0 : parseFloat(value)) : value;
        return { ...v, [field]: newValue };
      }
      return v;
    }));
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage.from('product-images').upload(`products/${fileName}`, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
    } catch (error: any) {
      alert('Upload falhou: ' + (error.message || 'Erro desconhecido de Storage'));
    } finally { setIsUploading(false); }
  };

  const handleSubmit = async () => {
    if (!name.trim() || !category) { 
      alert('Nome e Marca são obrigatórios!'); 
      return; 
    }

    setIsSaving(true);
    try {
      const cleanVariants = variants.map(v => ({ 
        ...v, 
        price: Number(v.price) || 0, 
        name: v.name.trim() || 'Padrão' 
      }));

      await onSave({
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/300?text=Sem+Imagem',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: cleanVariants
      });
    } catch (err: any) {
      // Aqui garantimos que o erro não apareça como [object Object]
      const errorMsg = err.message || (typeof err === 'object' ? JSON.stringify(err) : String(err));
      console.error("ERRO CRÍTICO NO FORMULÁRIO:", err);
      alert(`⚠️ ERRO AO SALVAR:\n\n${errorMsg}\n\nVerifique sua conexão ou as colunas do seu banco de dados.`);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      {/* Top Bar */}
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b border-border-light dark:border-border-dark px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5 dark:hover:bg-white/5 active:scale-90 transition-all">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar Produto' : 'Adicionar Item'}</h1>
      </div>

      <div className="px-4 pt-6 flex flex-col gap-6">
        {/* Dados Básicos */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Título</label>
            <input 
              value={name} 
              onChange={(e) => setName(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm font-bold focus:ring-primary outline-none transition-all" 
              placeholder="Ex: Doce de Leite Caseiro" 
            />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Marca / Categoria</label>
            <select 
              value={category} 
              onChange={(e) => setCategory(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm font-bold outline-none"
            >
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Descrição Curta</label>
            <textarea 
              value={description} 
              onChange={(e) => setDescription(e.target.value)} 
              rows={2}
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm outline-none" 
              placeholder="Fale um pouco sobre o produto..." 
            />
          </div>
        </div>

        {/* Imagem do Produto */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <h2 className="text-xs font-black uppercase italic tracking-widest flex items-center gap-2">
            <span className="material-symbols-outlined text-primary text-sm">image</span> Visual
          </h2>
          <div className="p-3 bg-primary/5 rounded-xl border border-primary/20">
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest">Link da Imagem (Pode colar código HTML!)</label>
            <input 
              value={image} 
