              disabled={isUploading}
              className="absolute bottom-2 right-2 bg-primary text-black p-3 rounded-xl shadow-lg disabled:opacity-50 active:scale-95 transition-all"
            >
              <span className="material-symbols-outlined">{isUploading ? 'sync' : 'upload'}</span>
            </button>
          </div>
          <input type="file" ref={fileInputRef} className="hidden" onChange={handleImageUpload} accept="image/*" />
