        {/* Variações de Preço */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-xs font-black uppercase italic tracking-widest">Preços e Pesos</h2>
            <div className="flex gap-2">
              <button 
                onClick={() => setShowPresets(!showPresets)} 
