                <div className="flex items-center gap-1 font-black text-sm bg-white dark:bg-black/40 px-3 py-1.5 rounded-lg border border-border-light dark:border-white/10">
                  <span className="text-neutral-500">R$</span>
                  <input 
                    type="number" 
                    step="0.01" 
                    inputMode="decimal" 
                    value={v.price === 0 ? '' : v.price} 
                    onChange={(e) => handleVariantChange(v.id, 'price', e.target.value)} 
                    className="w-full bg-transparent border-none p-0 focus:ring-0 text-primary-dark dark:text-primary outline-none" 
                    placeholder="0,00" 
