import React, { useState, useRef } from 'react';
import { Product, CartItem } from '../types';

declare var html2canvas: any;

interface CatalogViewProps {
  products: Product[];
  categories: string[];
  cart: CartItem[];
  addToCart: (p: Product, variantId: string) => void;
  removeFromCart: (pId: string, vId: string) => void;
  clientName: string;
  setClientName: (name: string) => void;
  onSendWhatsApp: (paymentMethod: string) => void;
  onOpenSettings: () => void;
}

const CatalogView: React.FC<CatalogViewProps> = ({ 
  products, categories, cart, addToCart, removeFromCart, clientName, setClientName, onSendWhatsApp, onOpenSettings 
}) => {
  const [selectedCategory, setSelectedCategory] = useState('Todas');
  const [paymentMethod, setPaymentMethod] = useState<'Pix' | 'Dinheiro'>('Dinheiro');
  const [isProcessing, setIsProcessing] = useState(false);
  const receiptRef = useRef<HTMLDivElement>(null);

  const filteredProducts = selectedCategory === 'Todas' 
    ? products 
    : products.filter(p => p.category === selectedCategory);

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const isNameValid = clientName.trim().length >= 3;
  const isOrderValid = cart.length > 0 && isNameValid;

  const getQuantity = (pId: string, vId: string) => {
    return cart.find(item => item.productId === pId && item.variantId === vId)?.quantity || 0;
  };

  const handleConfirmOrder = async () => {
    if (!isOrderValid) return;
    setIsProcessing(true);
    try {
      await new Promise(r => setTimeout(r, 300));
      if (receiptRef.current && navigator.share) {
        const canvas = await html2canvas(receiptRef.current, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          logging: false
        });
        const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));
        if (blob) {
          const file = new File([blob], `pedido-${Date.now()}.png`, { type: 'image/png' });
          const cartText = cart.map(item => `• ${item.quantity}x ${item.productName} (${item.variantName})`).join('\n');
          const shareData = {
            title: 'Pedido - Doce Mania',
            text: `*NOVO PEDIDO*\n👤 Cliente: ${clientName}\n💳 Pagamento: ${paymentMethod}\n💰 Total: R$ ${total.toFixed(2)}\n\nItens:\n${cartText}`,
            files: [file]
          };
          if (navigator.canShare && navigator.canShare(shareData)) {
            await navigator.share(shareData);
            setIsProcessing(false);
            return;
          }
        }
      }
      onSendWhatsApp(paymentMethod);
    } catch (err) {
      onSendWhatsApp(paymentMethod);
    } finally {
      setIsProcessing(false);
    }
  };

  const currentDate = new Date().toLocaleDateString('pt-BR');
  const currentTime = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });

  return (
    <div className="flex-1 w-full max-md:max-w-md mx-auto bg-background-light dark:bg-background-dark min-h-screen flex flex-col">
      {isProcessing && (
        <div className="fixed inset-0 z-[100] bg-black/60 flex flex-col items-center justify-center text-white">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="font-bold">Gerando Cupom...</p>
        </div>
      )}

      <header className="sticky top-0 z-50 w-full bg-background-light/90 dark:bg-background-dark/90 backdrop-blur-md shadow-sm border-b px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 flex items-center justify-center rounded-full bg-primary/20 text-primary">
            <span className="material-symbols-outlined">storefront</span>
          </div>
          <h1 className="font-bold">Catalogo Doce Mania</h1>
        </div>
        <button onClick={onOpenSettings} className="p-2 rounded-full text-neutral-500">
          <span className="material-symbols-outlined">settings</span>
        </button>
      </header>

      <main className="flex-1 pb-64 px-4 pt-6">
        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-6 -mx-4 px-4">
          {['Todas', ...categories].map(cat => (
            <button key={cat} onClick={() => setSelectedCategory(cat)} className={`shrink-0 px-4 py-2 rounded-full text-sm font-bold transition-all ${selectedCategory === cat ? 'bg-primary text-black' : 'bg-white dark:bg-white/5 border'}`}>
              {cat}
            </button>
          ))}
        </div>

        <div className="flex flex-col gap-6">
          {filteredProducts.map(product => {
            const variantsArray = Array.isArray(product.variants) ? product.variants : [];
            const activeVariants = variantsArray.filter(v => v.isActive);
            if (activeVariants.length === 0) return null;

            return (
              <article key={product.id} className="rounded-2xl bg-white dark:bg-white/5 p-3 border shadow-sm">
                <div className="aspect-video w-full overflow-hidden rounded-xl bg-neutral-100 mb-3">
                  <img 
                    src={product.image || 'https://picsum.photos/400/300?grayscale'} 
                    alt={product.name}
                    className="h-full w-full object-cover"
                    onError={(e) => { e.currentTarget.src = 'https://picsum.photos/400/300?grayscale'; }}
                  />
                </div>
                <h3 className="font-bold">{product.name}</h3>
                <div className="mt-4 space-y-3">
                  {activeVariants.map((variant) => {
                    const qty = getQuantity(product.id, variant.id);
                    return (
                      <div key={variant.id} className="flex items-center justify-between">
                        <div className="flex flex-col">
                          {activeVariants.length > 1 && <span className="text-[10px] text-neutral-500 uppercase font-bold">{variant.name}</span>}
                          <span className="font-extrabold text-primary-dark dark:text-primary">R$ {Number(variant.price).toFixed(2)}</span>
                        </div>
                        <div className="flex items-center bg-neutral-100 dark:bg-black/30 rounded-full p-1">
                          {qty > 0 ? (
                            <>
                              <button onClick={() => removeFromCart(product.id, variant.id)} className="w-8 h-8 bg-white dark:bg-neutral-700 rounded-full flex items-center justify-center"><span className="material-symbols-outlined text-sm">remove</span></button>
                              <span className="w-8 text-center text-sm font-bold">{qty}</span>
                              <button onClick={() => addToCart(product, variant.id)} className="w-8 h-8 bg-primary rounded-full flex items-center justify-center text-black"><span className="material-symbols-outlined text-sm">add</span></button>
                            </>
                          ) : (
                            <button onClick={() => addToCart(product, variant.id)} className="px-4 py-1 text-xs font-bold uppercase">Add</button>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </article>
            );
          })}
        </div>

        {cart.length > 0 && (
          <div ref={receiptRef} className="mt-12 p-6 bg-white text-black font-mono text-[11px] rounded shadow-xl border-t-4 border-primary">
            <h3 className="text-center font-bold mb-4">DOCE MANIA - RESUMO</h3>
            <div className="flex justify-between mb-4"><span>{currentDate}</span><span>{currentTime}</span></div>
            <p className="mb-2">CLIENTE: {clientName.toUpperCase()}</p>
            <p className="mb-4">PAGAMENTO: {paymentMethod.toUpperCase()}</p>
            <div className="border-y py-2 mb-4">
              {cart.map(item => (
                <div key={item.variantId} className="flex justify-between">
                  <span>{item.quantity}x {item.productName}</span>
                  <span>R$ {(item.price * item.quantity).toFixed(2)}</span>
                </div>
              ))}
            </div>
            <div className="flex justify-between font-bold text-sm"><span>TOTAL</span><span>R$ {total.toFixed(2)}</span></div>
          </div>
        )}

        <div className="mt-8 space-y-4 mb-32">
          <input 
            value={clientName} 
            onChange={(e) => setClientName(e.target.value)} 
            placeholder="Seu Nome Completo" 
            className="w-full p-4 rounded-xl border dark:bg-black/20" 
          />
          <div className="grid grid-cols-2 gap-3">
            <button onClick={() => setPaymentMethod('Pix')} className={`p-4 rounded-xl border font-bold ${paymentMethod === 'Pix' ? 'bg-primary/20 border-primary text-primary-dark' : ''}`}>Pix</button>
            <button onClick={() => setPaymentMethod('Dinheiro')} className={`p-4 rounded-xl border font-bold ${paymentMethod === 'Dinheiro' ? 'bg-primary/20 border-primary text-primary-dark' : ''}`}>Dinheiro</button>
          </div>
        </div>
      </main>

      <div className="fixed bottom-0 left-0 w-full p-4">
        <button onClick={handleConfirmOrder} disabled={!isOrderValid || isProcessing} className={`w-full py-4 rounded-2xl font-bold text-lg shadow-xl ${!isOrderValid ? 'bg-neutral-300' : 'bg-primary'}`}>
          Confirmar Pedido (R$ {total.toFixed(2)})
        </button>
      </div>
    </div>
  );
};

