import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let { data: dbProducts, error } = await supabase.from('products').select('*').order('order_index', { ascending: true });

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));
        setProducts(normalized);
      } else {
        const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({ 
          ...p, 
          order_index: i,
          is_active: p.isActive,
          variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
        }));
        setProducts(seedProducts);
        await supabase.from('products').upsert(seedProducts);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const formatError = (err: any): string => {
    if (!err) return "Erro desconhecido";
    if (typeof err === 'string') return err;
    if (err.message) {
      let msg = err.message;
      if (err.details && err.details !== 'null') msg += ` | Detalhes: ${err.details}`;
      return msg;
    }
    return JSON.stringify(err);
  };

  const saveProduct = async (product: Product) => {
    try {
      const orderIndex = productToEdit?.order_index !== undefined 
        ? productToEdit.order_index 
        : products.length;

      const payload = {
        id: product.id,
        name: product.name,
        description: product.description || "",
        image: product.image,
        category: product.category,
        variants: product.variants,
        is_active: product.isActive,
        isActive: product.isActive,
        order_index: orderIndex
      };

      const { error } = await supabase.from('products').upsert(payload);
      if (error) throw error;

      const updatedProduct = { ...product, order_index: orderIndex };
      setProducts(prev => {
        const exists = prev.find(p => p.id === product.id);
        if (exists) return prev.map(p => p.id === product.id ? updatedProduct : p);
        return [...prev, updatedProduct];
      });

      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      alert("Erro ao salvar: " + formatError(err));
    }
  };

  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStatus = !product.isActive;

    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));

    try { 
      await supabase.from('products').update({ is_active: newStatus, isActive: newStatus }).eq('id', id); 
    } catch (e) {
      console.error(e);
    }
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;

    const newProducts = [...products];
    const itemA = { ...newProducts[index] };
    const itemB = { ...newProducts[targetIndex] };

    itemA.order_index = targetIndex;
    itemB.order_index = index;

    newProducts[index] = itemB;
    newProducts[targetIndex] = itemA;

    setProducts(newProducts);

    try {
      await Promise.all([
        supabase.from('products').update({ order_index: targetIndex }).eq('id', itemA.id),
        supabase.from('products').update({ order_index: index }).eq('id', itemB.id)
      ]);
    } catch (e) {
      console.error(e);
    }
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;

    const updatedVariants = product.variants.map(v => 
      v.id === variantId ? { ...v, isActive: !v.isActive } : v
    );

    // Atualiza estado local
    setProducts(prev => prev.map(p => 
      p.id === productId ? { ...p, variants: updatedVariants } : p
    ));

    // Persiste no Supabase
    try {
      await supabase.from('products').update({ variants: updatedVariants }).eq('id', productId);
    } catch (e) {
      console.error("Erro ao salvar status da variação:", e);
    }
  };

  const deleteProduct = async (id: string) => {
    if (!confirm("Excluir este produto permanentemente?")) return;
    try {
      await supabase.from('products').delete().eq('id', id);
      setProducts(prev => prev.filter(p => p.id !== id));
    } catch (err) {
      alert("Erro ao excluir: " + formatError(err));
    }
  };

  const handleResetToDefaults = async () => {
    if (!confirm("Restaurar catálogo original?")) return;
    setIsLoading(true);
    try {
      await supabase.from('products').delete().neq('id', '0');
      const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({
        ...p,
        order_index: i,
        is_active: p.isActive,
        variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
      }));
      await supabase.from('products').upsert(seedProducts);
      fetchData();
    } catch (err) {
      alert("Erro ao restaurar: " + formatError(err));
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateWhatsapp = async (num: string) => { 
    setWhatsappNumber(num); 
    await supabase.from('settings').upsert({ key: 'whatsapp', value: num }); 
  };

  const handleUpdateCategories = async (newCats: any) => { 
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated); 
    await supabase.from('settings').upsert({ key: 'categories', value: updated }); 
  };

  const handleUpdatePresets = async (newPresets: any) => {
    const updated = typeof newPresets === 'function' ? newPresets(presets) : newPresets;
    setPresets(updated); 
    await supabase.from('settings').upsert({ key: 'presets', value: updated });
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) return prev.map(item => (item.productId === product.id && item.variantId === variantId) ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, variantId, quantity: 1, productName: product.name, variantName: variant.name, price: variant.price }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) return prev.map(item => (item.productId === productId && item.variantId === variantId) ? { ...item, quantity: item.quantity - 1 } : item);
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const handleSendWhatsApp = (paymentMethod: string) => {
    if (!clientName || clientName.trim().length < 3) { alert('Insira seu nome.'); return; }
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName}) - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-6"></div>
          <h2 className="text-xl font-black uppercase text-neutral-900 dark:text-white tracking-widest mb-2">Doce Mania</h2>
          <p className="font-bold animate-pulse text-primary text-sm uppercase italic">Sincronizando...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} addToCart={addToCart} removeFromCart={removeFromCart}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus} onToggleVariantStatus={toggleVariantStatus} onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={deleteProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onResetToDefaults={handleResetToDefaults}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} 
              presets={presets}
              productToEdit={productToEdit} 
              onSave={saveProduct} 
              onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} setCategories={handleUpdateCategories} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} setPresets={handleUpdatePresets} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let { data: dbProducts, error } = await supabase.from('products').select('*').order('order_index', { ascending: true });

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.is_active ?? v.isActive ?? true,
            price: Number(v.price)
          }))
        }));
        setProducts(normalized);
      } else {
        const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({ 
          ...p, 
          order_index: i,
          is_active: p.isActive,
          variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
        }));
        setProducts(seedProducts);
        await supabase.from('products').upsert(seedProducts);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const formatError = (err: any): string => {
    if (!err) return "Erro desconhecido";
    if (typeof err === 'string') return err;
    if (err.message) return err.message;
    try {
      return JSON.stringify(err);
    } catch {
      return String(err);
    }
  };

  const saveProduct = async (product: Product) => {
    try {
      const orderIndex = productToEdit?.order_index !== undefined 
        ? productToEdit.order_index 
        : products.length;

      // Criamos um payload limpo, garantindo que variants seja um array puro e os boofenos estejam em snake_case para o banco
      const payload: any = {
        id: product.id,
        name: product.name,
        description: product.description || "",
        image: product.image,
        category: product.category,
        variants: JSON.parse(JSON.stringify(product.variants)), // Garante que não há proxies do React
        is_active: product.isActive,
        isActive: product.isActive, // Envia ambos para compatibilidade
        order_index: orderIndex
      };

      const { error } = await supabase.from('products').upsert(payload);

      if (error) {
        // Se falhar, tenta uma versão minimalista apenas com colunas básicas
        console.error("Tentativa falha de salvamento completo:", error);
        const { error: retryError } = await supabase.from('products').upsert({
          id: payload.id,
          name: payload.name,
          category: payload.category,
          image: payload.image,
          description: payload.description,
          variants: payload.variants,
          order_index: payload.order_index
        });
        if (retryError) throw retryError;
      }

      const updatedProduct = { ...product, order_index: orderIndex };
      setProducts(prev => {
        const exists = prev.find(p => p.id === product.id);
        if (exists) return prev.map(p => p.id === product.id ? updatedProduct : p);
        return [...prev, updatedProduct];
      });

      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      console.error("Erro fatal ao salvar:", err);
      alert("Erro ao salvar no banco de dados: " + formatError(err));
    }
  };

  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStatus = !product.isActive;

    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));

    try { 
      await supabase.from('products').update({ is_active: newStatus, isActive: newStatus }).eq('id', id); 
    } catch (e) {
      console.error(e);
    }
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;

    const newProducts = [...products];
    const itemA = { ...newProducts[index] };
    const itemB = { ...newProducts[targetIndex] };

    itemA.order_index = targetIndex;
    itemB.order_index = index;

    newProducts[index] = itemB;
    newProducts[targetIndex] = itemA;

    setProducts(newProducts);

    try {
      await Promise.all([
        supabase.from('products').update({ order_index: targetIndex }).eq('id', itemA.id),
        supabase.from('products').update({ order_index: index }).eq('id', itemB.id)
      ]);
    } catch (e) {
      console.error(e);
    }
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;

    const updatedVariants = product.variants.map(v => 
      v.id === variantId ? { ...v, isActive: !v.isActive } : v
    );

    setProducts(prev => prev.map(p => 
      p.id === productId ? { ...p, variants: updatedVariants } : p
    ));

    try {
      await supabase.from('products').update({ variants: updatedVariants }).eq('id', productId);
    } catch (e) {
      console.error("Erro ao salvar status da variação:", e);
    }
  };

  const deleteProduct = async (id: string) => {
    if (!confirm("Excluir este produto permanentemente?")) return;
    try {
      await supabase.from('products').delete().eq('id', id);
      setProducts(prev => prev.filter(p => p.id !== id));
    } catch (err) {
      alert("Erro ao excluir: " + formatError(err));
    }
  };

  const handleResetToDefaults = async () => {
    if (!confirm("Restaurar catálogo original?")) return;
    setIsLoading(true);
    try {
      await supabase.from('products').delete().neq('id', '0');
      const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({
        ...p,
        order_index: i,
        is_active: p.isActive,
        variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
      }));
      await supabase.from('products').upsert(seedProducts);
      fetchData();
    } catch (err) {
      alert("Erro ao restaurar: " + formatError(err));
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateWhatsapp = async (num: string) => { 
    setWhatsappNumber(num); 
    await supabase.from('settings').upsert({ key: 'whatsapp', value: num }); 
  };

  const handleUpdateCategories = async (newCats: any) => { 
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated); 
    await supabase.from('settings').upsert({ key: 'categories', value: updated }); 
  };

  const handleUpdatePresets = async (newPresets: any) => {
    const updated = typeof newPresets === 'function' ? newPresets(presets) : newPresets;
    setPresets(updated); 
    await supabase.from('settings').upsert({ key: 'presets', value: updated });
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) return prev.map(item => (item.productId === product.id && item.variantId === variantId) ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, variantId, quantity: 1, productName: product.name, variantName: variant.name, price: variant.price }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) return prev.map(item => (item.productId === productId && item.variantId === variantId) ? { ...item, quantity: item.quantity - 1 } : item);
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const handleSendWhatsApp = (paymentMethod: string) => {
    if (!clientName || clientName.trim().length < 3) { alert('Insira seu nome.'); return; }
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName}) - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-6"></div>
          <h2 className="text-xl font-black uppercase text-neutral-900 dark:text-white tracking-widest mb-2">Doce Mania</h2>
          <p className="font-bold animate-pulse text-primary text-sm uppercase italic">Sincronizando...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} addToCart={addToCart} removeFromCart={removeFromCart}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus} onToggleVariantStatus={toggleVariantStatus} onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={deleteProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onResetToDefaults={handleResetToDefaults}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} 
              presets={presets}
              productToEdit={productToEdit} 
              onSave={saveProduct} 
              onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} setCategories={handleUpdateCategories} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} setPresets={handleUpdatePresets} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({...v, price: Number(v.price), isActive: v.isActive ?? true})));
    }
  }, [productToEdit]);

  const handleImageInput = (val: string) => {
    let raw = val.trim();
    // Extrai o src se for uma tag <img> do HTML
    if (raw.includes('<') && raw.includes('src=')) {
      const srcMatch = raw.match(/src=["']?([^"'\s>]+)["']?/i);
      if (srcMatch && srcMatch[1]) {
        raw = srcMatch[1];
      }
    }
    setImage(raw);
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    const newVariants = preset.variants.map(v => ({
      ...v,
      id: Math.random().toString(36).substr(2, 9),
      isActive: true
    }));
    setVariants(newVariants);
    setShowPresets(false);
  };

  const handleAddVariant = () => {
    setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }]);
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length <= 1) {
      alert('O produto precisa ter pelo menos um preço.');
      return;
    }
    setVariants(prev => prev.filter(v => v.id !== id));
  };

  const handleVariantChange = (id: string, field: keyof ProductVariant, value: any) => {
    setVariants(prev => prev.map(v => {
      if (v.id === id) {
        let newValue = value;
        if (field === 'price') {
          newValue = value === '' ? 0 : parseFloat(value);
        }
        return { ...v, [field]: newValue };
      }
      return v;
    }));
  };

  const toggleVariantStatus = (id: string) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, isActive: !v.isActive } : v));
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage.from('product-images').upload(`products/${fileName}`, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
    } catch (error: any) {
      alert('Falha no upload: ' + (error.message || 'Erro desconhecido.'));
    } finally { setIsUploading(false); }
  };

  const handleSubmit = async () => {
    if (!name.trim()) { 
      alert('O nome do item é obrigatório!'); 
      return; 
    }
    if (!category) {
      alert('Selecione uma marca/categoria!');
      return;
    }

    setIsSaving(true);
    try {
      const cleanVariants = variants.map(v => ({ 
        ...v, 
        price: Number(v.price) || 0, 
        name: v.name.trim() || 'Padrão' 
      }));

      const productData: Product = {
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/300?text=Doce+Mania',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: cleanVariants
      };

      await onSave(productData);
    } catch (err: any) {
      // O App.tsx já mostra o alert, mas garantimos aqui também se necessário
      console.error("Erro ao submeter formulário:", err);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b border-border-light dark:border-border-dark px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5 dark:hover:bg-white/5 active:scale-90 transition-all">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar Produto' : 'Novo Item'}</h1>
      </div>

      <div className="px-4 pt-6 flex flex-col gap-6">
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Nome do Item</label>
            <input 
              value={name} 
              onChange={(e) => setName(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm font-bold focus:ring-primary outline-none transition-all" 
              placeholder="Ex: Coca-Cola 350ml" 
            />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Marca / Categoria</label>
            <select 
              value={category} 
              onChange={(e) => setCategory(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm font-bold outline-none"
            >
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Descrição</label>
            <textarea 
              value={description} 
              onChange={(e) => setDescription(e.target.value)} 
              rows={2}
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm outline-none" 
              placeholder="Opcional..." 
            />
          </div>
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <h2 className="text-xs font-black uppercase italic tracking-widest text-primary flex items-center gap-2">
            <span className="material-symbols-outlined text-sm">photo_camera</span> Imagem
          </h2>
          <div className="p-3 bg-primary/5 rounded-xl border border-primary/20">
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest">Link Direto ou Código HTML</label>
            <input 
              value={image} 
              onChange={(e) => handleImageInput(e.target.value)} 
              className="w-full rounded-lg border-primary/30 bg-white dark:bg-black/40 p-3 text-xs focus:ring-primary outline-none font-mono" 
              placeholder="Cole o link ou o código da imagem..." 
            />
          </div>
          <div className="relative overflow-hidden rounded-xl border-2 border-dashed border-neutral-300 dark:border-white/10 aspect-video bg-neutral-100 dark:bg-black/40 flex items-center justify-center">
            {image ? (
              <img 
                src={image} 
                className="w-full h-full object-contain" 
                alt="Preview" 
                onError={(e) => { e.currentTarget.src = 'https://picsum.photos/400/300?text=Erro+no+Link'; }}
              />
            ) : (
              <span className="material-symbols-outlined text-4xl opacity-20">image</span>
            )}
            <button 
              type="button"
              onClick={() => fileInputRef.current?.click()} 
              disabled={isUploading}
              className="absolute bottom-2 right-2 bg-primary text-black p-3 rounded-xl shadow-lg disabled:opacity-50"
            >
              <span className="material-symbols-outlined">{isUploading ? 'sync' : 'upload'}</span>
            </button>
          </div>
          <input type="file" ref={fileInputRef} className="hidden" onChange={handleImageUpload} accept="image/*" />
        </div>

        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-xs font-black uppercase italic tracking-widest text-primary">Preços e Medidas</h2>
            <div className="flex gap-2">
              <button type="button" onClick={() => setShowPresets(!showPresets)} className="text-[10px] font-black uppercase text-blue-500 bg-blue-50 px-2 py-1 rounded">Presets</button>
              <button type="button" onClick={handleAddVariant} className="text-[10px] font-black uppercase text-primary">+ Novo Preço</button>
            </div>
          </div>

          {showPresets && presets.length > 0 && (
            <div className="p-3 bg-blue-50 dark:bg-blue-900/10 border border-blue-200 rounded-xl flex flex-wrap gap-2">
              {presets.map(p => (
                <button type="button" key={p.id} onClick={() => handleApplyPreset(p)} className="px-3 py-1.5 bg-white border text-[10px] font-bold rounded-lg shadow-sm">{p.name}</button>
              ))}
            </div>
          )}

          <div className="space-y-3">
            {variants.map(v => (
              <div key={v.id} className={`flex flex-col gap-2 p-3 bg-background-light dark:bg-black/20 rounded-xl border border-transparent focus-within:border-primary/30 transition-opacity ${!v.isActive ? 'opacity-50' : ''}`}>
                <div className="flex gap-2 items-center">
                  <input 
                    value={v.name} 
                    onChange={(e) => handleVariantChange(v.id, 'name', e.target.value)} 
                    className="flex-1 bg-transparent border-none p-0 text-sm font-bold outline-none" 
                    placeholder="Ex: Unitário ou 500g" 
                  />
                  <div className="flex gap-1">
                    <button 
                      type="button"
                      onClick={() => toggleVariantStatus(v.id)} 
                      className={`w-8 h-8 flex items-center justify-center rounded-lg transition-colors ${v.isActive ? 'text-green-500' : 'text-neutral-400'}`}
                    >
                      <span className="material-symbols-outlined text-sm">{v.isActive ? 'visibility' : 'visibility_off'}</span>
                    </button>
                    <button type="button" onClick={() => handleRemoveVariant(v.id)} className="w-8 h-8 flex items-center justify-center text-red-400">
                      <span className="material-symbols-outlined text-sm">delete</span>
                    </button>
                  </div>
                </div>
                <div className="flex items-center gap-1 font-black text-sm bg-white dark:bg-black/40 px-3 py-1.5 rounded-lg border">
                  <span className="text-neutral-500">R$</span>
                  <input 
                    type="number" 
                    step="0.01" 
                    value={v.price || ''} 
                    onChange={(e) => handleVariantChange(v.id, 'price', e.target.value)} 
                    className="w-full bg-transparent border-none p-0 outline-none" 
                    placeholder="0,00" 
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 w-full p-4 bg-white/95 dark:bg-surface-dark/95 backdrop-blur-md border-t flex gap-3 max-w-lg mx-auto left-1/2 -translate-x-1/2 z-50">
        <button type="button" onClick={onCancel} disabled={isSaving} className="flex-1 py-4 font-bold rounded-2xl border dark:border-white/10">Cancelar</button>
        <button type="button" onClick={handleSubmit} disabled={isSaving || isUploading} className="flex-[2] py-4 bg-primary text-black font-bold rounded-2xl shadow-lg active:scale-95 transition-all disabled:opacity-50">
          {isSaving ? 'Salvando...' : 'Salvar Alterações'}
        </button>
      </div>
    </div>
  );
};

export default AddProductForm;

import React, { useState, useEffect } from 'react';
import { Product, CartItem, AppView, ProductVariant, VariationPreset } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import CatalogView from './components/CatalogView';
import AdminView from './components/AdminView';
import AddProductForm from './components/AddProductForm';
import LoginView from './components/LoginView';
import EditCategoriesView from './components/EditCategoriesView';
import EditVariationsView from './components/EditVariationsView';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('catalog');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [productToEdit, setProductToEdit] = useState<Product | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);
  const [presets, setPresets] = useState<VariationPreset[]>([]);
  const [whatsappNumber, setWhatsappNumber] = useState<string>('5511999999999');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [clientName, setClientName] = useState(() => localStorage.getItem('catalog_client_name') || '');

  useEffect(() => {
    localStorage.setItem('catalog_client_name', clientName);
  }, [clientName]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let { data: dbProducts, error } = await supabase.from('products').select('*').order('order_index', { ascending: true });

      if (dbProducts && dbProducts.length > 0) {
        const normalized = dbProducts.map(p => ({
          ...p,
          isActive: p.is_active ?? p.isActive ?? true,
          variants: (Array.isArray(p.variants) ? p.variants : []).map((v: any) => ({
            ...v,
            isActive: v.isActive ?? v.is_active ?? true,
            price: Number(v.price)
          }))
        }));
        setProducts(normalized);
      } else {
        const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({ 
          ...p, 
          order_index: i,
          is_active: p.isActive,
          variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
        }));
        setProducts(seedProducts);
        await supabase.from('products').upsert(seedProducts);
      }

      const { data: dbSettings } = await supabase.from('settings').select('*');
      if (dbSettings) {
        const cats = dbSettings.find(s => s.key === 'categories')?.value;
        const wa = dbSettings.find(s => s.key === 'whatsapp')?.value;
        const pre = dbSettings.find(s => s.key === 'presets')?.value;
        if (cats) setCategories(cats);
        if (wa) setWhatsappNumber(wa);
        if (pre) setPresets(pre);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const formatError = (err: any): string => {
    if (!err) return "Erro desconhecido";
    if (typeof err === 'string') return err;

    // Tenta extrair mensagem de objetos de erro do Supabase ou Error nativo
    let message = err.message || "";
    let details = err.details || "";
    let hint = err.hint || "";

    if (!message && typeof err === 'object') {
      try {
        return JSON.stringify(err, null, 2);
      } catch {
        return "Erro de objeto não serializável";
      }
    }

    return `${message} ${details ? `\nDetalhes: ${details}` : ''} ${hint ? `\nSugestão: ${hint}` : ''}`.trim();
  };

  const saveProduct = async (product: Product) => {
    try {
      const orderIndex = productToEdit?.order_index !== undefined 
        ? productToEdit.order_index 
        : products.length;

      // Mapeamento rigoroso para as colunas do banco de dados
      const dbPayload = {
        id: product.id,
        name: product.name,
        description: product.description || "",
        image: product.image,
        category: product.category,
        variants: product.variants.map(v => ({
          id: v.id,
          name: v.name,
          price: Number(v.price),
          isActive: !!v.isActive
        })),
        is_active: !!product.isActive,
        order_index: orderIndex
      };

      const { error } = await supabase.from('products').upsert(dbPayload);

      if (error) throw error;

      // Atualiza o estado local para refletir as mudanças imediatamente
      const updatedLocalProduct = { 
        ...product, 
        order_index: orderIndex,
        isActive: !!product.isActive,
        variants: dbPayload.variants 
      };

      setProducts(prev => {
        const exists = prev.find(p => p.id === product.id);
        if (exists) return prev.map(p => p.id === product.id ? updatedLocalProduct : p);
        return [...prev, updatedLocalProduct];
      });

      setProductToEdit(null);
      setView('admin');
    } catch (err: any) {
      console.error("Erro ao salvar produto:", err);
      alert("Falha ao salvar:\n" + formatError(err));
    }
  };

  const toggleProductStatus = async (id: string) => {
    const product = products.find(p => p.id === id);
    if (!product) return;
    const newStatus = !product.isActive;

    setProducts(prev => prev.map(p => p.id === id ? { ...p, isActive: newStatus } : p));

    try { 
      await supabase.from('products').update({ is_active: newStatus }).eq('id', id); 
    } catch (e) {
      console.error("Erro ao alternar status do produto:", e);
    }
  };

  const handleReorderProduct = async (id: string, direction: 'up' | 'down') => {
    const index = products.findIndex(p => p.id === id);
    if (index === -1) return;
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= products.length) return;

    const newProducts = [...products];
    const itemA = { ...newProducts[index] };
    const itemB = { ...newProducts[targetIndex] };

    itemA.order_index = targetIndex;
    itemB.order_index = index;

    newProducts[index] = itemB;
    newProducts[targetIndex] = itemA;

    setProducts(newProducts);

    try {
      await Promise.all([
        supabase.from('products').update({ order_index: targetIndex }).eq('id', itemA.id),
        supabase.from('products').update({ order_index: index }).eq('id', itemB.id)
      ]);
    } catch (e) {
      console.error("Erro ao reordenar produtos:", e);
    }
  };

  const toggleVariantStatus = async (productId: string, variantId: string) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;

    const updatedVariants = product.variants.map(v => 
      v.id === variantId ? { ...v, isActive: !v.isActive } : v
    );

    setProducts(prev => prev.map(p => 
      p.id === productId ? { ...p, variants: updatedVariants } : p
    ));

    try {
      await supabase.from('products').update({ variants: updatedVariants }).eq('id', productId);
    } catch (e) {
      console.error("Erro ao alternar status da variação:", e);
    }
  };

  const deleteProduct = async (id: string) => {
    if (!confirm("Excluir este produto permanentemente?")) return;
    try {
      const { error } = await supabase.from('products').delete().eq('id', id);
      if (error) throw error;
      setProducts(prev => prev.filter(p => p.id !== id));
    } catch (err) {
      alert("Erro ao excluir: " + formatError(err));
    }
  };

  const handleResetToDefaults = async () => {
    if (!confirm("Isso apagará todas as suas alterações e voltará ao catálogo original. Deseja continuar?")) return;
    setIsLoading(true);
    try {
      await supabase.from('products').delete().neq('id', '0');
      const seedProducts = INITIAL_PRODUCTS.map((p, i) => ({
        ...p,
        order_index: i,
        is_active: p.isActive,
        variants: p.variants.map(v => ({ ...v, is_active: v.isActive }))
      }));
      await supabase.from('products').upsert(seedProducts);
      await fetchData();
    } catch (err) {
      alert("Erro ao restaurar: " + formatError(err));
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateWhatsapp = async (num: string) => { 
    setWhatsappNumber(num); 
    await supabase.from('settings').upsert({ key: 'whatsapp', value: num }); 
  };

  const handleUpdateCategories = async (newCats: any) => { 
    const updated = typeof newCats === 'function' ? newCats(categories) : newCats;
    setCategories(updated); 
    await supabase.from('settings').upsert({ key: 'categories', value: updated }); 
  };

  const handleUpdatePresets = async (newPresets: any) => {
    const updated = typeof newPresets === 'function' ? newPresets(presets) : newPresets;
    setPresets(updated); 
    await supabase.from('settings').upsert({ key: 'presets', value: updated });
  };

  const addToCart = (product: Product, variantId: string) => {
    const variant = product.variants.find(v => v.id === variantId);
    if (!variant || !variant.isActive) return;
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id && item.variantId === variantId);
      if (existing) return prev.map(item => (item.productId === product.id && item.variantId === variantId) ? { ...item, quantity: item.quantity + 1 } : item);
      return [...prev, { productId: product.id, variantId, quantity: 1, productName: product.name, variantName: variant.name, price: variant.price }];
    });
  };

  const removeFromCart = (productId: string, variantId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === productId && item.variantId === variantId);
      if (existing && existing.quantity > 1) return prev.map(item => (item.productId === productId && item.variantId === variantId) ? { ...item, quantity: item.quantity - 1 } : item);
      return prev.filter(item => !(item.productId === productId && item.variantId === variantId));
    });
  };

  const handleSendWhatsApp = (paymentMethod: string) => {
    if (!clientName || clientName.trim().length < 3) { alert('Por favor, insira seu nome antes de enviar o pedido.'); return; }
    const cartText = cart.map(item => `• *${item.quantity}x* ${item.productName} (${item.variantName}) - R$ ${(item.price * item.quantity).toFixed(2)}`).join('\n');
    const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const message = `*NOVO PEDIDO*\n👤 *Cliente:* ${clientName}\n💳 *Pagamento:* ${paymentMethod}\n\n🛒 *Itens:*\n${cartText}\n\n💰 *Total:* R$ ${total.toFixed(2)}`;
    window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen flex flex-col">
      {isLoading && view === 'catalog' ? (
        <div className="min-h-screen bg-background-light dark:bg-background-dark flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-6"></div>
          <h2 className="text-xl font-black uppercase text-neutral-900 dark:text-white tracking-widest mb-2">Doce Mania</h2>
          <p className="font-bold animate-pulse text-primary text-sm uppercase italic">Sincronizando Catálogo...</p>
        </div>
      ) : (
        <>
          {view === 'catalog' && (
            <CatalogView 
              products={products.filter(p => p.isActive)} 
              categories={categories} cart={cart} addToCart={addToCart} removeFromCart={removeFromCart}
              clientName={clientName} setClientName={setClientName} onSendWhatsApp={handleSendWhatsApp} onOpenSettings={() => isAuthenticated ? setView('admin') : setView('login')}
            />
          )}
          {view === 'login' && <LoginView onLogin={(pw) => { if(pw === '233023'){ setIsAuthenticated(true); setView('admin'); return true; } return false; }} onBack={() => setView('catalog')} />}
          {view === 'admin' && (
            <AdminView 
              products={products} whatsappNumber={whatsappNumber} setWhatsappNumber={handleUpdateWhatsapp}
              onToggleStatus={toggleProductStatus} onToggleVariantStatus={toggleVariantStatus} onReorderProduct={handleReorderProduct}
              onAddProduct={() => { setProductToEdit(null); setView('add-product'); }} onEditProduct={(p) => { setProductToEdit(p); setView('edit-product'); }}
              onDeleteProduct={deleteProduct}
              onOpenCategories={() => setView('edit-categories')}
              onOpenVariations={() => setView('edit-variations')}
              onResetToDefaults={handleResetToDefaults}
              onBack={() => setView('catalog')} onLogout={() => { setIsAuthenticated(false); setView('catalog'); }}
            />
          )}
          {(view === 'add-product' || view === 'edit-product') && (
            <AddProductForm 
              categories={categories} 
              presets={presets}
              productToEdit={productToEdit} 
              onSave={saveProduct} 
              onCancel={() => setView('admin')} 
            />
          )}
          {view === 'edit-categories' && <EditCategoriesView categories={categories} setCategories={handleUpdateCategories} onBack={() => setView('admin')} />}
          {view === 'edit-variations' && <EditVariationsView presets={presets} setPresets={handleUpdatePresets} onBack={() => setView('admin')} />}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductVariant, VariationPreset } from '../types';
import { supabase } from '../supabase';

interface AddProductFormProps {
  categories: string[];
  presets: VariationPreset[];
  productToEdit: Product | null;
  onSave: (product: Product) => Promise<void>;
  onCancel: () => void;
}

const AddProductForm: React.FC<AddProductFormProps> = ({ categories, presets, productToEdit, onSave, onCancel }) => {
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [variants, setVariants] = useState<ProductVariant[]>([{ id: Date.now().toString(), name: 'Padrão', price: 0, isActive: true }]);
  const [showPresets, setShowPresets] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (productToEdit) {
      setName(productToEdit.name);
      setCategory(productToEdit.category);
      setDescription(productToEdit.description || '');
      setImage(productToEdit.image);
      setVariants(productToEdit.variants.map(v => ({
        ...v, 
        price: Number(v.price), 
        isActive: v.isActive ?? true
      })));
    }
  }, [productToEdit]);

  const handleImageInput = (val: string) => {
    let raw = val.trim();
    if (raw.includes('<') && raw.includes('src=')) {
      const srcMatch = raw.match(/src=["']?([^"'\s>]+)["']?/i);
      if (srcMatch && srcMatch[1]) {
        raw = srcMatch[1];
      }
    }
    setImage(raw);
  };

  const handleApplyPreset = (preset: VariationPreset) => {
    const newVariants = preset.variants.map(v => ({
      ...v,
      id: Math.random().toString(36).substr(2, 9),
      isActive: true
    }));
    setVariants(newVariants);
    setShowPresets(false);
  };

  const handleAddVariant = () => {
    setVariants([...variants, { id: Date.now().toString(), name: '', price: 0, isActive: true }]);
  };

  const handleRemoveVariant = (id: string) => {
    if (variants.length <= 1) {
      alert('O produto precisa ter pelo menos um preço.');
      return;
    }
    setVariants(prev => prev.filter(v => v.id !== id));
  };

  const handleVariantChange = (id: string, field: keyof ProductVariant, value: any) => {
    setVariants(prev => prev.map(v => {
      if (v.id === id) {
        let newValue = value;
        if (field === 'price') {
          // Permite digitação mas limpa para número
          newValue = value === '' ? 0 : parseFloat(value);
        }
        return { ...v, [field]: newValue };
      }
      return v;
    }));
  };

  const toggleVariantStatus = (id: string) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, isActive: !v.isActive } : v));
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsUploading(true);
    try {
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
      const { error: uploadError } = await supabase.storage.from('product-images').upload(`products/${fileName}`, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('product-images').getPublicUrl(`products/${fileName}`);
      setImage(data.publicUrl);
    } catch (error: any) {
      alert('Falha no upload: ' + (error.message || 'Erro desconhecido.'));
    } finally { setIsUploading(false); }
  };

  const handleSubmit = async () => {
    if (!name.trim()) { 
      alert('O nome do item é obrigatório!'); 
      return; 
    }
    if (!category) {
      alert('Selecione uma marca/categoria!');
      return;
    }

    setIsSaving(true);
    try {
      const cleanVariants = variants.map(v => ({ 
        id: v.id,
        name: v.name.trim() || 'Padrão',
        price: Number(v.price) || 0,
        isActive: !!v.isActive
      }));

      const productData: Product = {
        id: productToEdit ? productToEdit.id : String(Date.now()), 
        name: name.trim(), 
        category, 
        description: description.trim(),
        image: image.trim() || 'https://picsum.photos/400/300?text=Doce+Mania',
        isActive: productToEdit ? productToEdit.isActive : true,
        variants: cleanVariants
      };

      await onSave(productData);
    } catch (err: any) {
      console.error("Erro no formulário:", err);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex-1 w-full max-w-lg mx-auto bg-background-light dark:bg-background-dark min-h-screen pb-32">
      <div className="sticky top-0 z-30 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md border-b border-border-light dark:border-border-dark px-4 py-3 flex items-center gap-3">
        <button onClick={onCancel} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-black/5 dark:hover:bg-white/5 active:scale-90 transition-all">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <h1 className="text-lg font-bold">{productToEdit ? 'Editar Produto' : 'Novo Item'}</h1>
      </div>

      <div className="px-4 pt-6 flex flex-col gap-6">
        {/* Informações Básicas */}
        <div className="bg-white dark:bg-white/5 p-5 rounded-2xl border border-border-light dark:border-border-dark shadow-sm space-y-4">
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Nome do Item</label>
            <input 
              value={name} 
              onChange={(e) => setName(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm font-bold focus:ring-primary outline-none transition-all" 
              placeholder="Ex: Coca-Cola 350ml" 
            />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-primary mb-1.5 tracking-widest italic">Marca / Categoria</label>
            <select 
              value={category} 
              onChange={(e) => setCategory(e.target.value)} 
              className="w-full rounded-xl border-border-light dark:border-border-dark bg-background-light dark:bg-black/20 p-3 text-sm font-bold outline-none"
            >
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
          <div>
